from (values
(392169,43575,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, angeblich ... die Taube mit geschlossenen Augen, als die Henne ihren Stock schwang.'::text,'lächelte'::text,'lächelte'::text,'hat gelächelt'::text,'Mädel, angeblich lächelte die Taube mit geschlossenen Augen, als die Henne ihren Stock schwang.'::text),
(392173,43575,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, голуб ... із заплющеними очима, коли курка змахнула палицею.'::text,'усміхався'::text,'усміхнувся'::text,'усміхнувся'::text,'Подруго, кажуть, голуб усміхався із заплющеними очима, коли курка змахнула палицею.'::text),
(392172,43575,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, al parecer la paloma ... con los ojos cerrados cuando la gallina blandió su palo.'::text,'estaba sonriendo'::text,'sonrió'::text,'ha sonreído'::text,'Tía, al parecer la paloma estaba sonriendo con los ojos cerrados cuando la gallina blandió su palo.'::text),
(392171,43575,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, apparemment le pigeon ... les yeux fermés quand la poule a brandi son bâton.'::text,'souriait'::text,'a souri'::text,'a souri'::text,'Meuf, apparemment le pigeon souriait les yeux fermés quand la poule a brandi son bâton.'::text),
(392174,43575,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, güya tavuk sopasını salladığında güvercin gözleri kapalı ...'::text,'gülümsüyordu'::text,'gülümsedi'::text,'gülümsemiş'::text,'Kızım, güya tavuk sopasını salladığında güvercin gözleri kapalı gülümsüyordu.'::text),
(392175,43575,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag a galamb csukott szemmel ..., amikor a tyúk meglendítette a botját.'::text,'mosolygott'::text,'elmosolyodott'::text,'elmosolyodott'::text,'Csajszi, állítólag a galamb csukott szemmel mosolygott, amikor a tyúk meglendítette a botját.'::text),
(392178,43576,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör mal, ich hab gehört, dass die Henne schon die ganze Woche ihren Stock gegen Tauben ...'::text,'schwingt'::text,'schwingt'::text,'schwingt'::text,'Hör mal, ich hab gehört, dass die Henne schon die ganze Woche ihren Stock gegen Tauben schwingt.'::text),
(392182,43576,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, я чула, що ця курка весь тиждень ... палицею на голубів.'::text,'махає'::text,'махає'::text,'махає'::text,'Слухай, я чула, що ця курка весь тиждень махає палицею на голубів.'::text),
(392181,43576,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, me han dicho que esa gallina ... su palo contra las palomas toda la semana.'::text,'lleva blandiendo'::text,'está blandiendo'::text,'blande'::text,'Oye, me han dicho que esa gallina lleva blandiendo su palo contra las palomas toda la semana.'::text),
(392180,43576,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, j''ai entendu dire que cette poule ... son bâton sur les pigeons toute la semaine.'::text,'agite'::text,'agite'::text,'agite'::text,'Écoute, j''ai entendu dire que cette poule agite son bâton sur les pigeons toute la semaine.'::text),
(392183,43576,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, duydum ki o tavuk bütün hafta güvercinlere sopasını ...'::text,'sallıyormuş'::text,'sallıyor'::text,'sallar'::text,'Dinle, duydum ki o tavuk bütün hafta güvercinlere sopasını sallıyormuş.'::text),
(392184,43576,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt hallottam, hogy az a tyúk egész héten ... a botjával a galambok felé.'::text,'hadonászik'::text,'hadonászik'::text,'hadonászik'::text,'Figyelj, azt hallottam, hogy az a tyúk egész héten hadonászik a botjával a galambok felé.'::text),
(392187,43577,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Taube ... friedlich, als der Stock der Henne auf ihrem Schnabel landete. Eindeutig ein schöner Tag.'::text,'döste'::text,'döste'::text,'hat gedöst'::text,'Die Taube döste friedlich, als der Stock der Henne auf ihrem Schnabel landete. Eindeutig ein schöner Tag.'::text),
(392191,43577,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Голуб спокійно ..., коли палиця курки приземлилася йому на дзьоб. Явно чудовий день.'::text,'дрімав'::text,'задрімав'::text,'задрімав'::text,'Голуб спокійно дрімав, коли палиця курки приземлилася йому на дзьоб. Явно чудовий день.'::text),
(392190,43577,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La paloma ... tranquilamente cuando el palo de la gallina le cayó en el pico. Claramente, un día estupendo.'::text,'estaba dormitando'::text,'dormitó'::text,'ha dormitado'::text,'La paloma estaba dormitando tranquilamente cuando el palo de la gallina le cayó en el pico. Claramente, un día estupendo.'::text),
(392189,43577,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le pigeon ... paisiblement quand le bâton de la poule a atterri sur son bec. Clairement une belle journée.'::text,'somnolait'::text,'a somnolé'::text,'a somnolé'::text,'Le pigeon somnolait paisiblement quand le bâton de la poule a atterri sur son bec. Clairement une belle journée.'::text),
(392192,43577,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Güvercin huzur içinde ..., tavuğun sopası gagasına indiğinde. Belli ki harika bir gün.'::text,'uyukluyordu'::text,'uyukladı'::text,'uyuklamış'::text,'Güvercin huzur içinde uyukluyordu, tavuğun sopası gagasına indiğinde. Belli ki harika bir gün.'::text),
(392193,43577,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A galamb békésen ..., amikor a tyúk botja a csőrén landolt. Nyilván remek nap.'::text,'szundikált'::text,'elszundított'::text,'elszundított'::text,'A galamb békésen szundikált, amikor a tyúk botja a csőrén landolt. Nyilván remek nap.'::text),
(392196,43578,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Henne ... den Stock schon dreimal gegen die Taube. So ruhig, offensichtlich.'::text,'schwang'::text,'schwingt'::text,'schwang'::text,'Die Henne schwang den Stock schon dreimal gegen die Taube. So ruhig, offensichtlich.'::text),
(392200,43578,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Курка вже тричі ... тією палицею на голуба. Така спокійна, очевидно.'::text,'замахнулася'::text,'замахувалася'::text,'замахнулася'::text,'Курка вже тричі замахнулася тією палицею на голуба. Така спокійна, очевидно.'::text),
(392199,43578,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La gallina ya ... ese palo contra la paloma tres veces. Qué tranquila, obviamente.'::text,'ha blandido'::text,'ha estado blandiendo'::text,'blandió'::text,'La gallina ya ha blandido ese palo contra la paloma tres veces. Qué tranquila, obviamente.'::text),
(392198,43578,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La poule ... ce bâton vers le pigeon trois fois déjà. Tellement calme, évidemment.'::text,'a brandi'::text,'brandit'::text,'a brandi'::text,'La poule a brandi ce bâton vers le pigeon trois fois déjà. Tellement calme, évidemment.'::text),
(392201,43578,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tavuk o sopayı şimdiden üç kez güvercine ..., çok sakin tabii.'::text,'salladı'::text,'sallıyor'::text,'salladı'::text,'Tavuk o sopayı şimdiden üç kez güvercine salladı, çok sakin tabii.'::text),
(392202,43578,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tyúk már háromszor ... azt a botot a galambra. Milyen nyugodt, nyilván.'::text,'meglendítette'::text,'lengette'::text,'meglendítette'::text,'A tyúk már háromszor meglendítette azt a botot a galambra. Milyen nyugodt, nyilván.'::text),
(392205,43579,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, das Küken ... – noch bevor die Henne überhaupt ihren Stock fallen ließ, echt jetzt.'::text,'war eingepennt'::text,'ist eingepennt'::text,'pennt ein'::text,'Digga, das Küken war eingepennt – noch bevor die Henne überhaupt ihren Stock fallen ließ, echt jetzt.'::text),
(392209,43579,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, курча ... ще до того, як курка взагалі кинула палицю, реально.'::text,'заснуло'::text,'заснуло'::text,'засинає'::text,'Бро, курча заснуло ще до того, як курка взагалі кинула палицю, реально.'::text),
(392208,43579,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, el pollito ya se ... antes de que la gallina soltara el palo, en serio.'::text,'había dormido'::text,'ha dormido'::text,'duerme'::text,'Bro, el pollito ya se había dormido antes de que la gallina soltara el palo, en serio.'::text),
(392207,43579,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, le poussin ... avant même que la poule lâche son bâton, sérieux.'::text,'s''était endormi'::text,'s''est endormi'::text,'s''endort'::text,'Frérot, le poussin s''était endormi avant même que la poule lâche son bâton, sérieux.'::text),
(392210,43579,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, tavuk daha sopasını bırakmadan civciv çoktan ..., cidden.'::text,'uyuyakalmıştı'::text,'uyuyakaldı'::text,'uyuyor'::text,'Kanka, tavuk daha sopasını bırakmadan civciv çoktan uyuyakalmıştı, cidden.'::text),
(392211,43579,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, a csibe már ..., mielőtt a tyúk egyáltalán leejtette volna a botját, komolyan.'::text,'elaludt'::text,'elaludt'::text,'elalszik'::text,'Tesó, a csibe már elaludt, mielőtt a tyúk egyáltalán leejtette volna a botját, komolyan.'::text),
(392214,43580,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, wenn die Henne den Stock nochmal hebt, ... die Taube, kein Witz.'::text,'flieht'::text,'würde fliehen'::text,'floh'::text,'Yo, wenn die Henne den Stock nochmal hebt, flieht die Taube, kein Witz.'::text),
(392218,43580,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, якщо курка знову підніме ту палицю, голуб ..., без брехні.'::text,'відлетить'::text,'відлетів би'::text,'відлетів'::text,'Йо, якщо курка знову підніме ту палицю, голуб відлетить, без брехні.'::text),
(392217,43580,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, si la gallina vuelve a levantar ese palo, la paloma ... volando, te lo juro.'::text,'saldrá'::text,'saldría'::text,'salió'::text,'Oye, si la gallina vuelve a levantar ese palo, la paloma saldrá volando, te lo juro.'::text),
(392216,43580,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wesh, si la poule relève ce bâton, le pigeon ..., sans mentir.'::text,'s''envolera'::text,'s''envolerait'::text,'s''est envolé'::text,'Wesh, si la poule relève ce bâton, le pigeon s''envolera, sans mentir.'::text),
(392219,43580,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, tavuk o sopayı bir daha kaldırırsa güvercin ..., yalan yok.'::text,'uçup gider'::text,'uçup giderdi'::text,'uçup gitti'::text,'Kanka, tavuk o sopayı bir daha kaldırırsa güvercin uçup gider, yalan yok.'::text),
(392220,43580,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyu, ha a tyúk még egyszer felemeli azt a botot, a galamb ..., nem viccelek.'::text,'elrepül'::text,'elrepülne'::text,'elrepült'::text,'Figyu, ha a tyúk még egyszer felemeli azt a botot, a galamb elrepül, nem viccelek.'::text),
(392223,43581,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn die Henne ein Meeting abhielte, statt ihren Stock zu benutzen, ... die Taube 100 % ruhiger.'::text,'wäre'::text,'wird'::text,'ist'::text,'Wenn die Henne ein Meeting abhielte, statt ihren Stock zu benutzen, wäre die Taube 100 % ruhiger.'::text),
(392227,43581,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби курка провела нараду замість того, щоб користуватися палицею, голуб ... на 100 % спокійнішим.'::text,'був би'::text,'буде'::text,'є'::text,'Якби курка провела нараду замість того, щоб користуватися палицею, голуб був би на 100 % спокійнішим.'::text),
(392226,43581,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la gallina hiciera una reunión en lugar de usar su palo, la paloma ... un 100 % más tranquila.'::text,'estaría'::text,'estará'::text,'está'::text,'Si la gallina hiciera una reunión en lugar de usar su palo, la paloma estaría un 100 % más tranquila.'::text),
(392225,43581,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la poule organisait une réunion au lieu d''utiliser son bâton, le pigeon ... 100 % plus calme.'::text,'serait'::text,'sera'::text,'est'::text,'Si la poule organisait une réunion au lieu d''utiliser son bâton, le pigeon serait 100 % plus calme.'::text),
(392228,43581,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tavuk sopasını kullanmak yerine toplantı yapsaydı, güvercin %100 daha sakin ...'::text,'olurdu'::text,'olacak'::text,NULL::text,'Tavuk sopasını kullanmak yerine toplantı yapsaydı, güvercin %100 daha sakin olurdu.'::text),
(392229,43581,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a tyúk a botja helyett megbeszélést tartana, a galamb 100%-kal nyugodtabb ...'::text,'lenne'::text,'lesz'::text,NULL::text,'Ha a tyúk a botja helyett megbeszélést tartana, a galamb 100%-kal nyugodtabb lenne.'::text),
(392232,43582,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die arme Taube ... – mit einem Stock, mitten im Park. Ein totaler Albtraum!'::text,'wurde bedroht'::text,'bedrohte'::text,'bedroht'::text,'Die arme Taube wurde bedroht – mit einem Stock, mitten im Park. Ein totaler Albtraum!'::text),
(392236,43582,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бідолашному голубу ... палицею посеред парку. Суцільний кошмар!'::text,'погрожували'::text,'погрожував'::text,'погрожує'::text,'Бідолашному голубу погрожували палицею посеред парку. Суцільний кошмар!'::text),
(392235,43582,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La pobre paloma ... con un palo en medio del parque. ¡Una pesadilla total!'::text,'fue amenazada'::text,'amenazó'::text,'está amenazando'::text,'La pobre paloma fue amenazada con un palo en medio del parque. ¡Una pesadilla total!'::text),
(392234,43582,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le pauvre pigeon ... avec un bâton en plein milieu du parc. Un cauchemar total !'::text,'a été menacé'::text,'a menacé'::text,'menace'::text,'Le pauvre pigeon a été menacé avec un bâton en plein milieu du parc. Un cauchemar total !'::text),
(392237,43582,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Zavallı güvercin parkın ortasında sopayla ..., tam bir kâbus!'::text,'tehdit edildi'::text,'tehdit etti'::text,'tehdit ediyor'::text,'Zavallı güvercin parkın ortasında sopayla tehdit edildi, tam bir kâbus!'::text),
(392238,43582,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szegény galambot ... egy bottal a park közepén. Totális rémálom!'::text,'megfenyegették'::text,'megfenyegette'::text,'fenyegeti'::text,'Szegény galambot megfenyegették egy bottal a park közepén. Totális rémálom!'::text),
(392250,43584,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Henne ... sehr wütend sein; sie schwingt einen Stock gegen die Taube.'::text,'muss'::text,'könnte'::text,'sollte'::text,'Die Henne muss sehr wütend sein; sie schwingt einen Stock gegen die Taube.'::text),
(392254,43584,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Курка ... бути дуже злою; вона махає палицею на голуба.'::text,'мусить'::text,'може'::text,'повинна'::text,'Курка мусить бути дуже злою; вона махає палицею на голуба.'::text),
(392253,43584,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La gallina ... estar muy enfadada; está blandiendo un palo contra la paloma.'::text,'debe de'::text,'podría'::text,'debería'::text,'La gallina debe de estar muy enfadada; está blandiendo un palo contra la paloma.'::text),
(392252,43584,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La poule ... être très en colère ; elle agite un bâton vers le pigeon.'::text,'doit'::text,'pourrait'::text,'devrait'::text,'La poule doit être très en colère ; elle agite un bâton vers le pigeon.'::text),
(392255,43584,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tavuk çok kızgın ...; güvercine sopa sallıyor.'::text,'olmalı'::text,'olabilir'::text,'olması gerek'::text,'Tavuk çok kızgın olmalı; güvercine sopa sallıyor.'::text),
(392256,43584,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tyúk ... nagyon dühös; bottal hadonászik a galamb felé.'::text,'biztosan'::text,'talán'::text,'elvileg'::text,'A tyúk biztosan nagyon dühös; bottal hadonászik a galamb felé.'::text),
(392259,43585,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Küken, ... unter dem Stock schläft, ist sehr klein.'::text,'das'::text,'dessen'::text,'was'::text,'Das Küken, das unter dem Stock schläft, ist sehr klein.'::text),
(392263,43585,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Курча, ... спить під палицею, дуже маленьке.'::text,'яке'::text,'чиє'::text,'що'::text,'Курча, яке спить під палицею, дуже маленьке.'::text),
(392262,43585,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El pollito ... duerme bajo el palo es muy pequeño.'::text,'que'::text,'cuyo'::text,'lo que'::text,'El pollito que duerme bajo el palo es muy pequeño.'::text),
(392261,43585,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le poussin ... dort sous le bâton est tout petit.'::text,'qui'::text,'dont'::text,'ce qui'::text,'Le poussin qui dort sous le bâton est tout petit.'::text),
(392264,43585,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sopanın altında ... civciv çok küçük.'::text,'uyuyan'::text,'kimin'::text,'ne'::text,'Sopanın altında uyuyan civciv çok küçük.'::text),
(392265,43585,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A csibe, ... a bot alatt alszik, nagyon kicsi.'::text,'amelyik'::text,'akinek a'::text,'ami'::text,'A csibe, amelyik a bot alatt alszik, nagyon kicsi.'::text),
(374205,41579,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... übers Bett zu den Kissen, als sich die Bettdecke zusammenschob. Anmutig, eindeutig.'::text,'krabbelte'::text,'krabbelte'::text,'ist gekrabbelt'::text,'Sie krabbelte übers Bett zu den Kissen, als sich die Bettdecke zusammenschob. Anmutig, eindeutig.'::text),
(374209,41579,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... ліжком до подушок, коли ковдра зібралася в купу. Граціозно, явно.'::text,'повзла'::text,'проповзла'::text,'проповзла'::text,'Вона повзла ліжком до подушок, коли ковдра зібралася в купу. Граціозно, явно.'::text),
(374208,41579,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... por la cama hacia las almohadas cuando el edredón se arrugó. Qué elegancia, claramente.'::text,'estaba gateando'::text,'gateó'::text,'ha gateado'::text,'Ella estaba gateando por la cama hacia las almohadas cuando el edredón se arrugó. Qué elegancia, claramente.'::text),
(374207,41579,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... sur le lit vers les oreillers quand la couette s''est tassée. Gracieux, clairement.'::text,'rampait'::text,'a rampé'::text,'a rampé'::text,'Elle rampait sur le lit vers les oreillers quand la couette s''est tassée. Gracieux, clairement.'::text),
(374210,41579,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O yatakta yastıklara doğru ..., yorgan toplandığında. Zarif, belli ki.'::text,'sürünüyordu'::text,'süründü'::text,'sürünmüş'::text,'O yatakta yastıklara doğru sürünüyordu, yorgan toplandığında. Zarif, belli ki.'::text),
(374211,41579,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő éppen az ágyon ... a párnák felé, amikor a paplan összegyűrődött. Kecses, nyilván.'::text,'mászott'::text,'felmászott'::text,'felmászott'::text,'Ő éppen az ágyon mászott a párnák felé, amikor a paplan összegyűrődött. Kecses, nyilván.'::text),
(374214,41580,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... schon eine ganze Minute auf diese sieben Kissen zu. Wirklich ein kurzer Trip.'::text,'krabbelt'::text,'krabbelt'::text,'krabbelt'::text,'Sie krabbelt schon eine ganze Minute auf diese sieben Kissen zu. Wirklich ein kurzer Trip.'::text),
(374218,41580,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... до тих семи подушок уже цілу хвилину. Справді швидка подорож.'::text,'повзе'::text,'повзе'::text,'повзе'::text,'Вона повзе до тих семи подушок уже цілу хвилину. Справді швидка подорож.'::text),
(374217,41580,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... hacia esas siete almohadas un minuto entero. Un viaje rapidísimo, de verdad.'::text,'lleva gateando'::text,'está gateando'::text,'gatea'::text,'Ella lleva gateando hacia esas siete almohadas un minuto entero. Un viaje rapidísimo, de verdad.'::text),
(374216,41580,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... vers ces sept oreillers depuis une minute entière. Vraiment un trajet express.'::text,'rampe'::text,'rampe'::text,'rampe'::text,'Elle rampe vers ces sept oreillers depuis une minute entière. Vraiment un trajet express.'::text),
(374219,41580,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Koca bir dakikadır o yedi yastığa doğru ..., gerçekten hızlı bir yolculuk.'::text,'sürünüyor'::text,'sürünüyor'::text,'sürünür'::text,'Koca bir dakikadır o yedi yastığa doğru sürünüyor, gerçekten hızlı bir yolculuk.'::text),
(374220,41580,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Már egy teljes perce ... a hét párna felé. Tényleg gyors kirándulás.'::text,'mászik'::text,'mászik'::text,'mászik'::text,'Már egy teljes perce mászik a hét párna felé. Tényleg gyors kirándulás.'::text),
(374232,41582,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jemand ... sieben weiße Kissen am Kopfende des Bettes auf.'::text,'reihte'::text,'reiht'::text,'reiht'::text,'Jemand reihte sieben weiße Kissen am Kopfende des Bettes auf.'::text),
(374236,41582,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Хтось ... сім білих подушок уздовж узголів''я ліжка.'::text,'виставив у ряд'::text,'виставляв'::text,'виставляє'::text,'Хтось виставив у ряд сім білих подушок уздовж узголів''я ліжка.'::text),
(374235,41582,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alguien ... siete almohadas blancas a lo largo de la cabecera de la cama.'::text,'ha colocado en fila'::text,'ha estado colocando'::text,'coloca'::text,'Alguien ha colocado en fila siete almohadas blancas a lo largo de la cabecera de la cama.'::text),
(374234,41582,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quelqu''un ... sept oreillers blancs le long de la tête du lit.'::text,'a aligné'::text,'aligne'::text,'aligne'::text,'Quelqu''un a aligné sept oreillers blancs le long de la tête du lit.'::text),
(374237,41582,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Biri yatağın başucu boyunca yedi beyaz yastığı ...'::text,'sıralamış'::text,'sıralıyormuş'::text,'sıralar'::text,'Biri yatağın başucu boyunca yedi beyaz yastığı sıralamış.'::text),
(374238,41582,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Valaki ... hét fehér párnát az ágy támlája mentén.'::text,'sorba rakott'::text,'rakosgatott'::text,'sorba rak'::text,'Valaki sorba rakott hét fehér párnát az ágy támlája mentén.'::text),
(374241,41583,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als sie die Kissen erreichte, ... die Bettdecke hinter ihr schon in langen Falten.'::text,'lag'::text,'hat gelegen'::text,'liegt'::text,'Als sie die Kissen erreichte, lag die Bettdecke hinter ihr schon in langen Falten.'::text),
(374245,41583,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки вона дісталася подушок, ковдра позаду неї вже ... довгими складками.'::text,'зібралася'::text,'зібралася'::text,'збирається'::text,'Поки вона дісталася подушок, ковдра позаду неї вже зібралася довгими складками.'::text),
(374244,41583,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando llegó a las almohadas, el edredón ya se ... en largos pliegues detrás de ella.'::text,'había recogido'::text,'ha recogido'::text,'recoge'::text,'Para cuando llegó a las almohadas, el edredón ya se había recogido en largos pliegues detrás de ella.'::text),
(374243,41583,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le temps qu''elle atteigne les oreillers, la couette ... en longs plis derrière elle.'::text,'s''était rassemblée'::text,'s''est rassemblée'::text,'se rassemble'::text,'Le temps qu''elle atteigne les oreillers, la couette s''était rassemblée en longs plis derrière elle.'::text),
(374246,41583,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O yastıklara ulaştığında yorgan arkasında çoktan uzun kıvrımlar halinde ...'::text,'toplanmıştı'::text,'toplandı'::text,'toplanıyor'::text,'O yastıklara ulaştığında yorgan arkasında çoktan uzun kıvrımlar halinde toplanmıştı.'::text),
(374247,41583,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire elérte a párnákat, a paplan mögötte már hosszú redőkbe ...'::text,'gyűrődött'::text,'gyűrődött'::text,'gyűrődik'::text,'Mire elérte a párnákat, a paplan mögötte már hosszú redőkbe gyűrődött.'::text),
(374250,41584,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen um diese Zeit ... sie auf diesen sieben Kissen.'::text,'schläft'::text,'wird schlafen'::text,'schläft'::text,'Morgen um diese Zeit schläft sie auf diesen sieben Kissen.'::text),
(374254,41584,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра в цей час вона ... на цих семи подушках.'::text,'спатиме'::text,'спатиме'::text,'спить'::text,'Завтра в цей час вона спатиме на цих семи подушках.'::text),
(374253,41584,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mañana a esta hora, ella ... en estas siete almohadas.'::text,'estará durmiendo'::text,'dormirá'::text,'duerme'::text,'Mañana a esta hora, ella estará durmiendo en estas siete almohadas.'::text),
(374252,41584,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain à cette heure-ci, elle ... sur ces sept oreillers.'::text,'dormira'::text,'dormira'::text,'dort'::text,'Demain à cette heure-ci, elle dormira sur ces sept oreillers.'::text),
(374255,41584,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın bu saatlerde o bu yedi yastıkta ...'::text,'uyuyor olacak'::text,'uyuyacak'::text,'uyuyor'::text,'Yarın bu saatlerde o bu yedi yastıkta uyuyor olacak.'::text),
(374256,41584,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap ilyenkor ő ezen a hét párnán ...'::text,'fog aludni'::text,'alszik majd'::text,'alszik'::text,'Holnap ilyenkor ő ezen a hét párnán fog aludni.'::text),
(374259,41585,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sieben Kissen? Okay, ich ... das mittlere, weil das mittlere in der Mitte ist.'::text,'nehme'::text,'werde nehmen'::text,'nehme gerade'::text,'Sieben Kissen? Okay, ich nehme das mittlere, weil das mittlere in der Mitte ist.'::text),
(374263,41585,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Сім подушок? Гаразд, я ... середню, бо середня посередині.'::text,'візьму'::text,'братиму'::text,'беру'::text,'Сім подушок? Гаразд, я візьму середню, бо середня посередині.'::text),
(374262,41585,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿Siete almohadas? Vale, yo ... la del medio, porque la del medio está en el medio.'::text,'cogeré'::text,'estaré cogiendo'::text,'estoy cogiendo'::text,'¿Siete almohadas? Vale, yo cogeré la del medio, porque la del medio está en el medio.'::text),
(374261,41585,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sept oreillers ? OK, je ... celui du milieu, parce que celui du milieu est au milieu.'::text,'prendrai'::text,'serai en train de prendre'::text,'prends'::text,'Sept oreillers ? OK, je prendrai celui du milieu, parce que celui du milieu est au milieu.'::text),
(374264,41585,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yedi yastık mı? Tamam, ben ortadakini ..., çünkü ortadaki ortada.'::text,'alacağım'::text,'alıyor olacağım'::text,'alıyorum'::text,'Yedi yastık mı? Tamam, ben ortadakini alacağım, çünkü ortadaki ortada.'::text),
(374265,41585,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hét párna? Oké, én a középsőt ..., mert a középső van középen.'::text,'elveszem'::text,'el fogom venni'::text,'éppen elveszem'::text,'Hét párna? Oké, én a középsőt elveszem, mert a középső van középen.'::text),
(374268,41586,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn das Individuum rückwärts auf ein Kissen ..., absorbiert das Kissen typischerweise den Aufprall.'::text,'fällt'::text,'fiel'::text,'fallen wird'::text,'Wenn das Individuum rückwärts auf ein Kissen fällt, absorbiert das Kissen typischerweise den Aufprall.'::text),
(374272,41586,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо індивід ... спиною на подушку, подушка зазвичай поглинає удар.'::text,'падає'::text,'впав'::text,'впаде'::text,'Якщо індивід падає спиною на подушку, подушка зазвичай поглинає удар.'::text),
(374271,41586,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el individuo ... de espaldas sobre una almohada, la almohada suele absorber el impacto.'::text,'cae'::text,'cayó'::text,'caerá'::text,'Si el individuo cae de espaldas sobre una almohada, la almohada suele absorber el impacto.'::text),
(374270,41586,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si l''individu ... en arrière sur un oreiller, l''oreiller absorbe généralement l''impact.'::text,'tombe'::text,'est tombé'::text,'tombera'::text,'Si l''individu tombe en arrière sur un oreiller, l''oreiller absorbe généralement l''impact.'::text),
(374273,41586,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Birey sırtüstü bir yastığa ..., yastık genellikle darbeyi emer.'::text,'düşerse'::text,'düştüyse'::text,'düşecekse'::text,'Birey sırtüstü bir yastığa düşerse, yastık genellikle darbeyi emer.'::text),
(374274,41586,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha az egyed hátrafelé egy párnára ..., a párna jellemzően elnyeli az ütközést.'::text,'esik'::text,'esett'::text,'esik majd'::text,'Ha az egyed hátrafelé egy párnára esik, a párna jellemzően elnyeli az ütközést.'::text),
(374277,41587,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du weißt echt, wie man ein Bett mit sieben Kissen ...! Ikonisch, ehrlich.'::text,'genießt'::text,'Genießen'::text,'genießen'::text,'Du weißt echt, wie man ein Bett mit sieben Kissen genießt! Ikonisch, ehrlich.'::text),
(374281,41587,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти справді вмієш ... ліжком із сімома подушками. Культово, чесно.'::text,'насолоджуватися'::text,'насолоджування'::text,'насолоджуватися'::text,'Ти справді вмієш насолоджуватися ліжком із сімома подушками. Культово, чесно.'::text),
(374280,41587,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'De verdad sabes ... de una cama con siete almohadas. Icónico, en serio.'::text,'disfrutar'::text,'disfrutando'::text,'disfrutar'::text,'De verdad sabes disfrutar de una cama con siete almohadas. Icónico, en serio.'::text),
(374279,41587,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu sais vraiment ... d''un lit avec sept oreillers. Iconique, franchement.'::text,'profiter'::text,'profitant'::text,'profiter'::text,'Tu sais vraiment profiter d''un lit avec sept oreillers. Iconique, franchement.'::text),
(374282,41587,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yedi yastıklı bir yatağın tadını ... gerçekten biliyorsun. İkonik, cidden.'::text,'çıkarmayı'::text,'çıkarmak'::text,'çıkar'::text,'Yedi yastıklı bir yatağın tadını çıkarmayı gerçekten biliyorsun. İkonik, cidden.'::text),
(374283,41587,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Te aztán tudod, hogyan kell ... egy hét párnás ágyat. Ikonikus, őszintén.'::text,'élvezni'::text,'élvezés'::text,'élvez'::text,'Te aztán tudod, hogyan kell élvezni egy hét párnás ágyat. Ikonikus, őszintén.'::text),
(374286,41588,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, gerade ... du auf diesen Kissen wie eine absolute Legende.'::text,'liegst'::text,'liegst'::text,'hast gelegen'::text,'Ehrlich, gerade liegst du auf diesen Kissen wie eine absolute Legende.'::text),
(374290,41588,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, прямо зараз ти ... на цих подушках, як справжня легенда.'::text,'лежиш'::text,'лежиш'::text,'лежала'::text,'Чесно, прямо зараз ти лежиш на цих подушках, як справжня легенда.'::text),
(374289,41588,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En serio, ahora mismo ... en esas almohadas como una auténtica leyenda.'::text,'estás tumbada'::text,'te tumbas'::text,'has estado tumbada'::text,'En serio, ahora mismo estás tumbada en esas almohadas como una auténtica leyenda.'::text),
(374288,41588,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, là tout de suite, tu ... sur ces oreillers comme une vraie légende.'::text,'es allongée'::text,'t''allonges'::text,'as été allongée'::text,'Franchement, là tout de suite, tu es allongée sur ces oreillers comme une vraie légende.'::text),
(374291,41588,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası şu an o yastıklarda tam bir efsane gibi ...'::text,'uzanıyorsun'::text,'uzanırsın'::text,'uzandın'::text,'Açıkçası şu an o yastıklarda tam bir efsane gibi uzanıyorsun.'::text),
(374292,41588,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, most épp úgy ... azokon a párnákon, mint egy igazi legenda.'::text,'fekszel'::text,'fekszel'::text,'feküdtél'::text,'Őszintén, most épp úgy fekszel azokon a párnákon, mint egy igazi legenda.'::text),
(383043,42561,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, angeblich ... er morgen um diese Zeit wieder die Schlucht runter.'::text,'rast'::text,'wird rasen'::text,'rast'::text,'Mädel, angeblich rast er morgen um diese Zeit wieder die Schlucht runter.'::text),
(383047,42561,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, завтра в цей час він знову ... вниз тією ущелиною.'::text,'мчатиме'::text,'помчить'::text,'мчить'::text,'Подруго, кажуть, завтра в цей час він знову мчатиме вниз тією ущелиною.'::text),
(383046,42561,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, al parecer mañana a esta hora él ... otra vez por ese cañón.'::text,'estará bajando a toda velocidad'::text,'bajará a toda velocidad'::text,'baja a toda velocidad'::text,'Tía, al parecer mañana a esta hora él estará bajando a toda velocidad otra vez por ese cañón.'::text),
(383045,42561,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, apparemment demain à cette heure-ci, il ... encore cette gorge.'::text,'dévalera'::text,'dévalera'::text,'dévale'::text,'Meuf, apparemment demain à cette heure-ci, il dévalera encore cette gorge.'::text),
(383048,42561,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, güya yarın bu saatlerde o vadiden yine aşağı ...'::text,'hızla iniyor olacakmış'::text,'hızla inecekmiş'::text,'hızla iniyormuş'::text,'Kızım, güya yarın bu saatlerde o vadiden yine aşağı hızla iniyor olacakmış.'::text),
(383049,42561,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag holnap ilyenkor megint ... lefelé abban a szurdokban.'::text,'száguld'::text,'fog száguldani'::text,'száguld'::text,'Csajszi, állítólag holnap ilyenkor megint száguld lefelé abban a szurdokban.'::text),
(383052,42562,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du bist so selbstbewusst, dass ich sicher bin, dass du dich auch in die nächste Stromschnelle ...'::text,'stürzen wirst'::text,'stürzen wirst'::text,'stürzt'::text,'Ehrlich, du bist so selbstbewusst, dass ich sicher bin, dass du dich auch in die nächste Stromschnelle stürzen wirst.'::text),
(383056,42562,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти такий впевнений, що я певна: ти ... і в наступний поріг.'::text,'кинешся'::text,'кидатимешся'::text,'кидаєшся'::text,'Чесно, ти такий впевнений, що я певна: ти кинешся і в наступний поріг.'::text),
(383055,42562,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En serio, eres tan seguro que estoy segura de que ... también al siguiente rápido.'::text,'te lanzarás'::text,'te estarás lanzando'::text,'te estás lanzando'::text,'En serio, eres tan seguro que estoy segura de que te lanzarás también al siguiente rápido.'::text),
(383054,42562,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, t''es tellement sûr de toi que je suis sûre que tu ... aussi dans le prochain rapide.'::text,'fonceras'::text,'seras en train de foncer'::text,'fonces'::text,'Franchement, t''es tellement sûr de toi que je suis sûre que tu fonceras aussi dans le prochain rapide.'::text),
(383057,42562,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası o kadar kendinden eminsin ki bir sonraki akıntıya da ... eminim.'::text,'dalacağından'::text,'dalıyor olacağından'::text,'daldığından'::text,'Açıkçası o kadar kendinden eminsin ki bir sonraki akıntıya da dalacağından eminim.'::text),
(383058,42562,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, annyira magabiztos vagy, hogy biztos vagyok benne: a következő zúgóba is ...'::text,'berohansz'::text,'be fogsz rohanni'::text,'éppen berohansz'::text,'Őszintén, annyira magabiztos vagy, hogy biztos vagyok benne: a következő zúgóba is berohansz.'::text),
(383061,42563,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn ein Fluss enger wird, ... das Wasser schneller zwischen den Felsen hindurch.'::text,'schießt'::text,'schoss'::text,'würde schießen'::text,'Wenn ein Fluss enger wird, schießt das Wasser schneller zwischen den Felsen hindurch.'::text),
(383065,42563,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли річка звужується, вода ... швидше між каменями.'::text,'мчить'::text,'мчала'::text,'мчала б'::text,'Коли річка звужується, вода мчить швидше між каменями.'::text),
(383064,42563,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cuando un río se estrecha, el agua ... más rápido entre las rocas.'::text,'corre'::text,'corrió'::text,'correría'::text,'Cuando un río se estrecha, el agua corre más rápido entre las rocas.'::text),
(383063,42563,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand une rivière se rétrécit, l''eau ... plus vite entre les rochers.'::text,'file'::text,'a filé'::text,'filerait'::text,'Quand une rivière se rétrécit, l''eau file plus vite entre les rochers.'::text),
(383066,42563,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nehir daraldığında su kayaların arasından daha hızlı ...'::text,'akar'::text,'aktı'::text,'akardı'::text,'Nehir daraldığında su kayaların arasından daha hızlı akar.'::text),
(383067,42563,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amikor egy folyó beszűkül, a víz gyorsabban ... a sziklák között.'::text,'zúdul'::text,'zúdult'::text,'zúdulna'::text,'Amikor egy folyó beszűkül, a víz gyorsabban zúdul a sziklák között.'::text),
(383079,42565,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... Angst, wenn Wasser an seinem Kajak vorbeirauschte, aber jetzt liebt er es.'::text,'hatte früher'::text,'hatte'::text,'war es gewohnt'::text,'Er hatte früher Angst, wenn Wasser an seinem Kajak vorbeirauschte, aber jetzt liebt er es.'::text),
(383083,42565,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ..., коли вода мчала повз його каяк, але тепер він це обожнює.'::text,'раніше боявся'::text,'боявся'::text,'звик боятися'::text,'Він раніше боявся, коли вода мчала повз його каяк, але тепер він це обожнює.'::text),
(383082,42565,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... tener miedo cuando el agua pasaba rugiendo junto a su kayak, pero ahora le encanta.'::text,'solía'::text,'solía'::text,'estaba acostumbrado a'::text,'Él solía tener miedo cuando el agua pasaba rugiendo junto a su kayak, pero ahora le encanta.'::text),
(383081,42565,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avant, il ... peur quand l''eau filait le long de son kayak, mais maintenant il adore ça.'::text,'avait'::text,'avait'::text,'était habitué à avoir'::text,'Avant, il avait peur quand l''eau filait le long de son kayak, mais maintenant il adore ça.'::text),
(383084,42565,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Suyun kanosunun yanından hızla aktığı zamanlar ..., ama şimdi buna bayılıyor.'::text,'korkardı'::text,'korkardı'::text,'korkmaya alışkındı'::text,'Suyun kanosunun yanından hızla aktığı zamanlar korkardı, ama şimdi buna bayılıyor.'::text),
(383085,42565,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Régen ..., amikor a víz elzúdult a kajakja mellett, de most imádja.'::text,'félt'::text,'félt'::text,'hozzá volt szokva a félelemhez'::text,'Régen félt, amikor a víz elzúdult a kajakja mellett, de most imádja.'::text),
(383088,42566,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Kajakfahrer vermeidet ... in die dunklen Felsen, wie im Filmmaterial beobachtet.'::text,'das Hineinrasen'::text,'hineinzurasen'::text,'hineinrasen'::text,'Der Kajakfahrer vermeidet das Hineinrasen in die dunklen Felsen, wie im Filmmaterial beobachtet.'::text),
(383092,42566,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Каякер уникає ... в темні камені, як видно на записі.'::text,'врізання'::text,'врізатися'::text,'врізатися'::text,'Каякер уникає врізання в темні камені, як видно на записі.'::text),
(383091,42566,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El piragüista evita ... contra las rocas oscuras, como se observa en la grabación.'::text,'lanzarse'::text,'lanzándose'::text,'lanzar'::text,'El piragüista evita lanzarse contra las rocas oscuras, como se observa en la grabación.'::text),
(383090,42566,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le kayakiste évite de ... dans les rochers sombres, comme on l''observe sur les images.'::text,'foncer'::text,'foncer'::text,'fonce'::text,'Le kayakiste évite de foncer dans les rochers sombres, comme on l''observe sur les images.'::text),
(383093,42566,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanocu, görüntülerde gözlemlendiği üzere, karanlık kayalara ... kaçınıyor.'::text,'dalmaktan'::text,'dalmak'::text,'dal'::text,'Kanocu, görüntülerde gözlemlendiği üzere, karanlık kayalara dalmaktan kaçınıyor.'::text),
(383094,42566,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kajakos kerüli, hogy a sötét sziklák közé ..., ahogy a felvételen megfigyelhető.'::text,'rohanjon'::text,'rohanni'::text,'rohan'::text,'A kajakos kerüli, hogy a sötét sziklák közé rohanjon, ahogy a felvételen megfigyelhető.'::text),
(383097,42567,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Wasser ist wie ein Albtraum an uns vorbeigerauscht, ...?'::text,'oder?'::text,'oder?'::text,'oder?'::text,'Das Wasser ist wie ein Albtraum an uns vorbeigerauscht, oder?'::text),
(383101,42567,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Та вода пронеслася повз нас, як жах, ...?'::text,'правда?'::text,'правда?'::text,'правда?'::text,'Та вода пронеслася повз нас, як жах, правда?'::text),
(383100,42567,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Esa agua pasó rugiendo a nuestro lado como una pesadilla, ...?'::text,'¿verdad?'::text,'¿verdad?'::text,'¿verdad?'::text,'Esa agua pasó rugiendo a nuestro lado como una pesadilla, ¿verdad?'::text),
(383099,42567,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cette eau a filé à côté de nous comme un cauchemar, ... ?'::text,'n''est-ce pas ?'::text,'n''est-ce pas ?'::text,'n''est-ce pas ?'::text,'Cette eau a filé à côté de nous comme un cauchemar, n''est-ce pas ?'::text),
(383102,42567,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O su bir kâbus gibi yanımızdan hızla geçti, ...?'::text,'değil mi?'::text,'değil mi?'::text,'değil mi?'::text,'O su bir kâbus gibi yanımızdan hızla geçti, değil mi?'::text),
(383103,42567,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az a víz rémálomként zúdult el mellettünk, ...?'::text,'ugye?'::text,'ugye?'::text,'ugye?'::text,'Az a víz rémálomként zúdult el mellettünk, ugye?'::text),
(383106,42568,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Chaos! Das Wasser raste die Schlucht hinunter und ...'::text,'wir auch.'::text,'wir auch.'::text,'wir auch.'::text,'Chaos! Das Wasser raste die Schlucht hinunter und wir auch.'::text),
(383110,42568,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Хаос! Вода мчала вниз ущелиною, і ...'::text,'ми теж.'::text,'ми теж.'::text,'ми теж.'::text,'Хаос! Вода мчала вниз ущелиною, і ми теж.'::text),
(383109,42568,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Caos! El agua bajó en tromba por el cañón, y ...'::text,'nosotros también.'::text,'nosotros también.'::text,'nosotros también.'::text,'¡Caos! El agua bajó en tromba por el cañón, y nosotros también.'::text),
(383108,42568,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le chaos ! L''eau a dévalé la gorge, et ...'::text,'nous aussi.'::text,'nous aussi.'::text,'nous aussi.'::text,'Le chaos ! L''eau a dévalé la gorge, et nous aussi.'::text),
(383111,42568,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kaos! Su vadiden aşağı hızla aktı, ...'::text,'biz de.'::text,'biz de.'::text,'biz de.'::text,'Kaos! Su vadiden aşağı hızla aktı, biz de.'::text),
(383112,42568,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Káosz! A víz lezúdult a szurdokban, és ...'::text,'mi is.'::text,'mi is.'::text,'mi is.'::text,'Káosz! A víz lezúdult a szurdokban, és mi is.'::text),
(383115,42569,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis wir ruhiges Wasser erreichen, ... wir durch die schlimmsten Stromschnellen unseres Lebens!'::text,'rasen'::text,'rasen'::text,'rasen gerade'::text,'Bis wir ruhiges Wasser erreichen, rasen wir durch die schlimmsten Stromschnellen unseres Lebens!'::text),
(383119,42569,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки ми допливемо до спокійної води, ми ... крізь найгірші пороги в нашому житті!'::text,'промчимо'::text,'промчимо'::text,'мчатимемо'::text,'Поки ми допливемо до спокійної води, ми промчимо крізь найгірші пороги в нашому житті!'::text),
(383118,42569,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Para cuando lleguemos a aguas tranquilas, ... por los peores rápidos de nuestra vida!'::text,'habremos pasado volando'::text,'pasaremos volando'::text,'estaremos pasando volando'::text,'¡Para cuando lleguemos a aguas tranquilas, habremos pasado volando por los peores rápidos de nuestra vida!'::text),
(383117,42569,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici à ce qu''on atteigne l''eau calme, on ... les pires rapides de notre vie !'::text,'aura dévalé'::text,'dévalera'::text,'sera en train de dévaler'::text,'D''ici à ce qu''on atteigne l''eau calme, on aura dévalé les pires rapides de notre vie !'::text),
(383120,42569,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sakin suya varana kadar hayatımızın en kötü akıntılarından hızla ...!'::text,'geçmiş olacağız'::text,'geçeceğiz'::text,'geçiyor olacağız'::text,'Sakin suya varana kadar hayatımızın en kötü akıntılarından hızla geçmiş olacağız!'::text),
(383121,42569,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire nyugodt vízhez érünk, ... életünk legdurvább zúgóin!'::text,'átszáguldunk'::text,'átszáguldunk'::text,'száguldani fogunk'::text,'Mire nyugodt vízhez érünk, átszáguldunk életünk legdurvább zúgóin!'::text),
(383133,42571,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Okay also, er hat mir erzählt, dass die anderen ewig am Ufer ..., bevor er reingerast ist.'::text,'gewartet hatten'::text,'gewartet haben'::text,'warten'::text,'Okay also, er hat mir erzählt, dass die anderen ewig am Ufer gewartet hatten, bevor er reingerast ist.'::text),
(383137,42571,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Отже, слухай, він мені сказав, що інші ... на березі цілу вічність, перш ніж він туди влетів.'::text,'чекали'::text,'чекають'::text,'чекають'::text,'Отже, слухай, він мені сказав, що інші чекали на березі цілу вічність, перш ніж він туди влетів.'::text),
(383136,42571,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, pues me dijo que los demás ... en la orilla una eternidad antes de que él se lanzara.'::text,'llevaban esperando'::text,'llevan esperando'::text,'están esperando'::text,'Vale, pues me dijo que los demás llevaban esperando en la orilla una eternidad antes de que él se lanzara.'::text),
(383135,42571,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon, du coup, il m''a dit que les autres ... sur la rive depuis une éternité avant qu''il fonce.'::text,'attendaient'::text,'attendent'::text,'attendent'::text,'Bon, du coup, il m''a dit que les autres attendaient sur la rive depuis une éternité avant qu''il fonce.'::text),
(383138,42571,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamam yani, bana dedi ki o dalmadan önce diğerleri kıyıda asırlardır ...'::text,'bekliyormuş'::text,'bekliyor'::text,'bekliyor'::text,'Tamam yani, bana dedi ki o dalmadan önce diğerleri kıyıda asırlardır bekliyormuş.'::text),
(383139,42571,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szóval, azt mondta, a többiek már ezer éve ... a parton, mielőtt ő belerohant.'::text,'vártak'::text,'várnak'::text,'várnak'::text,'Szóval, azt mondta, a többiek már ezer éve vártak a parton, mielőtt ő belerohant.'::text),
(403860,44874,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, angeblich ... sie gerade nach einem Haargummi, als sie drei an ihrem Handgelenk sah.'::text,'suchte'::text,'suchte'::text,'hat gesucht'::text,'Mädel, angeblich suchte sie gerade nach einem Haargummi, als sie drei an ihrem Handgelenk sah.'::text),
(403864,44874,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, вона ... гумку для волосся, коли побачила три на своєму зап''ясті.'::text,'шукала'::text,'пошукала'::text,'шукала'::text,'Подруго, кажуть, вона шукала гумку для волосся, коли побачила три на своєму зап''ясті.'::text),
(403863,44874,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, al parecer ella ... una goma del pelo cuando vio tres en su muñeca.'::text,'estaba buscando'::text,'buscó'::text,'ha buscado'::text,'Tía, al parecer ella estaba buscando una goma del pelo cuando vio tres en su muñeca.'::text),
(403862,44874,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, apparemment elle ... un élastique quand elle en a vu trois à son poignet.'::text,'cherchait'::text,'a cherché'::text,'a cherché'::text,'Meuf, apparemment elle cherchait un élastique quand elle en a vu trois à son poignet.'::text),
(403865,44874,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, güya bileğinde üç tane gördüğünde saç lastiği ...'::text,'arıyormuş'::text,'aradı'::text,'aramış'::text,'Kızım, güya bileğinde üç tane gördüğünde saç lastiği arıyormuş.'::text),
(403866,44874,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag épp hajgumit ..., amikor meglátott hármat a csuklóján.'::text,'keresett'::text,'keresett'::text,'keresett'::text,'Csajszi, állítólag épp hajgumit keresett, amikor meglátott hármat a csuklóján.'::text),
(403878,44876,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sie zuerst auf ihr Handgelenk geschaut hätte, ... sie nicht die ganze Schublade durchwühlt.'::text,'hätte'::text,'wird'::text,'hat'::text,'Wenn sie zuerst auf ihr Handgelenk geschaut hätte, hätte sie nicht die ganze Schublade durchwühlt.'::text),
(403882,44876,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби вона спершу подивилася на зап''ястя, то ... всю шухляду.'::text,'не перерила б'::text,'не переритиме'::text,'не перерила'::text,'Якби вона спершу подивилася на зап''ястя, то не перерила б всю шухляду.'::text),
(403881,44876,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si primero se hubiera mirado la muñeca, no ... todo el cajón.'::text,'habría registrado'::text,'registrará'::text,'registró'::text,'Si primero se hubiera mirado la muñeca, no habría registrado todo el cajón.'::text),
(403880,44876,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si elle avait regardé son poignet d''abord, elle ... tout le tiroir.'::text,'n''aurait pas fouillé'::text,'ne fouillera pas'::text,'n''a pas fouillé'::text,'Si elle avait regardé son poignet d''abord, elle n''aurait pas fouillé tout le tiroir.'::text),
(403883,44876,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Önce bileğine baksaydı bütün çekmeceyi ...'::text,'karıştırmazdı'::text,'karıştırmayacak'::text,'karıştırmadı'::text,'Önce bileğine baksaydı bütün çekmeceyi karıştırmazdı.'::text),
(403884,44876,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha előbb a csuklójára nézett volna, ... az egész fiókot.'::text,'nem túrta volna fel'::text,'nem fogja feltúrni'::text,'nem túrta fel'::text,'Ha előbb a csuklójára nézett volna, nem túrta volna fel az egész fiókot.'::text),
(403887,44877,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie gab zu, die Haargummis an ihrem eigenen Handgelenk ...'::text,'vergessen zu haben'::text,'zu vergessen'::text,'vergessen'::text,'Sie gab zu, die Haargummis an ihrem eigenen Handgelenk vergessen zu haben.'::text),
(403891,44877,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона визнала, що ... про гумки на власному зап''ясті.'::text,'забула'::text,'забути'::text,'забута'::text,'Вона визнала, що забула про гумки на власному зап''ясті.'::text),
(403890,44877,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Admitió ... las gomas del pelo de su propia muñeca.'::text,'haber olvidado'::text,'olvidar'::text,'olvidado'::text,'Admitió haber olvidado las gomas del pelo de su propia muñeca.'::text),
(403889,44877,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a reconnu ... les élastiques à son propre poignet.'::text,'avoir oublié'::text,'oublier'::text,'oublié'::text,'Elle a reconnu avoir oublié les élastiques à son propre poignet.'::text),
(403892,44877,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kendi bileğindeki saç lastiklerini ... itiraf etti.'::text,'unuttuğunu'::text,'unutmayı'::text,'unutulmuş'::text,'Kendi bileğindeki saç lastiklerini unuttuğunu itiraf etti.'::text),
(403893,44877,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Beismerte, hogy ... a saját csuklóján lévő hajgumikról.'::text,'megfeledkezett'::text,'megfeledkezni'::text,'elfelejtett'::text,'Beismerte, hogy megfeledkezett a saját csuklóján lévő hajgumikról.'::text),
(403896,44878,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... ihr Handgelenk checken sollen, bevor sie das ganze Zimmer durchsuchte.'::text,'hätte'::text,'muss'::text,'kann nicht'::text,'Sie hätte ihr Handgelenk checken sollen, bevor sie das ganze Zimmer durchsuchte.'::text),
(403900,44878,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... перевірити зап''ястя, перш ніж обшукувати всю кімнату.'::text,'мала б'::text,'мабуть мусила'::text,'не могла'::text,'Вона мала б перевірити зап''ястя, перш ніж обшукувати всю кімнату.'::text),
(403899,44878,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... revisado la muñeca antes de registrar toda la habitación.'::text,'debería haberse'::text,'debe de haberse'::text,'no puede haberse'::text,'Ella debería haberse revisado la muñeca antes de registrar toda la habitación.'::text),
(403898,44878,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... vérifier son poignet avant de fouiller toute la chambre.'::text,'aurait dû'::text,'a dû'::text,'n''a pas pu'::text,'Elle aurait dû vérifier son poignet avant de fouiller toute la chambre.'::text),
(403901,44878,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bütün odayı aramadan önce bileğini ...'::text,'kontrol etmeliydi'::text,'kontrol etmiş olmalı'::text,'kontrol etmiş olamaz'::text,'Bütün odayı aramadan önce bileğini kontrol etmeliydi.'::text),
(403902,44878,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Előbb a csuklóját ..., mielőtt átkutatta az egész szobát.'::text,'kellett volna megnéznie'::text,'biztos megnézte'::text,'nem nézhette meg'::text,'Előbb a csuklóját kellett volna megnéznie, mielőtt átkutatta az egész szobát.'::text),
(403905,44879,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das erwachsene Exemplar lässt das Jungtier still ..., während es einen Haargummi von seinem Handgelenk nimmt.'::text,'sitzen'::text,'zu sitzen'::text,'gesessen'::text,'Das erwachsene Exemplar lässt das Jungtier still sitzen, während es einen Haargummi von seinem Handgelenk nimmt.'::text),
(403909,44879,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Доросла особина змушує дитинча ... нерухомо, поки знімає гумку із зап''ястя.'::text,'сидіти'::text,'сидіти'::text,'сиділо'::text,'Доросла особина змушує дитинча сидіти нерухомо, поки знімає гумку із зап''ястя.'::text),
(403908,44879,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La adulta hace que la cría ... quieta mientras se quita una goma del pelo de la muñeca.'::text,'esté sentada'::text,'estar sentada'::text,'sentada'::text,'La adulta hace que la cría esté sentada quieta mientras se quita una goma del pelo de la muñeca.'::text),
(403907,44879,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''adulte fait ... le petit sans bouger pendant qu''elle retire un élastique de son poignet.'::text,'asseoir'::text,'s''asseoir'::text,'assis'::text,'L''adulte fait asseoir le petit sans bouger pendant qu''elle retire un élastique de son poignet.'::text),
(403910,44879,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yetişkin birey, bileğinden saç lastiği alırken yavruyu kıpırdamadan ...'::text,'oturtuyor'::text,'oturmaya'::text,'oturmuş'::text,'Yetişkin birey, bileğinden saç lastiği alırken yavruyu kıpırdamadan oturtuyor.'::text),
(403911,44879,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A felnőtt egyed mozdulatlanul ... a fiatalt, miközben leveszi a csuklójáról a hajgumit.'::text,'ülteti'::text,'ülni'::text,'ült'::text,'A felnőtt egyed mozdulatlanul ülteti a fiatalt, miközben leveszi a csuklójáról a hajgumit.'::text),
(403914,44880,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie wünscht sich, sie ... ihr Handgelenk gecheckt, bevor sie den ganzen Schminktisch zerlegt hat!'::text,'hätte'::text,'checkte'::text,'würde'::text,'Sie wünscht sich, sie hätte ihr Handgelenk gecheckt, bevor sie den ganzen Schminktisch zerlegt hat!'::text),
(403918,44880,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона шкодує, що не ... зап''ястя, перш ніж рознести весь туалетний столик!'::text,'перевірила'::text,'перевіряла'::text,'перевірить'::text,'Вона шкодує, що не перевірила зап''ястя, перш ніж рознести весь туалетний столик!'::text),
(403917,44880,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Desearía ... la muñeca antes de destrozar todo el tocador!'::text,'haberse revisado'::text,'revisarse'::text,'revisarse'::text,'¡Desearía haberse revisado la muñeca antes de destrozar todo el tocador!'::text),
(403916,44880,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle aimerait ... son poignet avant de détruire toute la coiffeuse !'::text,'avoir vérifié'::text,'vérifier'::text,'vérifier'::text,'Elle aimerait avoir vérifié son poignet avant de détruire toute la coiffeuse !'::text),
(403919,44880,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Keşke bütün makyaj masasını dağıtmadan önce bileğimi ... diyor!'::text,'kontrol etseydim'::text,'kontrol etsem'::text,'kontrol edecek olsam'::text,'Keşke bütün makyaj masasını dağıtmadan önce bileğimi kontrol etseydim diyor!'::text),
(403920,44880,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt kívánja, bárcsak ... a csuklóját, mielőtt szétszedte az egész fésülködőasztalt!'::text,'megnézte volna'::text,'megnézné'::text,'megnézné'::text,'Azt kívánja, bárcsak megnézte volna a csuklóját, mielőtt szétszedte az egész fésülködőasztalt!'::text),
(403923,44881,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Haargummis, ... die ganze Zeit an ihrem Handgelenk waren, haben ihr den ganzen Morgen ruiniert!'::text,'die'::text,'die'::text,'die'::text,'Die Haargummis, die die ganze Zeit an ihrem Handgelenk waren, haben ihr den ganzen Morgen ruiniert!'::text),
(403927,44881,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Гумки, ... весь час були на її зап''ясті, зіпсували їй увесь ранок!'::text,'які'::text,'які'::text,'хто'::text,'Гумки, які весь час були на її зап''ясті, зіпсували їй увесь ранок!'::text),
(403926,44881,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Las gomas del pelo, ... estuvieron en su muñeca todo el tiempo, le arruinaron la mañana entera!'::text,'que'::text,'que'::text,'quienes'::text,'¡Las gomas del pelo, que estuvieron en su muñeca todo el tiempo, le arruinaron la mañana entera!'::text),
(403925,44881,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les élastiques, ... étaient à son poignet depuis le début, lui ont gâché toute sa matinée !'::text,'qui'::text,'qui'::text,'qui'::text,'Les élastiques, qui étaient à son poignet depuis le début, lui ont gâché toute sa matinée !'::text),
(403928,44881,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Başından beri bileğinde ... saç lastikleri bütün sabahını mahvetti!'::text,'olan'::text,'olan'::text,'kim'::text,'Başından beri bileğinde olan saç lastikleri bütün sabahını mahvetti!'::text),
(403929,44881,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A hajgumik, ... végig a csuklóján voltak, tönkretették az egész reggelét!'::text,'amelyek'::text,'amik'::text,'akik'::text,'A hajgumik, amelyek végig a csuklóján voltak, tönkretették az egész reggelét!'::text),
(403932,44882,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Totale Katastrophe! Sie hat das ganze Haus durchsucht, und die Haargummis waren die ganze Zeit an ...!'::text,'ihrem Handgelenk'::text,'dem Handgelenk'::text,'einem Handgelenk'::text,'Totale Katastrophe! Sie hat das ganze Haus durchsucht, und die Haargummis waren die ganze Zeit an ihrem Handgelenk!'::text),
(403936,44882,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Повна катастрофа! Вона обшукала весь дім, а гумки весь час були на ...!'::text,'її зап''ясті'::text,'зап''ясті'::text,'зап''ясті'::text,'Повна катастрофа! Вона обшукала весь дім, а гумки весь час були на її зап''ясті!'::text),
(403935,44882,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Desastre total! Registró toda la casa, ¡y las gomas estaban en ... todo el tiempo!'::text,'su muñeca'::text,'la muñeca'::text,'una muñeca'::text,'¡Desastre total! Registró toda la casa, ¡y las gomas estaban en su muñeca todo el tiempo!'::text),
(403934,44882,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Catastrophe totale ! Elle a fouillé toute la maison, et les élastiques étaient à ... depuis le début !'::text,'son poignet'::text,'le poignet'::text,'un poignet'::text,'Catastrophe totale ! Elle a fouillé toute la maison, et les élastiques étaient à son poignet depuis le début !'::text),
(403937,44882,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tam bir felaket! Bütün evi aradı, oysa saç lastikleri başından beri ...!'::text,'bileğindeydi'::text,'bilekteydi'::text,'bir bilekteydi'::text,'Tam bir felaket! Bütün evi aradı, oysa saç lastikleri başından beri bileğindeydi!'::text),
(403938,44882,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Totális katasztrófa! Átkutatta az egész házat, a hajgumik pedig végig ... voltak!'::text,'a csuklóján'::text,'a csuklón'::text,'egy csuklón'::text,'Totális katasztrófa! Átkutatta az egész házat, a hajgumik pedig végig a csuklóján voltak!'::text),
(403950,44884,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Okay also, angeblich ... sie ab jetzt immer Haargummis am Handgelenk.'::text,'trägt'::text,'wird tragen'::text,'trägt'::text,'Okay also, angeblich trägt sie ab jetzt immer Haargummis am Handgelenk.'::text),
(403954,44884,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Отже, кажуть, відтепер вона ... гумки на зап''ясті.'::text,'завжди носитиме'::text,'завжди носитиме'::text,'завжди носить'::text,'Отже, кажуть, відтепер вона завжди носитиме гумки на зап''ясті.'::text),
(403953,44884,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, pues al parecer a partir de ahora ... gomas del pelo en la muñeca.'::text,'siempre llevará'::text,'siempre estará llevando'::text,'siempre lleva'::text,'Vale, pues al parecer a partir de ahora siempre llevará gomas del pelo en la muñeca.'::text),
(403952,44884,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon, du coup, apparemment elle ... des élastiques au poignet à partir de maintenant.'::text,'gardera toujours'::text,'gardera toujours'::text,'garde toujours'::text,'Bon, du coup, apparemment elle gardera toujours des élastiques au poignet à partir de maintenant.'::text),
(403955,44884,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamam yani, güya bundan sonra bileğinde hep saç lastiği ...'::text,'taşıyacakmış'::text,'taşıyor olacakmış'::text,'taşıyormuş'::text,'Tamam yani, güya bundan sonra bileğinde hep saç lastiği taşıyacakmış.'::text),
(403956,44884,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szóval, állítólag mostantól mindig ... hajgumit a csuklóján.'::text,'hord majd'::text,'fog hordani'::text,'hord'::text,'Szóval, állítólag mostantól mindig hord majd hajgumit a csuklóján.'::text),
(373386,41488,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn die Wolken wegbleiben, ... er die verschneiten Gipfel den ganzen Weg nach unten.'::text,'sieht'::text,'würde sehen'::text,'sah'::text,'Wenn die Wolken wegbleiben, sieht er die verschneiten Gipfel den ganzen Weg nach unten.'::text),
(373390,41488,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо хмари не з''являться, він ... засніжені вершини аж до самого низу.'::text,'бачитиме'::text,'бачив би'::text,'бачив'::text,'Якщо хмари не з''являться, він бачитиме засніжені вершини аж до самого низу.'::text),
(373389,41488,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si las nubes no aparecen, ... los picos nevados durante todo el descenso.'::text,'verá'::text,'vería'::text,'vio'::text,'Si las nubes no aparecen, verá los picos nevados durante todo el descenso.'::text),
(373388,41488,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si les nuages restent à l''écart, il ... les sommets enneigés pendant toute la descente.'::text,'verra'::text,'verrait'::text,'a vu'::text,'Si les nuages restent à l''écart, il verra les sommets enneigés pendant toute la descente.'::text),
(373391,41488,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bulutlar uzak durursa, aşağı inene kadar karlı zirveleri ...'::text,'görecek'::text,'görürdü'::text,'gördü'::text,'Bulutlar uzak durursa, aşağı inene kadar karlı zirveleri görecek.'::text),
(373392,41488,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a felhők távol maradnak, végig ... a havas csúcsokat lefelé.'::text,'látni fogja'::text,'látná'::text,'látta'::text,'Ha a felhők távol maradnak, végig látni fogja a havas csúcsokat lefelé.'::text),
(373395,41489,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn er aus einem höheren Hubschrauber springen würde, ... er mehr von den verschneiten Gipfeln.'::text,'sähe'::text,'wird sehen'::text,'sieht'::text,'Wenn er aus einem höheren Hubschrauber springen würde, sähe er mehr von den verschneiten Gipfeln.'::text),
(373399,41489,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби він стрибнув із вищого гелікоптера, то ... більше засніжених вершин.'::text,'побачив би'::text,'побачить'::text,'бачить'::text,'Якби він стрибнув із вищого гелікоптера, то побачив би більше засніжених вершин.'::text),
(373398,41489,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si saltara desde un helicóptero más alto, ... más picos nevados.'::text,'vería'::text,'verá'::text,'ve'::text,'Si saltara desde un helicóptero más alto, vería más picos nevados.'::text),
(373397,41489,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il sautait d''un hélicoptère plus haut, il ... davantage de sommets enneigés.'::text,'verrait'::text,'verra'::text,'voit'::text,'S''il sautait d''un hélicoptère plus haut, il verrait davantage de sommets enneigés.'::text),
(373400,41489,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Daha yüksekteki bir helikopterden atlasa, karlı zirvelerden daha fazlasını ...'::text,'görürdü'::text,'görecek'::text,'görüyor'::text,'Daha yüksekteki bir helikopterden atlasa, karlı zirvelerden daha fazlasını görürdü.'::text),
(373401,41489,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha egy magasabban repülő helikopterből ugrana, többet ... a havas csúcsokból.'::text,'látna'::text,'fog látni'::text,'lát'::text,'Ha egy magasabban repülő helikopterből ugrana, többet látna a havas csúcsokból.'::text),
(373404,41490,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Berggipfel ... mit dickem weißem Schnee bedeckt.'::text,'sind'::text,'bedecken'::text,'bedeckend'::text,'Die Berggipfel sind mit dickem weißem Schnee bedeckt.'::text),
(373408,41490,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Гірські вершини ... густим білим снігом.'::text,'вкриті'::text,'вкривають'::text,'вкривання'::text,'Гірські вершини вкриті густим білим снігом.'::text),
(373407,41490,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los picos de las montañas ... de una gruesa capa de nieve blanca.'::text,'están cubiertos'::text,'cubren'::text,'cubriendo'::text,'Los picos de las montañas están cubiertos de una gruesa capa de nieve blanca.'::text),
(373406,41490,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les sommets des montagnes ... d''une épaisse neige blanche.'::text,'sont couverts'::text,'couvrent'::text,'couvrant'::text,'Les sommets des montagnes sont couverts d''une épaisse neige blanche.'::text),
(373409,41490,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dağ zirveleri kalın beyaz karla ...'::text,'kaplı'::text,'kaplıyor'::text,'kaplayan'::text,'Dağ zirveleri kalın beyaz karla kaplı.'::text),
(373410,41490,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A hegycsúcsok vastag fehér hóval ...'::text,'borítottak'::text,'borítanak'::text,'borító'::text,'A hegycsúcsok vastag fehér hóval borítottak.'::text),
(373413,41491,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Hubschrauber ... ihn hoch über die verschneiten Gipfel.'::text,'trug'::text,'wurde getragen'::text,'tragend'::text,'Der Hubschrauber trug ihn hoch über die verschneiten Gipfel.'::text),
(373417,41491,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Гелікоптер ... його високо над засніженими вершинами.'::text,'підняв'::text,'був піднятий'::text,'піднімаючи'::text,'Гелікоптер підняв його високо над засніженими вершинами.'::text),
(373416,41491,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El helicóptero lo ... muy por encima de los picos nevados.'::text,'llevó'::text,'fue llevado'::text,'llevando'::text,'El helicóptero lo llevó muy por encima de los picos nevados.'::text),
(373415,41491,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''hélicoptère ... très haut au-dessus des sommets enneigés.'::text,'l''a emporté'::text,'a été emporté'::text,'l''emportant'::text,'L''hélicoptère l''a emporté très haut au-dessus des sommets enneigés.'::text),
(373418,41491,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Helikopter onu karlı zirvelerin çok yukarısına ...'::text,'taşıdı'::text,'taşındı'::text,'taşıyarak'::text,'Helikopter onu karlı zirvelerin çok yukarısına taşıdı.'::text),
(373419,41491,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A helikopter magasan a havas csúcsok fölé ... őt.'::text,'vitte'::text,'vitték'::text,'víve'::text,'A helikopter magasan a havas csúcsok fölé vitte őt.'::text),
(373422,41492,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dieser Gipfel ... etwa 4.000 Meter hoch sein, aber der Flugbericht sagt dazu nichts.'::text,'könnte'::text,'muss'::text,'kann nicht'::text,'Dieser Gipfel könnte etwa 4.000 Meter hoch sein, aber der Flugbericht sagt dazu nichts.'::text),
(373426,41492,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ця вершина ... мати близько 4 000 метрів заввишки, але в льотному звіті про це не сказано.'::text,'може'::text,'мусить'::text,'не може'::text,'Ця вершина може мати близько 4 000 метрів заввишки, але в льотному звіті про це не сказано.'::text),
(373425,41492,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ese pico ... tener unos 4.000 metros de altura, pero el informe de vuelo no lo indica.'::text,'podría'::text,'debe de'::text,'no puede'::text,'Ese pico podría tener unos 4.000 metros de altura, pero el informe de vuelo no lo indica.'::text),
(373424,41492,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ce sommet ... faire environ 4 000 mètres de haut, mais le rapport de vol ne le précise pas.'::text,'pourrait'::text,'doit'::text,'ne peut pas'::text,'Ce sommet pourrait faire environ 4 000 mètres de haut, mais le rapport de vol ne le précise pas.'::text),
(373427,41492,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O zirve yaklaşık 4.000 metre yüksekliğinde ..., ama uçuş raporu bunu belirtmiyor.'::text,'olabilir'::text,'olmalı'::text,'olamaz'::text,'O zirve yaklaşık 4.000 metre yüksekliğinde olabilir, ama uçuş raporu bunu belirtmiyor.'::text),
(373428,41492,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az a csúcs körülbelül 4000 méter magas ..., de a repülési jelentés nem írja.'::text,'lehet'::text,'kell hogy legyen'::text,'nem lehet'::text,'Az a csúcs körülbelül 4000 méter magas lehet, de a repülési jelentés nem írja.'::text),
(373431,41493,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Gipfel, ... der Hubschrauber zuerst passierte, war das Hauptziel des Sprungs um 9 Uhr.'::text,'den'::text,'der'::text,'dessen'::text,'Der Gipfel, den der Hubschrauber zuerst passierte, war das Hauptziel des Sprungs um 9 Uhr.'::text),
(373435,41493,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вершина, ... гелікоптер минув першою, була головною ціллю стрибка о 9:00.'::text,'яку'::text,'хто'::text,'чия'::text,'Вершина, яку гелікоптер минув першою, була головною ціллю стрибка о 9:00.'::text),
(373434,41493,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El pico ... el helicóptero pasó primero fue el objetivo principal del salto de las 9:00.'::text,'que'::text,'quien'::text,'cuyo'::text,'El pico que el helicóptero pasó primero fue el objetivo principal del salto de las 9:00.'::text),
(373433,41493,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le sommet ... l''hélicoptère a survolé en premier était l''objectif principal du saut de 9 h.'::text,'que'::text,'qui'::text,'dont'::text,'Le sommet que l''hélicoptère a survolé en premier était l''objectif principal du saut de 9 h.'::text),
(373436,41493,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Helikopterin önce üzerinden ... zirve, sabah 9 atlayışının ana hedefiydi.'::text,'geçtiği'::text,'kim'::text,'kimin'::text,'Helikopterin önce üzerinden geçtiği zirve, sabah 9 atlayışının ana hedefiydi.'::text),
(373437,41493,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A csúcs, ... fölött a helikopter elsőként elhaladt, volt a 9 órás ugrás fő célpontja.'::text,'amely'::text,'aki'::text,'akinek a'::text,'A csúcs, amely fölött a helikopter elsőként elhaladt, volt a 9 órás ugrás fő célpontja.'::text),
(373440,41494,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Pilot sagte, sie ... an dem Tag bis 10 Uhr über dem höchsten Gipfel sein, laut Bericht.'::text,'würden'::text,'werden'::text,'sind'::text,'Der Pilot sagte, sie würden an dem Tag bis 10 Uhr über dem höchsten Gipfel sein, laut Bericht.'::text),
(373444,41494,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Пілот сказав, що того дня до 10:00 вони ... над найвищою вершиною, згідно зі звітом.'::text,'будуть'::text,'будуть'::text,'є'::text,'Пілот сказав, що того дня до 10:00 вони будуть над найвищою вершиною, згідно зі звітом.'::text),
(373443,41494,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El piloto dijo que ese día ... sobre el pico más alto a las 10:00, según el informe.'::text,'estarían'::text,'estarán'::text,'están'::text,'El piloto dijo que ese día estarían sobre el pico más alto a las 10:00, según el informe.'::text),
(373442,41494,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le pilote a dit qu''ils ... au-dessus du plus haut sommet avant 10 h ce jour-là, selon le rapport.'::text,'seraient'::text,'seront'::text,'sont'::text,'Le pilote a dit qu''ils seraient au-dessus du plus haut sommet avant 10 h ce jour-là, selon le rapport.'::text),
(373445,41494,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pilot, rapora göre, o gün saat 10''a kadar en yüksek zirvenin üzerinde ... söyledi.'::text,'olacaklarını'::text,'olacaklarını'::text,'olduklarını'::text,'Pilot, rapora göre, o gün saat 10''a kadar en yüksek zirvenin üzerinde olacaklarını söyledi.'::text),
(373446,41494,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A pilóta azt mondta, hogy aznap 10 óráig a legmagasabb csúcs fölött ..., a jelentés szerint.'::text,'lesznek'::text,'lesznek'::text,'vannak'::text,'A pilóta azt mondta, hogy aznap 10 óráig a legmagasabb csúcs fölött lesznek, a jelentés szerint.'::text),
(373449,41495,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gletscher ... diese Gipfel früher deutlich dicker als heute.'::text,'bedeckten'::text,'bedeckten'::text,'waren gewohnt zu bedecken'::text,'Gletscher bedeckten diese Gipfel früher deutlich dicker als heute.'::text),
(373453,41495,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Льодовики ... ці вершини значно товстішим шаром, ніж сьогодні.'::text,'колись вкривали'::text,'вкривали'::text,'звикли вкривати'::text,'Льодовики колись вкривали ці вершини значно товстішим шаром, ніж сьогодні.'::text),
(373452,41495,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los glaciares ... cubrir estas cumbres con un espesor considerablemente mayor que hoy.'::text,'solían'::text,'solían'::text,'estaban acostumbrados a'::text,'Los glaciares solían cubrir estas cumbres con un espesor considerablemente mayor que hoy.'::text),
(373451,41495,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les glaciers ... ces sommets d''une couche bien plus épaisse qu''aujourd''hui.'::text,'recouvraient autrefois'::text,'recouvraient'::text,'avaient l''habitude de recouvrir'::text,'Les glaciers recouvraient autrefois ces sommets d''une couche bien plus épaisse qu''aujourd''hui.'::text),
(373454,41495,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Buzullar bu zirveleri bugünkünden çok daha kalın ...'::text,'kaplardı'::text,'kaplardı'::text,'kaplamaya alışkındı'::text,'Buzullar bu zirveleri bugünkünden çok daha kalın kaplardı.'::text),
(373455,41495,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A gleccserek egykor jóval vastagabban ... ezeket a csúcsokat, mint ma.'::text,'borították'::text,'borították'::text,'hozzá voltak szokva, hogy borítsák'::text,'A gleccserek egykor jóval vastagabban borították ezeket a csúcsokat, mint ma.'::text),
(373458,41496,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Offensichtlich vermied der Springer ... irgendwo in der Nähe der schneebedeckten Gipfel.'::text,'eine Landung'::text,'zu landen'::text,'landen'::text,'Offensichtlich vermied der Springer eine Landung irgendwo in der Nähe der schneebedeckten Gipfel.'::text),
(373462,41496,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Очевидно, парашутист уникав ... будь-де поблизу засніжених вершин.'::text,'приземлення'::text,'приземлитися'::text,'приземлятися'::text,'Очевидно, парашутист уникав приземлення будь-де поблизу засніжених вершин.'::text),
(373461,41496,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Evidentemente, el paracaidista evitó ... cerca de los picos nevados.'::text,'aterrizar'::text,'aterrizar'::text,'aterriza'::text,'Evidentemente, el paracaidista evitó aterrizar cerca de los picos nevados.'::text),
(373460,41496,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Visiblement, le parachutiste a évité ... près des sommets enneigés.'::text,'d''atterrir'::text,'atterrir'::text,'atterrit'::text,'Visiblement, le parachutiste a évité d''atterrir près des sommets enneigés.'::text),
(373463,41496,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Görünüşe göre paraşütçü karla kaplı zirvelerin yakınına ... kaçındı.'::text,'inmekten'::text,'inmeye'::text,'in'::text,'Görünüşe göre paraşütçü karla kaplı zirvelerin yakınına inmekten kaçındı.'::text),
(373464,41496,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nyilvánvalóan az ugró elkerülte, hogy bárhol a hófödte csúcsok közelében ...'::text,'landoljon'::text,'landolni'::text,'landol'::text,'Nyilvánvalóan az ugró elkerülte, hogy bárhol a hófödte csúcsok közelében landoljon.'::text),
(373467,41497,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Gipfel unter ihm sind mit Schnee bedeckt, ...?'::text,'oder?'::text,'oder?'::text,'oder?'::text,'Die Gipfel unter ihm sind mit Schnee bedeckt, oder?'::text),
(373471,41497,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вершини під ним укриті снігом, ...?'::text,'так?'::text,'так?'::text,'так?'::text,'Вершини під ним укриті снігом, так?'::text),
(373470,41497,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los picos debajo de él están cubiertos de nieve, ...?'::text,'¿verdad?'::text,'¿verdad?'::text,'¿verdad?'::text,'Los picos debajo de él están cubiertos de nieve, ¿verdad?'::text),
(373469,41497,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les sommets sous lui sont couverts de neige, ... ?'::text,'non ?'::text,'non ?'::text,'non ?'::text,'Les sommets sous lui sont couverts de neige, non ?'::text),
(373472,41497,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Altındaki zirveler karla kaplı, ...?'::text,'değil mi?'::text,'değil mi?'::text,'değil mi?'::text,'Altındaki zirveler karla kaplı, değil mi?'::text),
(373473,41497,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az alatta lévő csúcsokat hó borítja, ...?'::text,'ugye?'::text,'ugye?'::text,'ugye?'::text,'Az alatta lévő csúcsokat hó borítja, ugye?'::text),
(399963,44441,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... kopfüber unter der Tragfläche, als sie losließ.'::text,'hing'::text,'hing'::text,'hat gehangen'::text,'Sie hing kopfüber unter der Tragfläche, als sie losließ.'::text),
(399967,44441,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... догори ногами під крилом, коли відпустила руки.'::text,'висіла'::text,'повисіла'::text,'повисіла'::text,'Вона висіла догори ногами під крилом, коли відпустила руки.'::text),
(399966,44441,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... boca abajo bajo el ala cuando se soltó.'::text,'estaba colgando'::text,'colgó'::text,'ha colgado'::text,'Ella estaba colgando boca abajo bajo el ala cuando se soltó.'::text),
(399965,44441,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... la tête en bas sous l''aile quand elle a lâché prise.'::text,'était suspendue'::text,'a été suspendue'::text,'a été suspendue'::text,'Elle était suspendue la tête en bas sous l''aile quand elle a lâché prise.'::text),
(399968,44441,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O kanadın altında baş aşağı ..., bıraktığı anda.'::text,'asılı duruyordu'::text,'asılı durdu'::text,'asılı durmuş'::text,'O kanadın altında baş aşağı asılı duruyordu, bıraktığı anda.'::text),
(399969,44441,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Fejjel lefelé ... a szárny alatt, amikor elengedte.'::text,'lógott'::text,'lógott'::text,'lógott'::text,'Fejjel lefelé lógott a szárny alatt, amikor elengedte.'::text),
(399972,44442,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... sich bisher zweimal kopfüber unter der Tragfläche gedreht.'::text,'hat'::text,'dreht'::text,'drehte'::text,'Sie hat sich bisher zweimal kopfüber unter der Tragfläche gedreht.'::text),
(399976,44442,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Досі вона вже двічі ... догори ногами під крилом.'::text,'перевернулася'::text,'переверталася'::text,'перевернулася'::text,'Досі вона вже двічі перевернулася догори ногами під крилом.'::text),
(399975,44442,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hasta ahora, se ... boca abajo bajo el ala dos veces.'::text,'ha dado la vuelta'::text,'ha estado dando la vuelta'::text,'dio la vuelta'::text,'Hasta ahora, se ha dado la vuelta boca abajo bajo el ala dos veces.'::text),
(399974,44442,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jusqu''ici, elle ... la tête en bas deux fois sous l''aile.'::text,'s''est retournée'::text,'se retourne'::text,'s''est retournée'::text,'Jusqu''ici, elle s''est retournée la tête en bas deux fois sous l''aile.'::text),
(399977,44442,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şu ana kadar kanadın altında iki kez baş aşağı ...'::text,'döndü'::text,'dönüp duruyor'::text,'döndü'::text,'Şu ana kadar kanadın altında iki kez baş aşağı döndü.'::text),
(399978,44442,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eddig kétszer ... fejjel lefelé a szárny alatt.'::text,'fordult'::text,'fordulgatott'::text,'fordult'::text,'Eddig kétszer fordult fejjel lefelé a szárny alatt.'::text),
(399981,44443,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du ... dich schon kopfüber gedreht, bevor der Countdown überhaupt vorbei war.'::text,'hattest'::text,'hast'::text,'drehst'::text,'Ehrlich, du hattest dich schon kopfüber gedreht, bevor der Countdown überhaupt vorbei war.'::text),
(399985,44443,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти ... догори ногами ще до того, як закінчився відлік.'::text,'перевернулася'::text,'перевернулася'::text,'перевертаєшся'::text,'Чесно, ти перевернулася догори ногами ще до того, як закінчився відлік.'::text),
(399984,44443,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En serio, ya te ... boca abajo antes de que terminara la cuenta atrás.'::text,'habías dado la vuelta'::text,'has dado la vuelta'::text,'das la vuelta'::text,'En serio, ya te habías dado la vuelta boca abajo antes de que terminara la cuenta atrás.'::text),
(399983,44443,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, tu ... la tête en bas avant même la fin du compte à rebours.'::text,'t''étais retournée'::text,'t''es retournée'::text,'te retournes'::text,'Franchement, tu t''étais retournée la tête en bas avant même la fin du compte à rebours.'::text),
(399986,44443,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası geri sayım bitmeden baş aşağı ...'::text,'dönmüştün bile'::text,'döndün'::text,'dönüyorsun'::text,'Açıkçası geri sayım bitmeden baş aşağı dönmüştün bile.'::text),
(399987,44443,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, te már azelőtt fejjel lefelé ..., hogy a visszaszámlálás véget ért volna.'::text,'fordultál'::text,'fordultál'::text,'fordulsz'::text,'Őszintén, te már azelőtt fejjel lefelé fordultál, hogy a visszaszámlálás véget ért volna.'::text),
(399990,44444,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sie sich noch einmal kopfüber dreht, ... der Pilot begeistert sein, ganz offensichtlich.'::text,'wird'::text,'wäre'::text,'ist'::text,'Wenn sie sich noch einmal kopfüber dreht, wird der Pilot begeistert sein, ganz offensichtlich.'::text),
(399994,44444,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо вона ще раз перевернеться догори ногами, пілот ... в захваті, очевидно.'::text,'буде'::text,'був би'::text,'є'::text,'Якщо вона ще раз перевернеться догори ногами, пілот буде в захваті, очевидно.'::text),
(399993,44444,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si se pone boca abajo una vez más, el piloto ... encantado, obviamente.'::text,'estará'::text,'estaría'::text,'está'::text,'Si se pone boca abajo una vez más, el piloto estará encantado, obviamente.'::text),
(399992,44444,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si elle se retourne la tête en bas encore une fois, le pilote ... ravi, évidemment.'::text,'sera'::text,'serait'::text,'est'::text,'Si elle se retourne la tête en bas encore une fois, le pilote sera ravi, évidemment.'::text),
(399995,44444,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir kez daha baş aşağı dönerse pilot çok mutlu ..., belli ki.'::text,'olacak'::text,'olurdu'::text,NULL::text,'Bir kez daha baş aşağı dönerse pilot çok mutlu olacak, belli ki.'::text),
(399996,44444,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha még egyszer fejjel lefelé fordul, a pilóta nagyon boldog ..., nyilván.'::text,'lesz'::text,'lenne'::text,NULL::text,'Ha még egyszer fejjel lefelé fordul, a pilóta nagyon boldog lesz, nyilván.'::text),
(399999,44445,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn ich kopfüber an einem Flugzeug hängen würde, ... ich genauso ruhig wie sie. Offensichtlich.'::text,'bliebe'::text,'werde bleiben'::text,'bleibe'::text,'Wenn ich kopfüber an einem Flugzeug hängen würde, bliebe ich genauso ruhig wie sie. Offensichtlich.'::text),
(400003,44445,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби я висів догори ногами з літака, я ... таким же спокійним, як вона. Очевидно.'::text,'залишився б'::text,'залишуся'::text,'залишаюся'::text,'Якби я висів догори ногами з літака, я залишився б таким же спокійним, як вона. Очевидно.'::text),
(400002,44445,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si yo colgara boca abajo de un avión, ... tan tranquilo como ella. Obviamente.'::text,'me quedaría'::text,'me quedaré'::text,'me quedo'::text,'Si yo colgara boca abajo de un avión, me quedaría tan tranquilo como ella. Obviamente.'::text),
(400001,44445,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si je pendais la tête en bas sous un avion, je ... aussi calme qu''elle. Évidemment.'::text,'resterais'::text,'resterai'::text,'reste'::text,'Si je pendais la tête en bas sous un avion, je resterais aussi calme qu''elle. Évidemment.'::text),
(400004,44445,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir uçaktan baş aşağı sarkıyor olsam, ben de onun kadar sakin ..., tabii ki.'::text,'kalırdım'::text,'kalacağım'::text,'kalırım'::text,'Bir uçaktan baş aşağı sarkıyor olsam, ben de onun kadar sakin kalırdım, tabii ki.'::text),
(400005,44445,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha fejjel lefelé lógnék egy repülőről, ugyanolyan nyugodt ..., mint ő. Nyilvánvalóan.'::text,'maradnék'::text,'maradok'::text,'maradok'::text,'Ha fejjel lefelé lógnék egy repülőről, ugyanolyan nyugodt maradnék, mint ő. Nyilvánvalóan.'::text),
(400008,44446,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ihr Stunt ... kopfüber über einem Korallenriff vorgeführt. Eindeutig ein ruhiger Morgen.'::text,'wurde'::text,'führte'::text,'führt'::text,'Ihr Stunt wurde kopfüber über einem Korallenriff vorgeführt. Eindeutig ein ruhiger Morgen.'::text),
(400012,44446,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Її трюк ... догори ногами над кораловим рифом. Явно спокійний ранок.'::text,'був виконаний'::text,'виконав'::text,'виконує'::text,'Її трюк був виконаний догори ногами над кораловим рифом. Явно спокійний ранок.'::text),
(400011,44446,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su truco ... boca abajo sobre un arrecife de coral. Claramente, una mañana tranquila.'::text,'fue realizado'::text,'realizó'::text,'está realizando'::text,'Su truco fue realizado boca abajo sobre un arrecife de coral. Claramente, una mañana tranquila.'::text),
(400010,44446,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sa cascade ... la tête en bas au-dessus d''un récif de corail. Clairement une matinée tranquille.'::text,'a été réalisée'::text,'a réalisé'::text,'réalise'::text,'Sa cascade a été réalisée la tête en bas au-dessus d''un récif de corail. Clairement une matinée tranquille.'::text),
(400013,44446,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onun gösterisi bir mercan resifinin üzerinde baş aşağı ..., belli ki sakin bir sabah.'::text,'yapıldı'::text,'yaptı'::text,'yapıyor'::text,'Onun gösterisi bir mercan resifinin üzerinde baş aşağı yapıldı, belli ki sakin bir sabah.'::text),
(400014,44446,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A mutatványt fejjel lefelé ... egy korallzátony fölött. Egyértelműen nyugis reggel.'::text,'hajtotta végre'::text,'végrehajtotta'::text,'végrehajtja'::text,'A mutatványt fejjel lefelé hajtotta végre egy korallzátony fölött. Egyértelműen nyugis reggel.'::text),
(400017,44447,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... kopfüber über dem Ozean, und niemand konnte sie aufhalten!'::text,'schwang'::text,'wurde geschwungen'::text,'schwingend'::text,'Sie schwang kopfüber über dem Ozean, und niemand konnte sie aufhalten!'::text),
(400021,44447,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... догори ногами над океаном, і ніхто не міг її зупинити!'::text,'гойднулася'::text,'була розгойдана'::text,'гойдаючись'::text,'Вона гойднулася догори ногами над океаном, і ніхто не міг її зупинити!'::text),
(400020,44447,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Ella se ... boca abajo sobre el océano, y nadie pudo detenerla!'::text,'balanceó'::text,'fue balanceada'::text,'balanceando'::text,'¡Ella se balanceó boca abajo sobre el océano, y nadie pudo detenerla!'::text),
(400019,44447,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... la tête en bas au-dessus de l''océan, et personne n''a pu l''arrêter !'::text,'s''est balancée'::text,'a été balancée'::text,'se balançant'::text,'Elle s''est balancée la tête en bas au-dessus de l''océan, et personne n''a pu l''arrêter !'::text),
(400022,44447,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Okyanusun üzerinde baş aşağı ... ve kimse onu durduramadı!'::text,'sallandı'::text,'sallandırıldı'::text,'sallanarak'::text,'Okyanusun üzerinde baş aşağı sallandı ve kimse onu durduramadı!'::text),
(400023,44447,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Fejjel lefelé ... az óceán fölött, és senki sem tudta megállítani!'::text,'lendült'::text,'lendítették'::text,'lendülve'::text,'Fejjel lefelé lendült az óceán fölött, és senki sem tudta megállítani!'::text),
(400026,44448,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie lacht kopfüber unter der Tragfläche; sie ... völlig furchtlos sein!'::text,'muss'::text,'könnte'::text,'sollte'::text,'Sie lacht kopfüber unter der Tragfläche; sie muss völlig furchtlos sein!'::text),
(400030,44448,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона сміється догори ногами під крилом; вона ... бути абсолютно безстрашною!'::text,'мусить'::text,'може'::text,'повинна'::text,'Вона сміється догори ногами під крилом; вона мусить бути абсолютно безстрашною!'::text),
(400029,44448,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Se está riendo boca abajo bajo el ala; ... ser totalmente intrépida!'::text,'debe de'::text,'podría'::text,'debería'::text,'¡Se está riendo boca abajo bajo el ala; debe de ser totalmente intrépida!'::text),
(400028,44448,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle rit la tête en bas sous l''aile ; elle ... être complètement intrépide !'::text,'doit'::text,'pourrait'::text,'devrait'::text,'Elle rit la tête en bas sous l''aile ; elle doit être complètement intrépide !'::text),
(400031,44448,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanadın altında baş aşağı gülüyor; tamamen korkusuz ...!'::text,'olmalı'::text,'olabilir'::text,'olması gerek'::text,'Kanadın altında baş aşağı gülüyor; tamamen korkusuz olmalı!'::text),
(400032,44448,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Fejjel lefelé nevet a szárny alatt; ... teljesen rettenthetetlen!'::text,'biztosan'::text,'talán'::text,'elvileg'::text,'Fejjel lefelé nevet a szárny alatt; biztosan teljesen rettenthetetlen!'::text),
(400035,44449,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Warte, angeblich ist die Frau, ... kopfüber am Flügel hing, Pilotin.'::text,'die'::text,'welches'::text,'deren'::text,'Warte, angeblich ist die Frau, die kopfüber am Flügel hing, Pilotin.'::text),
(400039,44449,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чекай, кажуть, жінка, ... висіла догори ногами на крилі, — пілотка.'::text,'яка'::text,'що'::text,'чия'::text,'Чекай, кажуть, жінка, яка висіла догори ногами на крилі, — пілотка.'::text),
(400038,44449,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Espera, al parecer la mujer ... colgó boca abajo del ala es piloto.'::text,'que'::text,'la cual'::text,'cuya'::text,'Espera, al parecer la mujer que colgó boca abajo del ala es piloto.'::text),
(400037,44449,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Attends, apparemment la femme ... s''est suspendue la tête en bas à l''aile est pilote.'::text,'qui'::text,'lequel'::text,'dont'::text,'Attends, apparemment la femme qui s''est suspendue la tête en bas à l''aile est pilote.'::text),
(400040,44449,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dur, güya kanattan baş aşağı ... kadın pilotmuş.'::text,'sarkan'::text,'hangi'::text,'kimin'::text,'Dur, güya kanattan baş aşağı sarkan kadın pilotmuş.'::text),
(400041,44449,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Várj, állítólag a nő, ... fejjel lefelé lógott a szárnyról, pilóta.'::text,'aki'::text,'amely'::text,'akinek a'::text,'Várj, állítólag a nő, aki fejjel lefelé lógott a szárnyról, pilóta.'::text),
(400053,44451,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als Kind ... sie stundenlang kopfüber an Bäumen.'::text,'hing'::text,'hing'::text,'war gewohnt zu hängen'::text,'Als Kind hing sie stundenlang kopfüber an Bäumen.'::text),
(400057,44451,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У дитинстві вона ... догори ногами на деревах годинами.'::text,'висіла'::text,'висіла'::text,'звикла висіти'::text,'У дитинстві вона висіла догори ногами на деревах годинами.'::text),
(400056,44451,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'De niña, ... colgarse boca abajo de los árboles durante horas.'::text,'solía'::text,'solía'::text,'estaba acostumbrada a'::text,'De niña, solía colgarse boca abajo de los árboles durante horas.'::text),
(400055,44451,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Enfant, elle ... la tête en bas aux arbres pendant des heures.'::text,'se suspendait'::text,'se suspendait'::text,'avait l''habitude de se suspendre'::text,'Enfant, elle se suspendait la tête en bas aux arbres pendant des heures.'::text),
(400058,44451,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çocukken ağaçlardan saatlerce baş aşağı ...'::text,'sarkardı'::text,'sarkardı'::text,'sarkmaya alışkındı'::text,'Çocukken ağaçlardan saatlerce baş aşağı sarkardı.'::text),
(400059,44451,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gyerekként órákig ... fejjel lefelé a fákon.'::text,'lógott'::text,'lógott'::text,'hozzá volt szokva a lógáshoz'::text,'Gyerekként órákig lógott fejjel lefelé a fákon.'::text),
(334866,37208,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Schläfer ... tief und fest, als die Mücke zum Stechen landete. Super Job, Mückenstecker.'::text,'schlief'::text,'schlief'::text,'hat geschlafen'::text,'Der Schläfer schlief tief und fest, als die Mücke zum Stechen landete. Super Job, Mückenstecker.'::text),
(334870,37208,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Людина ... міцно, коли комар сів, щоб укусити. Чудова робота, відлякувачу.'::text,'спала'::text,'поспала'::text,'поспала'::text,'Людина спала міцно, коли комар сів, щоб укусити. Чудова робота, відлякувачу.'::text),
(334869,37208,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La persona ... profundamente cuando el mosquito aterrizó para picar. Buen trabajo, repelente.'::text,'estaba durmiendo'::text,'durmió'::text,'ha dormido'::text,'La persona estaba durmiendo profundamente cuando el mosquito aterrizó para picar. Buen trabajo, repelente.'::text),
(334868,37208,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le dormeur ... profondément quand le moustique s''est posé pour piquer. Bravo, le répulsif.'::text,'dormait'::text,'a dormi'::text,'a dormi'::text,'Le dormeur dormait profondément quand le moustique s''est posé pour piquer. Bravo, le répulsif.'::text),
(334871,37208,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Uyuyan kişi mışıl mışıl ..., sivrisinek ısırmak için konduğunda. Harika iş, kovucu.'::text,'uyuyordu'::text,'uyudu'::text,'uyumuş'::text,'Uyuyan kişi mışıl mışıl uyuyordu, sivrisinek ısırmak için konduğunda. Harika iş, kovucu.'::text),
(334872,37208,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az alvó mélyen ..., amikor a szúnyog leszállt, hogy megcsípje. Szép munka, riasztó.'::text,'aludt'::text,'aludt'::text,'aludt'::text,'Az alvó mélyen aludt, amikor a szúnyog leszállt, hogy megcsípje. Szép munka, riasztó.'::text),
(334875,37209,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Mückenstecker ... die ganze Nacht, und die Mücke will trotzdem stechen. Makellose Technik.'::text,'läuft'::text,'läuft'::text,'läuft'::text,'Der Mückenstecker läuft die ganze Nacht, und die Mücke will trotzdem stechen. Makellose Technik.'::text),
(334879,37209,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Відлякувач ... всю ніч, а комар однаково хоче вкусити. Бездоганна технологія.'::text,'працює'::text,'працює'::text,'працює'::text,'Відлякувач працює всю ніч, а комар однаково хоче вкусити. Бездоганна технологія.'::text),
(334878,37209,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El repelente ... toda la noche, y el mosquito sigue queriendo picar. Tecnología impecable.'::text,'lleva funcionando'::text,'está funcionando'::text,'funciona'::text,'El repelente lleva funcionando toda la noche, y el mosquito sigue queriendo picar. Tecnología impecable.'::text),
(334877,37209,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le répulsif ... toute la nuit, et le moustique veut toujours piquer. Technologie impeccable.'::text,'fonctionne'::text,'fonctionne'::text,'fonctionne'::text,'Le répulsif fonctionne toute la nuit, et le moustique veut toujours piquer. Technologie impeccable.'::text),
(334880,37209,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kovucu bütün gece ... ve sivrisinek hâlâ ısırmak istiyor. Kusursuz teknoloji.'::text,'çalışıyor'::text,'çalışıyor'::text,'çalışır'::text,'Kovucu bütün gece çalışıyor ve sivrisinek hâlâ ısırmak istiyor. Kusursuz teknoloji.'::text),
(334881,37209,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A riasztó egész éjjel ..., a szúnyog mégis csípni akar. Hibátlan technológia.'::text,'működik'::text,'működik'::text,'működik'::text,'A riasztó egész éjjel működik, a szúnyog mégis csípni akar. Hibátlan technológia.'::text),
(334884,37210,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, die Mücke ... einfach am Mückenstecker vorbei und ging direkt zum Stechen über, kein Witz.'::text,'flog'::text,'flog gerade'::text,'ist geflogen'::text,'Digga, die Mücke flog einfach am Mückenstecker vorbei und ging direkt zum Stechen über, kein Witz.'::text),
(334888,37210,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, комар просто ... повз відлякувач і пішов одразу кусати, без брехні.'::text,'пролетів'::text,'пролітав'::text,'пролетів'::text,'Бро, комар просто пролетів повз відлякувач і пішов одразу кусати, без брехні.'::text),
(334887,37210,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, el mosquito simplemente ... junto al repelente y fue directo a picar, te lo juro.'::text,'pasó volando'::text,'estaba pasando volando'::text,'ha pasado volando'::text,'Bro, el mosquito simplemente pasó volando junto al repelente y fue directo a picar, te lo juro.'::text),
(334886,37210,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, le moustique ... juste à côté du répulsif et il est allé direct piquer, sans mentir.'::text,'est passé'::text,'passait'::text,'est passé'::text,'Frérot, le moustique est passé juste à côté du répulsif et il est allé direct piquer, sans mentir.'::text),
(334889,37210,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, sivrisinek kovucunun yanından öylece ... ve direkt ısırmaya gitti, yalan yok.'::text,'uçup geçti'::text,'uçup geçiyordu'::text,'uçup geçmiş'::text,'Kanka, sivrisinek kovucunun yanından öylece uçup geçti ve direkt ısırmaya gitti, yalan yok.'::text),
(334890,37210,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, a szúnyog simán ... a riasztó mellett, és egyből ment csípni, nem viccelek.'::text,'elrepült'::text,'repült'::text,'elrepült'::text,'Tesó, a szúnyog simán elrepült a riasztó mellett, és egyből ment csípni, nem viccelek.'::text),
(334893,37211,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nee Digga, die Mücke ... mich heute Nacht schon dreimal gestochen, ich bin durch.'::text,'hat'::text,'sticht'::text,'sticht gerade'::text,'Nee Digga, die Mücke hat mich heute Nacht schon dreimal gestochen, ich bin durch.'::text),
(334897,37211,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ні, бро, цей комар ... мене сьогодні вночі тричі, мені кінець.'::text,'вкусив'::text,'кусав'::text,'кусає'::text,'Ні, бро, цей комар вкусив мене сьогодні вночі тричі, мені кінець.'::text),
(334896,37211,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Qué va, bro, este mosquito me ... tres veces esta noche, estoy muerto.'::text,'ha picado'::text,'ha estado picando'::text,'está picando'::text,'Qué va, bro, este mosquito me ha picado tres veces esta noche, estoy muerto.'::text),
(334895,37211,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Non frérot, ce moustique ... trois fois cette nuit, je suis foutu.'::text,'m''a piqué'::text,'me pique depuis tout à l''heure'::text,'me pique'::text,'Non frérot, ce moustique m''a piqué trois fois cette nuit, je suis foutu.'::text),
(334898,37211,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yok kanka, bu sivrisinek bu gece beni üç kez ..., bittim ben.'::text,'ısırdı'::text,'ısırıp duruyor'::text,'ısırıyor'::text,'Yok kanka, bu sivrisinek bu gece beni üç kez ısırdı, bittim ben.'::text),
(334899,37211,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem, tesó, ez a szúnyog ma éjjel háromszor ..., végem van.'::text,'megcsípett'::text,'csipkedett'::text,'csíp'::text,'Nem, tesó, ez a szúnyog ma éjjel háromszor megcsípett, végem van.'::text),
(334902,37212,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Prüfergebnis: Der Mückenstecker für 20 Euro ... kaputt sein, da die Mücke trotzdem jemanden gestochen hat.'::text,'muss'::text,'kann nicht'::text,'muss nicht'::text,'Prüfergebnis: Der Mückenstecker für 20 Euro muss kaputt sein, da die Mücke trotzdem jemanden gestochen hat.'::text),
(334906,37212,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Результат аудиту: відлякувач за 20 євро ... бути зламаним, адже комар однаково когось укусив.'::text,'мусить'::text,'не може'::text,'не мусить'::text,'Результат аудиту: відлякувач за 20 євро мусить бути зламаним, адже комар однаково когось укусив.'::text),
(334905,37212,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Resultado de la auditoría: el repelente de 20 euros ... estar roto, ya que el mosquito picó a alguien igualmente.'::text,'debe de'::text,'no puede'::text,'no tiene que'::text,'Resultado de la auditoría: el repelente de 20 euros debe de estar roto, ya que el mosquito picó a alguien igualmente.'::text),
(334904,37212,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Résultat de l''audit : le répulsif à 20 euros ... être cassé, puisque le moustique a quand même piqué quelqu''un.'::text,'doit'::text,'ne peut pas'::text,'n''a pas besoin d'''::text,'Résultat de l''audit : le répulsif à 20 euros doit être cassé, puisque le moustique a quand même piqué quelqu''un.'::text),
(334907,37212,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Denetim sonucu: 20 euroluk kovucu bozuk ..., çünkü sivrisinek yine de birini ısırdı.'::text,'olmalı'::text,'olamaz'::text,'olmak zorunda değil'::text,'Denetim sonucu: 20 euroluk kovucu bozuk olmalı, çünkü sivrisinek yine de birini ısırdı.'::text),
(334908,37212,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Auditeredmény: a 20 eurós riasztó ... elromlott, mivel a szúnyog így is megcsípett valakit.'::text,'biztosan'::text,'nem lehet, hogy'::text,'nem kell, hogy'::text,'Auditeredmény: a 20 eurós riasztó biztosan elromlott, mivel a szúnyog így is megcsípett valakit.'::text),
(334911,37213,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eine Mücke, ... dich nachts sticht, ist eine Nachtmücke, weil ja Nacht ist.'::text,'die'::text,'wer'::text,'was'::text,'Eine Mücke, die dich nachts sticht, ist eine Nachtmücke, weil ja Nacht ist.'::text),
(334915,37213,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Комар, ... кусає тебе вночі, — нічний комар, бо ж ніч.'::text,'який'::text,'хто'::text,'що'::text,'Комар, який кусає тебе вночі, — нічний комар, бо ж ніч.'::text),
(334914,37213,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un mosquito ... te pica de noche es un mosquito nocturno, porque es de noche.'::text,'que'::text,'quien'::text,'lo que'::text,'Un mosquito que te pica de noche es un mosquito nocturno, porque es de noche.'::text),
(334913,37213,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un moustique ... te pique la nuit est un moustique de nuit, parce que c''est la nuit.'::text,'qui'::text,'qui'::text,'ce qui'::text,'Un moustique qui te pique la nuit est un moustique de nuit, parce que c''est la nuit.'::text),
(334916,37213,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Seni gece ... sivrisinek gece sivrisineğidir, çünkü gece.'::text,'ısıran'::text,'kim'::text,'ne'::text,'Seni gece ısıran sivrisinek gece sivrisineğidir, çünkü gece.'::text),
(334917,37213,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az a szúnyog, ... éjjel megcsíp, éjszakai szúnyog, mert éjszaka van.'::text,'amelyik'::text,'aki'::text,'ami'::text,'Az a szúnyog, amelyik éjjel megcsíp, éjszakai szúnyog, mert éjszaka van.'::text),
(334929,37215,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Diese Mücke ... früher Angst vor dem Mückenstecker, aber jetzt fliegt sie zum Stechen daran vorbei.'::text,'hatte'::text,'hätte'::text,'ist es gewohnt'::text,'Diese Mücke hatte früher Angst vor dem Mückenstecker, aber jetzt fliegt sie zum Stechen daran vorbei.'::text),
(334933,37215,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Цей комар ... відлякувача, але тепер пролітає повз нього, щоб кусати.'::text,'колись боявся'::text,'боявся б'::text,'звик боятися'::text,'Цей комар колись боявся відлякувача, але тепер пролітає повз нього, щоб кусати.'::text),
(334932,37215,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Este mosquito ... tenerle miedo al repelente, pero ahora pasa volando a su lado para picar.'::text,'solía'::text,'solía'::text,'está acostumbrado a'::text,'Este mosquito solía tenerle miedo al repelente, pero ahora pasa volando a su lado para picar.'::text),
(334931,37215,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avant, ce moustique ... peur du répulsif, mais maintenant il passe à côté pour piquer.'::text,'avait'::text,'avait'::text,'est habitué à avoir'::text,'Avant, ce moustique avait peur du répulsif, mais maintenant il passe à côté pour piquer.'::text),
(334934,37215,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu sivrisinek eskiden kovucudan ..., ama şimdi ısırmak için yanından uçup geçiyor.'::text,'korkardı'::text,'korkardı'::text,'korkmaya alışkın'::text,'Bu sivrisinek eskiden kovucudan korkardı, ama şimdi ısırmak için yanından uçup geçiyor.'::text),
(334935,37215,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ez a szúnyog régen ... a riasztótól, de most elrepül mellette, hogy csípjen.'::text,'félt'::text,'félt'::text,'hozzá van szokva, hogy féljen'::text,'Ez a szúnyog régen félt a riasztótól, de most elrepül mellette, hogy csípjen.'::text),
(334938,37216,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Mücke ignoriert den Mückenstecker und beschließt, die schlafende Person ...'::text,'zu stechen'::text,'das Stechen'::text,'stechen'::text,'Die Mücke ignoriert den Mückenstecker und beschließt, die schlafende Person zu stechen.'::text),
(334942,37216,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Комар ігнорує відлякувач і вирішує ... сплячу людину.'::text,'вкусити'::text,'кусання'::text,'вкусити'::text,'Комар ігнорує відлякувач і вирішує вкусити сплячу людину.'::text),
(334941,37216,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El mosquito ignora el repelente y decide ... a la persona dormida.'::text,'picar'::text,'picando'::text,'pica'::text,'El mosquito ignora el repelente y decide picar a la persona dormida.'::text),
(334940,37216,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le moustique ignore le répulsif et décide de ... la personne endormie.'::text,'piquer'::text,'piquant'::text,'pique'::text,'Le moustique ignore le répulsif et décide de piquer la personne endormie.'::text),
(334943,37216,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sivrisinek kovucuyu umursamıyor ve uyuyan kişiyi ... karar veriyor.'::text,'ısırmaya'::text,'ısırmak'::text,'ısır'::text,'Sivrisinek kovucuyu umursamıyor ve uyuyan kişiyi ısırmaya karar veriyor.'::text),
(334944,37216,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A szúnyog nem törődik a riasztóval, és úgy dönt, hogy ... az alvó embert.'::text,'megcsípi'::text,'csípés'::text,'csíp'::text,'A szúnyog nem törődik a riasztóval, és úgy dönt, hogy megcsípi az alvó embert.'::text),
(334947,37217,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Low-key, du ... dich an jedem Mückenstecker im Haus vorbei, bevor du stichst.'::text,'schleichst'::text,'schleichst gerade'::text,'bist geschlichen'::text,'Low-key, du schleichst dich an jedem Mückenstecker im Haus vorbei, bevor du stichst.'::text),
(334951,37217,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно кажучи, ти ... повз кожен відлякувач у домі, перш ніж укусити.'::text,'прокрадаєшся'::text,'прокрадаєшся'::text,'прокрався'::text,'Чесно кажучи, ти прокрадаєшся повз кожен відлякувач у домі, перш ніж укусити.'::text),
(334950,37217,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En plan, te ... junto a cada repelente de la casa antes de picar.'::text,'cuelas'::text,'estás colando'::text,'has colado'::text,'En plan, te cuelas junto a cada repelente de la casa antes de picar.'::text),
(334949,37217,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Entre nous, tu te ... devant chaque répulsif de la maison avant de piquer.'::text,'faufiles'::text,'faufiles'::text,'es faufilé'::text,'Entre nous, tu te faufiles devant chaque répulsif de la maison avant de piquer.'::text),
(334952,37217,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Aramızda kalsın, ısırmadan önce evdeki her kovucunun yanından sessizce ...'::text,'geçiyorsun'::text,'geçiyorsun'::text,'geçtin'::text,'Aramızda kalsın, ısırmadan önce evdeki her kovucunun yanından sessizce geçiyorsun.'::text),
(334953,37217,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csak mondom, te minden riasztó mellett ... a házban, mielőtt csípsz.'::text,'elsurransz'::text,'épp elsurransz'::text,'elsurrantál'::text,'Csak mondom, te minden riasztó mellett elsurransz a házban, mielőtt csípsz.'::text),
(381270,42364,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Während die Rakete am Turm ..., wurde das Meeting für 3 Minuten unterbrochen.'::text,'hochstieg'::text,'hochstieg'::text,'hochgestiegen ist'::text,'Während die Rakete am Turm hochstieg, wurde das Meeting für 3 Minuten unterbrochen.'::text),
(381274,42364,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки ракета ... повз вежу, нарада зупинилася на 3 хвилини.'::text,'піднімалася'::text,'піднялася'::text,'піднялася'::text,'Поки ракета піднімалася повз вежу, нарада зупинилася на 3 хвилини.'::text),
(381273,42364,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mientras el cohete ... junto a la torre, la reunión se detuvo 3 minutos.'::text,'subía'::text,'subió'::text,'ha subido'::text,'Mientras el cohete subía junto a la torre, la reunión se detuvo 3 minutos.'::text),
(381272,42364,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pendant que la fusée ... le long de la tour, la réunion a fait une pause de 3 minutes.'::text,'s''élevait'::text,'s''est élevée'::text,'s''est élevée'::text,'Pendant que la fusée s''élevait le long de la tour, la réunion a fait une pause de 3 minutes.'::text),
(381275,42364,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Roket kulenin yanından ..., toplantıya 3 dakika ara verildi.'::text,'yükselirken'::text,'yükseldi'::text,'yükselmiş'::text,'Roket kulenin yanından yükselirken, toplantıya 3 dakika ara verildi.'::text),
(381276,42364,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amíg a rakéta a torony mellett ..., a megbeszélés 3 percre szünetelt.'::text,'emelkedett'::text,'felemelkedett'::text,'felemelkedett'::text,'Amíg a rakéta a torony mellett emelkedett, a megbeszélés 3 percre szünetelt.'::text),
(381279,42365,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Rakete ... seit 90 Sekunden, was im Zielkorridor liegt.'::text,'steigt'::text,'steigt'::text,'steigt'::text,'Die Rakete steigt seit 90 Sekunden, was im Zielkorridor liegt.'::text),
(381283,42365,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ракета ... вже 90 секунд, що відповідає плану.'::text,'піднімається'::text,'піднімається'::text,'піднімається'::text,'Ракета піднімається вже 90 секунд, що відповідає плану.'::text),
(381282,42365,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El cohete ... 90 segundos, lo cual está dentro del objetivo.'::text,'lleva subiendo'::text,'está subiendo'::text,'sube'::text,'El cohete lleva subiendo 90 segundos, lo cual está dentro del objetivo.'::text),
(381281,42365,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La fusée ... depuis 90 secondes, ce qui est conforme à l''objectif.'::text,'monte'::text,'monte'::text,'monte'::text,'La fusée monte depuis 90 secondes, ce qui est conforme à l''objectif.'::text),
(381284,42365,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Roket 90 saniyedir ..., bu da hedefle uyumlu.'::text,'yükseliyor'::text,'yükseliyor'::text,'yükselir'::text,'Roket 90 saniyedir yükseliyor, bu da hedefle uyumlu.'::text),
(381285,42365,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A rakéta 90 másodperce ..., ami megfelel a célnak.'::text,'emelkedik'::text,'emelkedik'::text,'emelkedik'::text,'A rakéta 90 másodperce emelkedik, ami megfelel a célnak.'::text),
(381288,42366,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Rakete ... gerade am Turm vorbei, als eine riesige Rauchwolke die Rampe verhüllte.'::text,'stieg'::text,'stieg'::text,'ist gestiegen'::text,'Die Rakete stieg gerade am Turm vorbei, als eine riesige Rauchwolke die Rampe verhüllte.'::text),
(381292,42366,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ракета ... повз вежу, коли величезна хмара диму накрила майданчик.'::text,'піднімалася'::text,'піднялася'::text,'піднялася'::text,'Ракета піднімалася повз вежу, коли величезна хмара диму накрила майданчик.'::text),
(381291,42366,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El cohete ... junto a la torre cuando una enorme nube de humo cubrió la plataforma.'::text,'estaba subiendo'::text,'subió'::text,'ha subido'::text,'El cohete estaba subiendo junto a la torre cuando una enorme nube de humo cubrió la plataforma.'::text),
(381290,42366,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La fusée ... le long de la tour quand un énorme nuage de fumée a recouvert le pas de tir.'::text,'s''élevait'::text,'s''est élevée'::text,'s''est élevée'::text,'La fusée s''élevait le long de la tour quand un énorme nuage de fumée a recouvert le pas de tir.'::text),
(381293,42366,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Roket kulenin yanından ..., dev bir duman bulutu rampayı kapladığında.'::text,'yükseliyordu'::text,'yükseldi'::text,'yükselmiş'::text,'Roket kulenin yanından yükseliyordu, dev bir duman bulutu rampayı kapladığında.'::text),
(381294,42366,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A rakéta épp a torony mellett ..., amikor hatalmas füstfelhő borította be az indítóállást.'::text,'emelkedett'::text,'emelkedett fel'::text,'emelkedett fel'::text,'A rakéta épp a torony mellett emelkedett, amikor hatalmas füstfelhő borította be az indítóállást.'::text),
(381297,42367,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Rakete ... aus dem Bild, sodass nur noch der Turm übrig ist.'::text,'stieg'::text,'steigt'::text,'stieg'::text,'Die Rakete stieg aus dem Bild, sodass nur noch der Turm übrig ist.'::text),
(381301,42367,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ракета ... з кадру, тож лишилася тільки вежа.'::text,'злетіла'::text,'злітала'::text,'злетіла'::text,'Ракета злетіла з кадру, тож лишилася тільки вежа.'::text),
(381300,42367,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El cohete ... fuera del plano, así que solo queda la torre.'::text,'ha subido'::text,'ha estado subiendo'::text,'subió'::text,'El cohete ha subido fuera del plano, así que solo queda la torre.'::text),
(381299,42367,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La fusée ... hors du cadre, donc il ne reste que la tour.'::text,'est montée'::text,'monte'::text,'est montée'::text,'La fusée est montée hors du cadre, donc il ne reste que la tour.'::text),
(381302,42367,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Roket kadrajdan çıkacak kadar ..., bu yüzden geriye sadece kule kaldı.'::text,'yükseldi'::text,'yükselip duruyor'::text,'yükseldi'::text,'Roket kadrajdan çıkacak kadar yükseldi, bu yüzden geriye sadece kule kaldı.'::text),
(381303,42367,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A rakéta ... a képből, így csak a torony maradt.'::text,'kiemelkedett'::text,'emelkedett'::text,'kiemelkedett'::text,'A rakéta kiemelkedett a képből, így csak a torony maradt.'::text),
(381306,42368,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als der Rauch die Kamera erreichte, ... die Rakete schon außer Sicht.'::text,'war'::text,'ist'::text,'steigt'::text,'Als der Rauch die Kamera erreichte, war die Rakete schon außer Sicht.'::text),
(381310,42368,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки дим дістався до камери, ракета вже ... з поля зору.'::text,'злетіла'::text,'злетіла'::text,'злітає'::text,'Поки дим дістався до камери, ракета вже злетіла з поля зору.'::text),
(381309,42368,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando el humo llegó a la cámara, el cohete ya ... hasta perderse de vista.'::text,'había subido'::text,'ha subido'::text,'sube'::text,'Para cuando el humo llegó a la cámara, el cohete ya había subido hasta perderse de vista.'::text),
(381308,42368,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le temps que la fumée atteigne la caméra, la fusée ... hors de vue.'::text,'était montée'::text,'est montée'::text,'monte'::text,'Le temps que la fumée atteigne la caméra, la fusée était montée hors de vue.'::text),
(381311,42368,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Duman kameraya ulaştığında roket çoktan gözden kaybolacak kadar ...'::text,'yükselmişti'::text,'yükseldi'::text,'yükseliyor'::text,'Duman kameraya ulaştığında roket çoktan gözden kaybolacak kadar yükselmişti.'::text),
(381312,42368,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire a füst elérte a kamerát, a rakéta már ... a látótérből.'::text,'kiemelkedett'::text,'kiemelkedett'::text,'emelkedik'::text,'Mire a füst elérte a kamerát, a rakéta már kiemelkedett a látótérből.'::text),
(381324,42370,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ich verspreche, diese Rakete ... wieder, selbst nach diesem absoluten Chaos!'::text,'steigt'::text,'wird steigen'::text,'steigt gerade'::text,'Ich verspreche, diese Rakete steigt wieder, selbst nach diesem absoluten Chaos!'::text),
(381328,42370,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Обіцяю, ця ракета знову ..., навіть після цього абсолютного хаосу!'::text,'злетить'::text,'злітатиме'::text,'злітає'::text,'Обіцяю, ця ракета знову злетить, навіть після цього абсолютного хаосу!'::text),
(381327,42370,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Te prometo que este cohete ... de nuevo, incluso después de este caos absoluto!'::text,'despegará'::text,'estará despegando'::text,'está despegando'::text,'¡Te prometo que este cohete despegará de nuevo, incluso después de este caos absoluto!'::text),
(381326,42370,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je promets que cette fusée ... à nouveau, même après ce chaos absolu !'::text,'s''élèvera'::text,'sera en train de s''élever'::text,'s''élève'::text,'Je promets que cette fusée s''élèvera à nouveau, même après ce chaos absolu !'::text),
(381329,42370,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Söz veriyorum, bu roket bu mutlak kaosun ardından bile yeniden ...!'::text,'yükselecek'::text,'yükseliyor olacak'::text,'yükseliyor'::text,'Söz veriyorum, bu roket bu mutlak kaosun ardından bile yeniden yükselecek!'::text),
(381330,42370,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Megígérem, hogy ez a rakéta újra ..., még ez után a totális káosz után is!'::text,'felemelkedik'::text,'emelkedni fog'::text,'emelkedik'::text,'Megígérem, hogy ez a rakéta újra felemelkedik, még ez után a totális káosz után is!'::text),
(381333,42371,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn heißes Gas stark genug nach unten drückt, ... eine Rakete in die Luft.'::text,'steigt'::text,'stieg'::text,'würde steigen'::text,'Wenn heißes Gas stark genug nach unten drückt, steigt eine Rakete in die Luft.'::text),
(381337,42371,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли гарячий газ тисне вниз досить сильно, ракета ... в повітря.'::text,'піднімається'::text,'піднялася'::text,'піднялася б'::text,'Коли гарячий газ тисне вниз досить сильно, ракета піднімається в повітря.'::text),
(381336,42371,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cuando el gas caliente empuja hacia abajo con suficiente fuerza, un cohete ... en el aire.'::text,'se eleva'::text,'se elevó'::text,'se elevaría'::text,'Cuando el gas caliente empuja hacia abajo con suficiente fuerza, un cohete se eleva en el aire.'::text),
(381335,42371,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand le gaz chaud pousse assez fort vers le bas, une fusée ... dans les airs.'::text,'s''élève'::text,'s''est élevée'::text,'s''élèverait'::text,'Quand le gaz chaud pousse assez fort vers le bas, une fusée s''élève dans les airs.'::text),
(381338,42371,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sıcak gaz aşağıya yeterince güçlü ittiğinde roket havaya ...'::text,'yükselir'::text,'yükseldi'::text,'yükselirdi'::text,'Sıcak gaz aşağıya yeterince güçlü ittiğinde roket havaya yükselir.'::text),
(381339,42371,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a forró gáz elég erősen nyom lefelé, a rakéta a levegőbe ...'::text,'emelkedik'::text,'emelkedett'::text,'emelkedne'::text,'Ha a forró gáz elég erősen nyom lefelé, a rakéta a levegőbe emelkedik.'::text),
(381342,42372,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Rakete schaffte ... am Turm vorbei, ganz ohne Laut. Offensichtlich.'::text,'den Aufstieg'::text,'das Aufsteigen'::text,'aufsteigen'::text,'Die Rakete schaffte den Aufstieg am Turm vorbei, ganz ohne Laut. Offensichtlich.'::text),
(381346,42372,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ракеті вдалося ... повз вежу без жодного звуку. Очевидно.'::text,'піднятися'::text,'піднімання'::text,'піднятися'::text,'Ракеті вдалося піднятися повз вежу без жодного звуку. Очевидно.'::text),
(381345,42372,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El cohete logró ... junto a la torre sin hacer ruido. Obviamente.'::text,'subir'::text,'subiendo'::text,'sube'::text,'El cohete logró subir junto a la torre sin hacer ruido. Obviamente.'::text),
(381344,42372,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La fusée a réussi à ... le long de la tour sans un bruit. Évidemment.'::text,'s''élever'::text,'s''élevant'::text,'s''élève'::text,'La fusée a réussi à s''élever le long de la tour sans un bruit. Évidemment.'::text),
(381347,42372,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Roket kulenin yanından hiç ses çıkarmadan ... başardı. Tabii ki.'::text,'yükselmeyi'::text,'yükselmek'::text,'yüksel'::text,'Roket kulenin yanından hiç ses çıkarmadan yükselmeyi başardı. Tabii ki.'::text),
(381348,42372,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A rakétának sikerült hangtalanul ... a torony mellett. Nyilvánvalóan.'::text,'felemelkednie'::text,'felemelkedés'::text,'felemelkedik'::text,'A rakétának sikerült hangtalanul felemelkednie a torony mellett. Nyilvánvalóan.'::text),
(381351,42373,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, die Rakete ... gerade so schnell, das ist echt unreal.'::text,'steigt'::text,'steigt'::text,'ist gestiegen'::text,'Digga, die Rakete steigt gerade so schnell, das ist echt unreal.'::text),
(381355,42373,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, ця ракета зараз ... так швидко, це якось нереально.'::text,'злітає'::text,'злітає'::text,'злетіла'::text,'Бро, ця ракета зараз злітає так швидко, це якось нереально.'::text),
(381354,42373,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, ese cohete ... tan rápido ahora mismo, es medio irreal.'::text,'está subiendo'::text,'sube'::text,'ha subido'::text,'Bro, ese cohete está subiendo tan rápido ahora mismo, es medio irreal.'::text),
(381353,42373,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, cette fusée ... tellement vite là, c''est grave irréel.'::text,'monte'::text,'monte'::text,'est montée'::text,'Frérot, cette fusée monte tellement vite là, c''est grave irréel.'::text),
(381356,42373,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o roket şu an o kadar hızlı ... ki, resmen gerçek dışı.'::text,'yükseliyor'::text,'yükselir'::text,'yükseldi'::text,'Kanka, o roket şu an o kadar hızlı yükseliyor ki, resmen gerçek dışı.'::text),
(381357,42373,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, az a rakéta most olyan gyorsan ..., hogy az már szinte irreális.'::text,'emelkedik'::text,'emelkedik'::text,'emelkedett'::text,'Tesó, az a rakéta most olyan gyorsan emelkedik, hogy az már szinte irreális.'::text),
(343830,38204,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als sie fertig gegossen hatte, ... das Eis unter ihren Füßen schon in alle Richtungen gerissen. Genie.'::text,'war'::text,'ist'::text,'reißt'::text,'Als sie fertig gegossen hatte, war das Eis unter ihren Füßen schon in alle Richtungen gerissen. Genie.'::text),
(343834,38204,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки вона долила, лід під її ногами вже ... на всі боки. Геній.'::text,'потріскався'::text,'потріскався'::text,'тріскається'::text,'Поки вона долила, лід під її ногами вже потріскався на всі боки. Геній.'::text),
(343833,38204,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando terminó de verter, el hielo bajo sus pies ya se ... en todas direcciones. Genial.'::text,'había agrietado'::text,'ha agrietado'::text,'agrieta'::text,'Para cuando terminó de verter, el hielo bajo sus pies ya se había agrietado en todas direcciones. Genial.'::text),
(343832,38204,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le temps qu''elle finisse de verser, la glace sous ses pieds ... dans tous les sens. Génie.'::text,'s''était fissurée'::text,'s''est fissurée'::text,'se fissure'::text,'Le temps qu''elle finisse de verser, la glace sous ses pieds s''était fissurée dans tous les sens. Génie.'::text),
(343835,38204,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dökmeyi bitirdiğinde ayaklarının altındaki buz çoktan her yöne doğru ..., dahiyane.'::text,'çatlamıştı'::text,'çatladı'::text,'çatlıyor'::text,'Dökmeyi bitirdiğinde ayaklarının altındaki buz çoktan her yöne doğru çatlamıştı, dahiyane.'::text),
(343836,38204,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire befejezte az öntést, a jég a lába alatt már minden irányban ..., zseniális.'::text,'megrepedt'::text,'megrepedt'::text,'reped'::text,'Mire befejezte az öntést, a jég a lába alatt már minden irányban megrepedt, zseniális.'::text),
(343839,38205,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen um diese Zeit ... sie das Eis auf dem See mit heißem Tee für ein weiteres Video.'::text,'knackt'::text,'knackt'::text,'knackt'::text,'Morgen um diese Zeit knackt sie das Eis auf dem See mit heißem Tee für ein weiteres Video.'::text),
(343843,38205,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра в цей час вона ... лід на озері гарячим чаєм для ще одного відео.'::text,'розколюватиме'::text,'розколе'::text,'розколює'::text,'Завтра в цей час вона розколюватиме лід на озері гарячим чаєм для ще одного відео.'::text),
(343842,38205,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mañana a esta hora, ella ... el hielo del lago con té caliente para otro vídeo.'::text,'estará agrietando'::text,'agrietará'::text,'agrieta'::text,'Mañana a esta hora, ella estará agrietando el hielo del lago con té caliente para otro vídeo.'::text),
(343841,38205,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain à cette heure-ci, elle ... la glace du lac avec du thé chaud pour une autre vidéo.'::text,'fera craquer'::text,'fera craquer'::text,'fait craquer'::text,'Demain à cette heure-ci, elle fera craquer la glace du lac avec du thé chaud pour une autre vidéo.'::text),
(343844,38205,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın bu saatlerde başka bir video için göl buzunu sıcak çayla ...'::text,'çatlatıyor olacak'::text,'çatlatacak'::text,'çatlatıyor'::text,'Yarın bu saatlerde başka bir video için göl buzunu sıcak çayla çatlatıyor olacak.'::text),
(343845,38205,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap ilyenkor forró teával ... a tavon a jeget egy újabb videóhoz.'::text,'fogja repeszteni'::text,'megrepeszti'::text,'repeszti'::text,'Holnap ilyenkor forró teával fogja repeszteni a tavon a jeget egy újabb videóhoz.'::text),
(343848,38206,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Risse breiten sich aus, also denkt sie, dass das Eis bald in Stücke ...'::text,'brechen wird'::text,'brechen wird'::text,'bricht'::text,'Die Risse breiten sich aus, also denkt sie, dass das Eis bald in Stücke brechen wird.'::text),
(343852,38206,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Тріщини поширюються, тож вона думає, що лід скоро ... на шматки.'::text,'розколеться'::text,'розколюватиметься'::text,'розколюється'::text,'Тріщини поширюються, тож вона думає, що лід скоро розколеться на шматки.'::text),
(343851,38206,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Las grietas se extienden, así que cree que el hielo pronto se ... en pedazos.'::text,'romperá'::text,'estará rompiendo'::text,'rompe'::text,'Las grietas se extienden, así que cree que el hielo pronto se romperá en pedazos.'::text),
(343850,38206,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les fissures s''étendent, alors elle pense que la glace ... bientôt en morceaux.'::text,'se brisera'::text,'sera en train de se briser'::text,'se brise'::text,'Les fissures s''étendent, alors elle pense que la glace se brisera bientôt en morceaux.'::text),
(343853,38206,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çatlaklar yayılıyor, o yüzden buzun yakında paramparça ... düşünüyor.'::text,'olacağını'::text,'oluyor olacağını'::text,'olduğunu'::text,'Çatlaklar yayılıyor, o yüzden buzun yakında paramparça olacağını düşünüyor.'::text),
(343854,38206,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A repedések terjednek, ezért úgy gondolja, a jég hamarosan darabokra ...'::text,'reped'::text,'repedezni fog'::text,'éppen reped'::text,'A repedések terjednek, ezért úgy gondolja, a jég hamarosan darabokra reped.'::text),
(343857,38207,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn heißer Tee auf sehr kaltes Eis trifft, ... die Oberfläche oft in dünnen Linien.'::text,'reißt'::text,'riss'::text,'wird reißen'::text,'Wenn heißer Tee auf sehr kaltes Eis trifft, reißt die Oberfläche oft in dünnen Linien.'::text),
(343861,38207,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо гарячий чай потрапляє на дуже холодний лід, поверхня часто ... тонкими лініями.'::text,'тріскається'::text,'тріснула'::text,'трісне'::text,'Якщо гарячий чай потрапляє на дуже холодний лід, поверхня часто тріскається тонкими лініями.'::text),
