(343859,38207,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si du thé chaud touche une glace très froide, la surface ... souvent en fines lignes.'::text,'se fissure'::text,'s''est fissurée'::text,'se fissurera'::text,'Si du thé chaud touche une glace très froide, la surface se fissure souvent en fines lignes.'::text),
(343862,38207,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sıcak çay çok soğuk buza değerse yüzey genellikle ince çizgiler halinde ...'::text,'çatlar'::text,'çatladı'::text,'çatlayacak'::text,'Sıcak çay çok soğuk buza değerse yüzey genellikle ince çizgiler halinde çatlar.'::text),
(343863,38207,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha forró tea ér nagyon hideg jéghez, a felszín gyakran vékony vonalakban ...'::text,'megreped'::text,'megrepedt'::text,'meg fog repedni'::text,'Ha forró tea ér nagyon hideg jéghez, a felszín gyakran vékony vonalakban megreped.'::text),
(343866,38208,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, wenn sie noch eine Tasse ausgießt, ... das Eis unter ihr, echt jetzt.'::text,'bricht'::text,'würde brechen'::text,'brach'::text,'Digga, wenn sie noch eine Tasse ausgießt, bricht das Eis unter ihr, echt jetzt.'::text),
(343870,38208,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, якщо вона наллє ще одну чашку, той лід під нею ..., реально.'::text,'трісне'::text,'тріснув би'::text,'тріснув'::text,'Бро, якщо вона наллє ще одну чашку, той лід під нею трісне, реально.'::text),
