(343868,38208,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, si elle verse encore une tasse, cette glace ... sous elle, sérieux.'::text,'va craquer'::text,'craquerait'::text,'a craqué'::text,'Frérot, si elle verse encore une tasse, cette glace va craquer sous elle, sérieux.'::text),
