(382264,42474,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо камера наблизить ще більше, круглий місяць ... весь кадр.'::text,'заповнить'::text,'заповнив би'::text,'заповнив'::text,'Якщо камера наблизить ще більше, круглий місяць заповнить весь кадр.'::text),
(382263,42474,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la cámara hace más zoom, la luna redonda ... toda la imagen.'::text,'llenará'::text,'llenaría'::text,'llenó'::text,'Si la cámara hace más zoom, la luna redonda llenará toda la imagen.'::text),
(382262,42474,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la caméra zoome davantage, la lune ronde ... toute l''image.'::text,'remplira'::text,'remplirait'::text,'a rempli'::text,'Si la caméra zoome davantage, la lune ronde remplira toute l''image.'::text),
(382265,42474,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kamera biraz daha yakınlaşırsa yuvarlak ay bütün görüntüyü ...'::text,'dolduracak'::text,'doldururdu'::text,'doldurdu'::text,'Kamera biraz daha yakınlaşırsa yuvarlak ay bütün görüntüyü dolduracak.'::text),
(382266,42474,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a kamera jobban ráközelít, a kerek hold ... az egész képet.'::text,'kitölti'::text,'kitöltené'::text,'kitöltötte'::text,'Ha a kamera jobban ráközelít, a kerek hold kitölti az egész képet.'::text),
(382269,42475,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn der Mond nicht rund wäre, ... sein Rand im Teleskop nicht so gebogen aus.'::text,'sähe'::text,'wird'::text,'sieht'::text,'Wenn der Mond nicht rund wäre, sähe sein Rand im Teleskop nicht so gebogen aus.'::text),
(382273,42475,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби місяць не був круглим, його край ... таким вигнутим у телескопі.'::text,'не виглядав би'::text,'не виглядатиме'::text,'не виглядає'::text,'Якби місяць не був круглим, його край не виглядав би таким вигнутим у телескопі.'::text),
(382272,42475,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la luna no fuera redonda, su borde no ... tan curvo en el telescopio.'::text,'se vería'::text,'se verá'::text,'se ve'::text,'Si la luna no fuera redonda, su borde no se vería tan curvo en el telescopio.'::text),
(382271,42475,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la lune n''était pas ronde, son bord ... aussi courbé dans le télescope.'::text,'ne paraîtrait pas'::text,'ne paraîtra pas'::text,'ne paraît pas'::text,'Si la lune n''était pas ronde, son bord ne paraîtrait pas aussi courbé dans le télescope.'::text),
(382274,42475,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ay yuvarlak olmasaydı kenarı teleskopta bu kadar kavisli ...'::text,'görünmezdi'::text,'görünmeyecek'::text,'görünmüyor'::text,'Ay yuvarlak olmasaydı kenarı teleskopta bu kadar kavisli görünmezdi.'::text),
(382275,42475,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a hold nem lenne kerek, a széle ... ilyen íveltnek a távcsőben.'::text,'nem tűnne'::text,'nem fog tűnni'::text,'nem tűnik'::text,'Ha a hold nem lenne kerek, a széle nem tűnne ilyen íveltnek a távcsőben.'::text),
(382278,42476,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der runde Mond ... aus einem Garten mit einem Teleskop gefilmt. Bahnbrechende Arbeit, offensichtlich.'::text,'wurde'::text,'filmte'::text,'filmt'::text,'Der runde Mond wurde aus einem Garten mit einem Teleskop gefilmt. Bahnbrechende Arbeit, offensichtlich.'::text),
(382282,42476,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Круглий місяць ... із саду в телескоп. Проривна робота, очевидно.'::text,'зняли'::text,'зняв'::text,'знімає'::text,'Круглий місяць зняли із саду в телескоп. Проривна робота, очевидно.'::text),
(382281,42476,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La luna redonda ... desde un jardín con un telescopio. Un trabajo revolucionario, obviamente.'::text,'fue grabada'::text,'grabó'::text,'está grabando'::text,'La luna redonda fue grabada desde un jardín con un telescopio. Un trabajo revolucionario, obviamente.'::text),
(382280,42476,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La lune ronde ... depuis un jardin avec un télescope. Un travail révolutionnaire, évidemment.'::text,'a été filmée'::text,'a filmé'::text,'filme'::text,'La lune ronde a été filmée depuis un jardin avec un télescope. Un travail révolutionnaire, évidemment.'::text),
(382283,42476,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yuvarlak ay bir bahçeden teleskopla ..., çığır açan bir iş, belli ki.'::text,'çekildi'::text,'çekti'::text,'çekiyor'::text,'Yuvarlak ay bir bahçeden teleskopla çekildi, çığır açan bir iş, belli ki.'::text),
(382284,42476,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kerek holdat egy kertből ... távcsővel. Úttörő munka, nyilván.'::text,'vették fel'::text,'felvette'::text,'veszi fel'::text,'A kerek holdat egy kertből vették fel távcsővel. Úttörő munka, nyilván.'::text),
(382287,42477,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Kamera ... an den runden Mond heran, bis er das Bild füllte.'::text,'zoomte'::text,'wurde gezoomt'::text,'zoomend'::text,'Die Kamera zoomte an den runden Mond heran, bis er das Bild füllte.'::text),
(382291,42477,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Камера ... круглий місяць, аж поки він не заповнив кадр.'::text,'наближала'::text,'була наближена'::text,'наближаючи'::text,'Камера наближала круглий місяць, аж поки він не заповнив кадр.'::text),
(382290,42477,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La cámara ... sobre la luna redonda hasta que llenó el encuadre.'::text,'hizo zoom'::text,'fue ampliada'::text,'haciendo zoom'::text,'La cámara hizo zoom sobre la luna redonda hasta que llenó el encuadre.'::text),
(382289,42477,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La caméra ... sur la lune ronde jusqu''à ce qu''elle remplisse le cadre.'::text,'a zoomé'::text,'a été zoomée'::text,'zoomant'::text,'La caméra a zoomé sur la lune ronde jusqu''à ce qu''elle remplisse le cadre.'::text),
(382292,42477,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kamera, kadrajı doldurana kadar yuvarlak aya ...'::text,'yakınlaştı'::text,'yakınlaştırıldı'::text,'yakınlaşarak'::text,'Kamera, kadrajı doldurana kadar yuvarlak aya yakınlaştı.'::text),
(382293,42477,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kamera addig ... a kerek holdra, amíg az ki nem töltötte a képet.'::text,'zoomolt'::text,'zoomolva lett'::text,'zoomolva'::text,'A kamera addig zoomolt a kerek holdra, amíg az ki nem töltötte a képet.'::text),
(382296,42478,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der runde Mond ... noch 3 Stunden sichtbar sein, aber die Vorhersage ist nicht sicher.'::text,'könnte'::text,'muss'::text,'sollte'::text,'Der runde Mond könnte noch 3 Stunden sichtbar sein, aber die Vorhersage ist nicht sicher.'::text),
(382300,42478,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Круглий місяць ... бути видимим ще 3 години, але прогноз не певний.'::text,'може'::text,'мусить'::text,'має'::text,'Круглий місяць може бути видимим ще 3 години, але прогноз не певний.'::text),
(382299,42478,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La luna redonda ... ser visible 3 horas más, pero el pronóstico no es seguro.'::text,'podría'::text,'debe de'::text,'debería'::text,'La luna redonda podría ser visible 3 horas más, pero el pronóstico no es seguro.'::text),
(382298,42478,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La lune ronde ... être visible encore 3 heures, mais la prévision n''est pas sûre.'::text,'pourrait'::text,'doit'::text,'devrait'::text,'La lune ronde pourrait être visible encore 3 heures, mais la prévision n''est pas sûre.'::text),
(382301,42478,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yuvarlak ay 3 saat daha görünür ..., ama tahmin kesin değil.'::text,'olabilir'::text,'olmalı'::text,'olması gerek'::text,'Yuvarlak ay 3 saat daha görünür olabilir, ama tahmin kesin değil.'::text),
(382302,42478,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kerek hold még 3 óráig látható ..., de az előrejelzés nem biztos.'::text,'lehet'::text,'biztosan lesz'::text,'kellene legyen'::text,'A kerek hold még 3 óráig látható lehet, de az előrejelzés nem biztos.'::text),
(382305,42479,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Teleskop, ... den runden Mond gefilmt hat, kostete 400 Euro vom Budget.'::text,'das'::text,'wer'::text,'dessen'::text,'Das Teleskop, das den runden Mond gefilmt hat, kostete 400 Euro vom Budget.'::text),
(382309,42479,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Телескоп, ... зняв круглий місяць, коштував 400 євро з бюджету.'::text,'який'::text,'хто'::text,'чий'::text,'Телескоп, який зняв круглий місяць, коштував 400 євро з бюджету.'::text),
(382308,42479,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El telescopio ... grabó la luna redonda costó 400 euros del presupuesto.'::text,'que'::text,'quien'::text,'cuyo'::text,'El telescopio que grabó la luna redonda costó 400 euros del presupuesto.'::text),
(382307,42479,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le télescope ... a filmé la lune ronde a coûté 400 euros du budget.'::text,'qui'::text,'qui'::text,'dont'::text,'Le télescope qui a filmé la lune ronde a coûté 400 euros du budget.'::text),
(382310,42479,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yuvarlak ayı ... teleskop bütçeden 400 euroya mal oldu.'::text,'çeken'::text,'kim'::text,'kimin'::text,'Yuvarlak ayı çeken teleskop bütçeden 400 euroya mal oldu.'::text),
(382311,42479,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A távcső, ... felvette a kerek holdat, 400 euróba került a költségvetésből.'::text,'amely'::text,'aki'::text,'akinek a'::text,'A távcső, amely felvette a kerek holdat, 400 euróba került a költségvetésből.'::text),
(382314,42480,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Im Bericht stand, der runde Mond ... um 22:00 Uhr sichtbar sein.'::text,'würde'::text,'wird'::text,'ist'::text,'Im Bericht stand, der runde Mond würde um 22:00 Uhr sichtbar sein.'::text),
(382318,42480,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У звіті було сказано, що круглий місяць ... видимим о 22:00.'::text,'буде'::text,'буде'::text,'є'::text,'У звіті було сказано, що круглий місяць буде видимим о 22:00.'::text),
(382317,42480,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El informe decía que la luna redonda ... visible a las 22:00.'::text,'sería'::text,'será'::text,'está siendo'::text,'El informe decía que la luna redonda sería visible a las 22:00.'::text),
(382316,42480,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le rapport disait que la lune ronde ... visible à 22 h.'::text,'serait'::text,'sera'::text,'est'::text,'Le rapport disait que la lune ronde serait visible à 22 h.'::text),
(382319,42480,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rapor, yuvarlak ayın saat 22:00''de görünür ... söylüyordu.'::text,'olacağını'::text,'olacağını'::text,'olduğunu'::text,'Rapor, yuvarlak ayın saat 22:00''de görünür olacağını söylüyordu.'::text),
(382320,42480,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A jelentés szerint a kerek hold 22:00-kor látható ...'::text,'lesz'::text,'lesz'::text,NULL::text,'A jelentés szerint a kerek hold 22:00-kor látható lesz.'::text),
(382332,42482,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Astronomen genießen ... des runden Mondes, da seine Krater deutlich zu erkennen sind.'::text,'das Beobachten'::text,'zu beobachten'::text,'beobachten'::text,'Astronomen genießen das Beobachten des runden Mondes, da seine Krater deutlich zu erkennen sind.'::text),
(382336,42482,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Астрономи люблять ... круглий місяць, адже його кратери чітко видно.'::text,'спостерігати'::text,'спостереження'::text,'спостерігати'::text,'Астрономи люблять спостерігати круглий місяць, адже його кратери чітко видно.'::text),
(382335,42482,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A los astrónomos les encanta ... la luna redonda, ya que sus cráteres son claramente observables.'::text,'observar'::text,'observando'::text,'observa'::text,'A los astrónomos les encanta observar la luna redonda, ya que sus cráteres son claramente observables.'::text),
(382334,42482,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les astronomes adorent ... la lune ronde, car ses cratères sont clairement observables.'::text,'observer'::text,'observant'::text,'observent'::text,'Les astronomes adorent observer la lune ronde, car ses cratères sont clairement observables.'::text),
(382337,42482,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gökbilimciler yuvarlak ayı ... seviyor, çünkü kraterleri açıkça gözlemlenebiliyor.'::text,'izlemeyi'::text,'izlemek'::text,'izle'::text,'Gökbilimciler yuvarlak ayı izlemeyi seviyor, çünkü kraterleri açıkça gözlemlenebiliyor.'::text),
(382338,42482,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A csillagászok szeretik ... a kerek holdat, mivel a kráterei jól megfigyelhetők.'::text,'nézni'::text,'nézés'::text,'néz'::text,'A csillagászok szeretik nézni a kerek holdat, mivel a kráterei jól megfigyelhetők.'::text),
(382341,42483,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Mond sieht heute Abend rund und hell aus, ...?'::text,'oder?'::text,'oder?'::text,'oder?'::text,'Der Mond sieht heute Abend rund und hell aus, oder?'::text),
(382345,42483,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Місяць сьогодні ввечері виглядає круглим і яскравим, ...?'::text,'правда?'::text,'правда?'::text,'правда?'::text,'Місяць сьогодні ввечері виглядає круглим і яскравим, правда?'::text),
(382344,42483,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La luna se ve redonda y brillante esta noche, ...?'::text,'¿verdad?'::text,'¿verdad?'::text,'¿verdad?'::text,'La luna se ve redonda y brillante esta noche, ¿verdad?'::text),
(382343,42483,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La lune a l''air ronde et brillante ce soir, ... ?'::text,'non ?'::text,'non ?'::text,'non ?'::text,'La lune a l''air ronde et brillante ce soir, non ?'::text),
(382346,42483,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ay bu gece yuvarlak ve parlak görünüyor, ...?'::text,'değil mi?'::text,'değil mi?'::text,'değil mi?'::text,'Ay bu gece yuvarlak ve parlak görünüyor, değil mi?'::text),
(382347,42483,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A hold ma este kereknek és fényesnek tűnik, ...?'::text,'ugye?'::text,'ugye?'::text,'ugye?'::text,'A hold ma este kereknek és fényesnek tűnik, ugye?'::text),
(382350,42484,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Mond ist rund, und ...'::text,'die Krater darauf auch.'::text,'die Krater darauf auch.'::text,'die Krater darauf auch nicht.'::text,'Der Mond ist rund, und die Krater darauf auch.'::text),
(382354,42484,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Місяць круглий, і ...'::text,'кратери на ньому теж.'::text,'кратери на ньому теж.'::text,'кратери на ньому теж ні.'::text,'Місяць круглий, і кратери на ньому теж.'::text),
(382353,42484,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La luna es redonda, y ...'::text,'los cráteres que tiene también.'::text,'los cráteres que tiene también.'::text,'los cráteres que tiene tampoco.'::text,'La luna es redonda, y los cráteres que tiene también.'::text),
(382352,42484,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La lune est ronde, et ...'::text,'ses cratères aussi.'::text,'ses cratères aussi.'::text,'ses cratères non plus.'::text,'La lune est ronde, et ses cratères aussi.'::text),
(382355,42484,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ay yuvarlak, ...'::text,'üzerindeki kraterler de.'::text,'üzerindeki kraterler de.'::text,'üzerindeki kraterler de değil.'::text,'Ay yuvarlak, üzerindeki kraterler de.'::text),
(382356,42484,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A hold kerek, és ...'::text,'a rajta lévő kráterek is.'::text,'a rajta lévő kráterek is.'::text,'a rajta lévő kráterek sem.'::text,'A hold kerek, és a rajta lévő kráterek is.'::text),
(402060,44674,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Kühe ... schon eine Weile auf dem einzigen Durchgang, bevor der Fahrer kam.'::text,'standen'::text,'stehen'::text,'stehen'::text,'Die Kühe standen schon eine Weile auf dem einzigen Durchgang, bevor der Fahrer kam.'::text),
(402064,44674,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Корови ... на єдиному проході вже якийсь час, перш ніж приїхав велосипедист.'::text,'стояли'::text,'стоять'::text,'стоять'::text,'Корови стояли на єдиному проході вже якийсь час, перш ніж приїхав велосипедист.'::text),
(402063,44674,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Las vacas ... un rato plantadas en el único paso antes de que llegara el ciclista.'::text,'llevaban'::text,'llevan'::text,'están'::text,'Las vacas llevaban un rato plantadas en el único paso antes de que llegara el ciclista.'::text),
(402062,44674,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les vaches ... sur le seul passage depuis un moment avant que le cycliste arrive.'::text,'étaient plantées'::text,'sont plantées'::text,'sont plantées'::text,'Les vaches étaient plantées sur le seul passage depuis un moment avant que le cycliste arrive.'::text),
(402065,44674,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bisikletçi gelmeden önce inekler bir süredir tek geçiş yolunda ...'::text,'duruyordu'::text,'duruyor'::text,'duruyor'::text,'Bisikletçi gelmeden önce inekler bir süredir tek geçiş yolunda duruyordu.'::text),
(402066,44674,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tehenek már egy ideje ... az egyetlen átjárón, mielőtt a biciklis megérkezett.'::text,'álltak'::text,'állnak'::text,'állnak'::text,'A tehenek már egy ideje álltak az egyetlen átjárón, mielőtt a biciklis megérkezett.'::text),
(402069,44675,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis der Fahrer das Tal erreicht, ... ihm die Kühe längst aus dem Weg gegangen.'::text,'sind'::text,'gehen'::text,'werden'::text,'Bis der Fahrer das Tal erreicht, sind ihm die Kühe längst aus dem Weg gegangen.'::text),
(402073,44675,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки велосипедист дістанеться долини, корови ... йому з дороги.'::text,'зійдуть'::text,'зійдуть'::text,'сходитимуть'::text,'Поки велосипедист дістанеться долини, корови зійдуть йому з дороги.'::text),
(402072,44675,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando el ciclista llegue al valle, las vacas ya se ... de su camino.'::text,'habrán apartado'::text,'apartarán'::text,'estarán apartando'::text,'Para cuando el ciclista llegue al valle, las vacas ya se habrán apartado de su camino.'::text),
(402071,44675,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici à ce que le cycliste atteigne la vallée, les vaches ... de son chemin.'::text,'se seront écartées'::text,'s''écarteront'::text,'seront en train de s''écarter'::text,'D''ici à ce que le cycliste atteigne la vallée, les vaches se seront écartées de son chemin.'::text),
(402074,44675,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bisikletçi vadiye varana kadar inekler yolundan ...'::text,'çekilmiş olacak'::text,'çekilecek'::text,'çekiliyor olacak'::text,'Bisikletçi vadiye varana kadar inekler yolundan çekilmiş olacak.'::text),
(402075,44675,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire a biciklis leér a völgybe, a tehenek már ... az útjából.'::text,'kiállnak'::text,'ki fognak állni'::text,'éppen kiállnak'::text,'Mire a biciklis leér a völgybe, a tehenek már kiállnak az útjából.'::text),
(402078,44676,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, angeblich ... die Kühe bis Mittag schon drei Stunden im Weg des Fahrers.'::text,'stehen'::text,'stehen'::text,'stehen'::text,'Mädel, angeblich stehen die Kühe bis Mittag schon drei Stunden im Weg des Fahrers.'::text),
(402082,44676,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, до обіду ті корови ... на шляху велосипедиста три години.'::text,'стоятимуть'::text,'стоятимуть'::text,'стоятимуть'::text,'Подруго, кажуть, до обіду ті корови стоятимуть на шляху велосипедиста три години.'::text),
(402081,44676,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, al parecer al mediodía esas vacas ... tres horas en medio del camino del ciclista.'::text,'llevarán plantadas'::text,'estarán plantadas'::text,'estarán plantadas'::text,'Tía, al parecer al mediodía esas vacas llevarán plantadas tres horas en medio del camino del ciclista.'::text),
(402080,44676,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, apparemment à midi ces vaches ... sur le chemin du cycliste depuis trois heures.'::text,'seront plantées'::text,'seront plantées'::text,'seront plantées'::text,'Meuf, apparemment à midi ces vaches seront plantées sur le chemin du cycliste depuis trois heures.'::text),
(402083,44676,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, güya öğlene kadar o inekler üç saattir bisikletçinin yolunda ...'::text,'duruyor olacakmış'::text,'duracakmış'::text,'duruyor olacakmış'::text,'Kızım, güya öğlene kadar o inekler üç saattir bisikletçinin yolunda duruyor olacakmış.'::text),
(402084,44676,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag délre azok a tehenek már három órája ... a biciklis útjában.'::text,'állnak majd'::text,'állnak majd'::text,'fognak állni'::text,'Csajszi, állítólag délre azok a tehenek már három órája állnak majd a biciklis útjában.'::text),
(402087,44677,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn die Kühe nicht ausgewichen wären, ... der Fahrer einen anderen Weg den Grat hinunter gefunden.'::text,'hätte'::text,'wird'::text,'fand'::text,'Wenn die Kühe nicht ausgewichen wären, hätte der Fahrer einen anderen Weg den Grat hinunter gefunden.'::text),
(402091,44677,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби корови не відійшли, велосипедист ... інший шлях униз із хребта.'::text,'знайшов би'::text,'знайде'::text,'знайшов'::text,'Якби корови не відійшли, велосипедист знайшов би інший шлях униз із хребта.'::text),
(402090,44677,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si las vacas no se hubieran apartado, el ciclista ... otro camino para bajar de la cresta.'::text,'habría encontrado'::text,'encontrará'::text,'encontró'::text,'Si las vacas no se hubieran apartado, el ciclista habría encontrado otro camino para bajar de la cresta.'::text),
(402089,44677,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si les vaches ne s''étaient pas écartées, le cycliste ... un autre chemin pour descendre de la crête.'::text,'aurait trouvé'::text,'trouvera'::text,'a trouvé'::text,'Si les vaches ne s''étaient pas écartées, le cycliste aurait trouvé un autre chemin pour descendre de la crête.'::text),
(402092,44677,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İnekler çekilmeseydi bisikletçi sırttan aşağı başka bir yol ...'::text,'bulurdu'::text,'bulacak'::text,'buldu'::text,'İnekler çekilmeseydi bisikletçi sırttan aşağı başka bir yol bulurdu.'::text),
(402093,44677,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a tehenek nem álltak volna félre, a biciklis ... egy másik utat le a gerincről.'::text,'talált volna'::text,'talál majd'::text,'talált'::text,'Ha a tehenek nem álltak volna félre, a biciklis talált volna egy másik utat le a gerincről.'::text),
(402105,44679,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Man nimmt an, dass der Pfad der einzige Weg entlang des Grats ...'::text,'ist'::text,'ist'::text,'sein'::text,'Man nimmt an, dass der Pfad der einzige Weg entlang des Grats ist.'::text),
(402109,44679,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вважається, що стежка ... єдиним шляхом уздовж хребта.'::text,'є'::text,'є'::text,'буття'::text,'Вважається, що стежка є єдиним шляхом уздовж хребта.'::text),
(402108,44679,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Se cree que el sendero ... el único camino por la cresta.'::text,'es'::text,'es'::text,'siendo'::text,'Se cree que el sendero es el único camino por la cresta.'::text),
(402107,44679,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'On pense que le sentier ... le seul chemin le long de la crête.'::text,'est'::text,'est'::text,'étant'::text,'On pense que le sentier est le seul chemin le long de la crête.'::text),
(402110,44679,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Patikanın sırt boyunca tek yol ... düşünülüyor.'::text,'olduğu'::text,'olduğu'::text,'olmak'::text,'Patikanın sırt boyunca tek yol olduğu düşünülüyor.'::text),
(402111,44679,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Úgy tartják, hogy az ösvény ... az egyetlen út a gerinc mentén.'::text,''::text,NULL::text,'lévén'::text,'Úgy tartják, hogy az ösvény az egyetlen út a gerinc mentén.'::text),
(402114,44680,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Fahrer bat die Kuh höflich, aus dem Weg ...'::text,'zu gehen'::text,'gehend'::text,'gehen'::text,'Der Fahrer bat die Kuh höflich, aus dem Weg zu gehen.'::text),
(402118,44680,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Велосипедист чемно попросив корову ... з дороги.'::text,'зійти'::text,'сходження'::text,'зійти'::text,'Велосипедист чемно попросив корову зійти з дороги.'::text),
(402117,44680,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El ciclista le pidió amablemente a la vaca que ... de su camino.'::text,'se apartara'::text,'apartándose'::text,'se aparta'::text,'El ciclista le pidió amablemente a la vaca que se apartara de su camino.'::text),
(402116,44680,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le cycliste a poliment demandé à la vache de ... de son chemin.'::text,'s''écarter'::text,'s''écartant'::text,'s''écarte'::text,'Le cycliste a poliment demandé à la vache de s''écarter de son chemin.'::text),
(402119,44680,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bisikletçi kibarca inekten yolundan ... istedi.'::text,'çekilmesini'::text,'çekilme'::text,'çekil'::text,'Bisikletçi kibarca inekten yolundan çekilmesini istedi.'::text),
(402120,44680,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A biciklis udvariasan megkérte a tehenet, hogy ... az útjából.'::text,'álljon ki'::text,'kiállás'::text,'kiáll'::text,'A biciklis udvariasan megkérte a tehenet, hogy álljon ki az útjából.'::text),
(402123,44681,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Fahrer ... sich keine Sorgen machen müssen; die Kühe gingen ihm sofort aus dem Weg.'::text,'hätte'::text,'durfte'::text,'konnte'::text,'Der Fahrer hätte sich keine Sorgen machen müssen; die Kühe gingen ihm sofort aus dem Weg.'::text),
(402127,44681,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Велосипедистові ... хвилюватися; корови одразу зійшли йому з дороги.'::text,'не треба було'::text,'не можна було'::text,'не могло бути'::text,'Велосипедистові не треба було хвилюватися; корови одразу зійшли йому з дороги.'::text),
(402126,44681,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El ciclista no ... preocuparse; las vacas se apartaron de su camino al instante.'::text,'tenía por qué'::text,'debía'::text,'podía'::text,'El ciclista no tenía por qué preocuparse; las vacas se apartaron de su camino al instante.'::text),
(402125,44681,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le cycliste ... s''inquiéter ; les vaches se sont écartées de son chemin aussitôt.'::text,'n''avait pas besoin de'::text,'ne devait pas'::text,'ne pouvait pas'::text,'Le cycliste n''avait pas besoin de s''inquiéter ; les vaches se sont écartées de son chemin aussitôt.'::text),
(402128,44681,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bisikletçinin endişelenmesine ...; inekler hemen yolundan çekildi.'::text,'gerek yoktu'::text,'izin yoktu'::text,'imkân yoktu'::text,'Bisikletçinin endişelenmesine gerek yoktu; inekler hemen yolundan çekildi.'::text),
(402129,44681,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A biciklisnek ... aggódnia; a tehenek azonnal kiálltak az útjából.'::text,'nem kellett volna'::text,'nem lett volna szabad'::text,'nem lehetett'::text,'A biciklisnek nem kellett volna aggódnia; a tehenek azonnal kiálltak az útjából.'::text),
(402132,44682,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Selten ... blockiert Vieh den einzigen Weg über einen so schmalen Grat, wie hier dokumentiert.'::text,''::text,NULL::text,NULL::text,'Selten blockiert Vieh den einzigen Weg über einen so schmalen Grat, wie hier dokumentiert.'::text),
(402136,44682,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Рідко ... худоба перекриває єдиний шлях таким вузьким хребтом, як тут задокументовано.'::text,''::text,NULL::text,NULL::text,'Рідко худоба перекриває єдиний шлях таким вузьким хребтом, як тут задокументовано.'::text),
(402135,44682,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rara vez ... el ganado bloquea el único camino por una cresta tan estrecha, como se documenta aquí.'::text,''::text,NULL::text,NULL::text,'Rara vez el ganado bloquea el único camino por una cresta tan estrecha, como se documenta aquí.'::text),
(402134,44682,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rarement ... le bétail bloque le seul chemin sur une crête aussi étroite, comme documenté ici.'::text,''::text,NULL::text,NULL::text,'Rarement le bétail bloque le seul chemin sur une crête aussi étroite, comme documenté ici.'::text),
(402137,44682,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sığırlar böylesine dar bir sırttaki tek yolu nadiren ... kapatır, burada belgelendiği gibi.'::text,''::text,NULL::text,NULL::text,'Sığırlar böylesine dar bir sırttaki tek yolu nadiren kapatır, burada belgelendiği gibi.'::text),
(402138,44682,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ritkán ... zárja el a marha az egyetlen utat egy ilyen keskeny gerincen, ahogy itt dokumentálva van.'::text,''::text,NULL::text,NULL::text,'Ritkán zárja el a marha az egyetlen utat egy ilyen keskeny gerincen, ahogy itt dokumentálva van.'::text),
(402141,44683,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Subjekt bringt das Vieh dazu, den Weg ..., indem es ein Tier zur Seite schiebt.'::text,'freizumachen'::text,'freimachen'::text,'freigemacht'::text,'Das Subjekt bringt das Vieh dazu, den Weg freizumachen, indem es ein Tier zur Seite schiebt.'::text),
(402145,44683,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Суб''єкт змушує худобу ... шлях, відштовхнувши одну тварину вбік.'::text,'звільнити'::text,'звільнити'::text,'звільнений'::text,'Суб''єкт змушує худобу звільнити шлях, відштовхнувши одну тварину вбік.'::text),
(402144,44683,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El sujeto consigue que el ganado ... el camino apartando a un animal.'::text,'despeje'::text,'despejar'::text,'despejado'::text,'El sujeto consigue que el ganado despeje el camino apartando a un animal.'::text),
(402143,44683,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le sujet pousse le bétail à ... le chemin en écartant une bête.'::text,'libérer'::text,'libère'::text,'libéré'::text,'Le sujet pousse le bétail à libérer le chemin en écartant une bête.'::text),
(402146,44683,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Özne, birini kenara iterek sığırların yolu ... sağlıyor.'::text,'açmasını'::text,'aç'::text,'açılmış'::text,'Özne, birini kenara iterek sığırların yolu açmasını sağlıyor.'::text),
(402147,44683,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az alany ráveszi a marhákat, hogy ... az utat, azzal, hogy az egyiket félretolja.'::text,'szabadítsák fel'::text,'felszabadítani'::text,'felszabadított'::text,'Az alany ráveszi a marhákat, hogy szabadítsák fel az utat, azzal, hogy az egyiket félretolja.'::text),
(402150,44684,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Fahrer wünscht sich offensichtlich, das Vieh ... den Weg früher freigemacht.'::text,'hätte'::text,'hat'::text,'macht'::text,'Der Fahrer wünscht sich offensichtlich, das Vieh hätte den Weg früher freigemacht.'::text),
(402154,44684,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Велосипедист, очевидно, хотів би, щоб худоба ... шлях раніше.'::text,'звільнила'::text,'звільнила'::text,'звільняє'::text,'Велосипедист, очевидно, хотів би, щоб худоба звільнила шлях раніше.'::text),
(402153,44684,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Evidentemente, el ciclista desearía que el ganado ... el camino antes.'::text,'hubiera despejado'::text,'ha despejado'::text,'despeja'::text,'Evidentemente, el ciclista desearía que el ganado hubiera despejado el camino antes.'::text),
(402152,44684,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Visiblement, le cycliste aurait aimé que le bétail ... le chemin plus tôt.'::text,'ait libéré'::text,'a libéré'::text,'libère'::text,'Visiblement, le cycliste aurait aimé que le bétail ait libéré le chemin plus tôt.'::text),
(402155,44684,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bisikletçi belli ki keşke sığırlar yolu daha önce ... diye düşünüyor.'::text,'açsaydı'::text,'açtı'::text,'açıyor'::text,'Bisikletçi belli ki keşke sığırlar yolu daha önce açsaydı diye düşünüyor.'::text),
(402156,44684,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A biciklis láthatóan azt kívánja, bárcsak a marhák hamarabb ... az utat.'::text,'szabadították volna fel'::text,'felszabadították'::text,'felszabadítják'::text,'A biciklis láthatóan azt kívánja, bárcsak a marhák hamarabb szabadították volna fel az utat.'::text),
(373125,41459,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Welpe ... die Wurst mit großer Geduld, bevor er endlich losschnellte.'::text,'beobachtete'::text,'beobachtet'::text,'beobachtet'::text,'Der Welpe beobachtete die Wurst mit großer Geduld, bevor er endlich losschnellte.'::text),
(373129,41459,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Цуценя ... за ковбаскою з великим терпінням, перш ніж нарешті кинулося вперед.'::text,'стежило'::text,'стежить'::text,'стежить'::text,'Цуценя стежило за ковбаскою з великим терпінням, перш ніж нарешті кинулося вперед.'::text),
(373128,41459,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El cachorro ... la salchicha con gran paciencia antes de lanzarse por fin.'::text,'llevaba un rato observando'::text,'lleva observando'::text,'observa'::text,'El cachorro llevaba un rato observando la salchicha con gran paciencia antes de lanzarse por fin.'::text),
(373127,41459,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le chiot ... la saucisse avec une grande patience avant de finalement bondir.'::text,'observait depuis un moment'::text,'observe depuis un moment'::text,'observe'::text,'Le chiot observait depuis un moment la saucisse avec une grande patience avant de finalement bondir.'::text),
(373130,41459,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Köpek yavrusu sonunda atılmadan önce sosisi büyük bir sabırla ...'::text,'izliyordu'::text,'izliyor'::text,'izler'::text,'Köpek yavrusu sonunda atılmadan önce sosisi büyük bir sabırla izliyordu.'::text),
(373131,41459,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kiskutya nagy türelemmel ... a kolbászt, mielőtt végül rávetette magát.'::text,'figyelte'::text,'figyeli'::text,'figyeli'::text,'A kiskutya nagy türelemmel figyelte a kolbászt, mielőtt végül rávetette magát.'::text),
(373134,41460,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis zum Ende dieses Videos ... der Welpe seine ganze Geduld verloren.'::text,'hat'::text,'verliert'::text,'verliert'::text,'Bis zum Ende dieses Videos hat der Welpe seine ganze Geduld verloren.'::text),
(373138,41460,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До кінця цього відео цуценя ... все своє терпіння.'::text,'втратить'::text,'втратить'::text,'втрачає'::text,'До кінця цього відео цуценя втратить все своє терпіння.'::text),
(373137,41460,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para el final de este vídeo, el cachorro ... toda su paciencia.'::text,'habrá perdido'::text,'perderá'::text,'pierde'::text,'Para el final de este vídeo, el cachorro habrá perdido toda su paciencia.'::text),
(373136,41460,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici la fin de cette vidéo, le chiot ... toute sa patience.'::text,'aura perdu'::text,'perdra'::text,'perd'::text,'D''ici la fin de cette vidéo, le chiot aura perdu toute sa patience.'::text),
(373139,41460,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu videonun sonunda köpek yavrusu bütün sabrını ...'::text,'yitirmiş olacak'::text,'yitirecek'::text,'yitiriyor'::text,'Bu videonun sonunda köpek yavrusu bütün sabrını yitirmiş olacak.'::text),
(373140,41460,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A videó végére a kiskutya ... minden türelmét.'::text,'elveszíti'::text,'el fogja veszíteni'::text,'veszíti'::text,'A videó végére a kiskutya elveszíti minden türelmét.'::text),
(373143,41461,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis er sich die Wurst schnappt, ... der Welpe fast eine Minute lang geduldig gewartet.'::text,'hat'::text,'wird'::text,'wird'::text,'Bis er sich die Wurst schnappt, hat der Welpe fast eine Minute lang geduldig gewartet.'::text),
(373147,41461,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки воно схопить ковбаску, цуценя ... терпляче майже хвилину.'::text,'чекатиме'::text,'чекатиме'::text,'чекатиме'::text,'Поки воно схопить ковбаску, цуценя чекатиме терпляче майже хвилину.'::text),
(373146,41461,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando agarre la salchicha, el cachorro ... con paciencia casi un minuto.'::text,'llevará esperando'::text,'estará esperando'::text,'esperará'::text,'Para cuando agarre la salchicha, el cachorro llevará esperando con paciencia casi un minuto.'::text),
(373145,41461,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le temps qu''il attrape la saucisse, le chiot ... patiemment pendant presque une minute.'::text,'aura attendu'::text,'attendra'::text,'attendra'::text,'Le temps qu''il attrape la saucisse, le chiot aura attendu patiemment pendant presque une minute.'::text),
(373148,41461,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sosisi kaptığında köpek yavrusu neredeyse bir dakikadır sabırla ...'::text,'bekliyor olacak'::text,'bekliyor olacak'::text,'bekleyecek'::text,'Sosisi kaptığında köpek yavrusu neredeyse bir dakikadır sabırla bekliyor olacak.'::text),
(373149,41461,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire elkapja a kolbászt, a kiskutya már majdnem egy perce türelmesen ...'::text,'várni fog'::text,'várni fog'::text,'vár majd'::text,'Mire elkapja a kolbászt, a kiskutya már majdnem egy perce türelmesen várni fog.'::text),
(373152,41462,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn der Welpe mehr Geduld gezeigt hätte, ... die Wurst dort ein bisschen länger gestanden.'::text,'hätte'::text,'wird'::text,'stand'::text,'Wenn der Welpe mehr Geduld gezeigt hätte, hätte die Wurst dort ein bisschen länger gestanden.'::text),
(373156,41462,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби цуценя проявило більше терпіння, ковбаска ... там трохи довше.'::text,'простояла б'::text,'стоятиме'::text,'стояла'::text,'Якби цуценя проявило більше терпіння, ковбаска простояла б там трохи довше.'::text),
(373155,41462,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el cachorro hubiera mostrado más paciencia, la salchicha ... en pie un poco más.'::text,'habría seguido'::text,'seguirá'::text,'siguió'::text,'Si el cachorro hubiera mostrado más paciencia, la salchicha habría seguido en pie un poco más.'::text),
(373154,41462,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le chiot avait fait preuve de plus de patience, la saucisse ... là un peu plus longtemps.'::text,'serait restée'::text,'restera'::text,'est restée'::text,'Si le chiot avait fait preuve de plus de patience, la saucisse serait restée là un peu plus longtemps.'::text),
(373157,41462,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Köpek yavrusu daha fazla sabır gösterseydi sosis orada biraz daha uzun ...'::text,'dururdu'::text,'duracak'::text,'durdu'::text,'Köpek yavrusu daha fazla sabır gösterseydi sosis orada biraz daha uzun dururdu.'::text),
(373158,41462,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a kiskutya több türelmet mutatott volna, a kolbász egy kicsit tovább ... ott.'::text,'állt volna'::text,'áll majd'::text,'állt'::text,'Ha a kiskutya több türelmet mutatott volna, a kolbász egy kicsit tovább állt volna ott.'::text),
(373161,41463,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn der Welpe mehr Geduld gehabt hätte, ... die Wurst jetzt noch auf dem Karton.'::text,'stünde'::text,'hätte gestanden'::text,'wird stehen'::text,'Wenn der Welpe mehr Geduld gehabt hätte, stünde die Wurst jetzt noch auf dem Karton.'::text),
(373165,41463,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби цуценя мало більше терпіння, ковбаска ... зараз на картоні.'::text,'ще стояла б'::text,'ще стояла б'::text,'ще стоятиме'::text,'Якби цуценя мало більше терпіння, ковбаска ще стояла б зараз на картоні.'::text),
(373164,41463,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el cachorro hubiera tenido más paciencia, la salchicha ... ahora sobre el cartón.'::text,'seguiría en pie'::text,'habría seguido en pie'::text,'seguirá en pie'::text,'Si el cachorro hubiera tenido más paciencia, la salchicha seguiría en pie ahora sobre el cartón.'::text),
(373163,41463,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le chiot avait eu plus de patience, la saucisse ... encore debout sur le carton maintenant.'::text,'serait'::text,'aurait été'::text,'sera'::text,'Si le chiot avait eu plus de patience, la saucisse serait encore debout sur le carton maintenant.'::text),
(373166,41463,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Köpek yavrusu daha sabırlı olsaydı sosis şimdi hâlâ kartonun üstünde ...'::text,'duruyor olurdu'::text,'durmuş olurdu'::text,'duracak'::text,'Köpek yavrusu daha sabırlı olsaydı sosis şimdi hâlâ kartonun üstünde duruyor olurdu.'::text),
(373167,41463,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a kiskutyának több türelme lett volna, a kolbász most is ... a kartonon.'::text,'állna'::text,'állt volna'::text,'állni fog'::text,'Ha a kiskutyának több türelme lett volna, a kolbász most is állna a kartonon.'::text),
(373179,41465,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Welpe bestand darauf, Geduld zu ..., dann schnappte er sich die Wurst in Sekunden. Makellos.'::text,'zeigen'::text,'zeigen'::text,'zeigt'::text,'Der Welpe bestand darauf, Geduld zu zeigen, dann schnappte er sich die Wurst in Sekunden. Makellos.'::text),
(373183,41465,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Цуценя наполягало на ... терпіння, а потім схопило ковбаску за лічені секунди. Бездоганно.'::text,'проявленні'::text,'проявити'::text,'проявляє'::text,'Цуценя наполягало на проявленні терпіння, а потім схопило ковбаску за лічені секунди. Бездоганно.'::text),
(373182,41465,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El cachorro insistió en ... paciencia y luego agarró la salchicha en segundos. Impecable.'::text,'mostrar'::text,'mostrando'::text,'muestra'::text,'El cachorro insistió en mostrar paciencia y luego agarró la salchicha en segundos. Impecable.'::text),
(373181,41465,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le chiot a tenu à ... de la patience, puis il a attrapé la saucisse en quelques secondes. Impeccable.'::text,'faire preuve'::text,'faisant preuve'::text,'fait preuve'::text,'Le chiot a tenu à faire preuve de la patience, puis il a attrapé la saucisse en quelques secondes. Impeccable.'::text),
(373184,41465,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Köpek yavrusu sabır ... ısrar etti, sonra sosisi saniyeler içinde kaptı. Kusursuz.'::text,'göstermekte'::text,'göstermeye'::text,'göster'::text,'Köpek yavrusu sabır göstermekte ısrar etti, sonra sosisi saniyeler içinde kaptı. Kusursuz.'::text),
(373185,41465,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kiskutya ragaszkodott hozzá, hogy türelmet ..., aztán másodpercek alatt elkapta a kolbászt. Hibátlan.'::text,'mutasson'::text,'mutatni'::text,'mutat'::text,'A kiskutya ragaszkodott hozzá, hogy türelmet mutasson, aztán másodpercek alatt elkapta a kolbászt. Hibátlan.'::text),
(373188,41466,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, der Welpe ... ein bisschen länger warten sollen, aber Geduld ist nicht sein Vibe, echt jetzt.'::text,'hätte'::text,'muss'::text,'hätte nicht'::text,'Digga, der Welpe hätte ein bisschen länger warten sollen, aber Geduld ist nicht sein Vibe, echt jetzt.'::text),
(373192,41466,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, те цуценя ... почекати трохи довше, але терпіння — не його вайб, реально.'::text,'мало б'::text,'мабуть мусило'::text,'могло не'::text,'Бро, те цуценя мало б почекати трохи довше, але терпіння — не його вайб, реально.'::text),
(373191,41466,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, ese cachorro ... esperado un poco más, pero la paciencia no es lo suyo, en serio.'::text,'debería haber'::text,'debe de haber'::text,'no tendría por qué haber'::text,'Bro, ese cachorro debería haber esperado un poco más, pero la paciencia no es lo suyo, en serio.'::text),
(373190,41466,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, ce chiot ... attendre un peu plus, mais la patience c''est pas son truc, sérieux.'::text,'aurait dû'::text,'a dû'::text,'n''avait pas besoin d'''::text,'Frérot, ce chiot aurait dû attendre un peu plus, mais la patience c''est pas son truc, sérieux.'::text),
(373193,41466,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o yavru biraz daha ..., ama sabır onun olayı değil, cidden.'::text,'beklemeliydi'::text,'beklemiş olmalı'::text,'beklemesine gerek yoktu'::text,'Kanka, o yavru biraz daha beklemeliydi, ama sabır onun olayı değil, cidden.'::text),
(373194,41466,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, annak a kutyusnak kicsit tovább ... várnia, de a türelem nem az ő vibe-ja, komolyan.'::text,'kellett volna'::text,'biztos kellett'::text,'nem kellett volna'::text,'Tesó, annak a kutyusnak kicsit tovább kellett volna várnia, de a türelem nem az ő vibe-ja, komolyan.'::text),
(373197,41467,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Erst nach langem Warten ... ging dem Welpen endlich die Geduld aus.'::text,''::text,'war'::text,'hatte'::text,'Erst nach langem Warten ging dem Welpen endlich die Geduld aus.'::text),
(373201,41467,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Лише після довгого очікування ... терпіння цуценяти нарешті урвалося.'::text,''::text,'було'::text,'мало'::text,'Лише після довгого очікування терпіння цуценяти нарешті урвалося.'::text),
(373200,41467,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Solo después de una larga espera ... al cachorro se le acabó por fin la paciencia.'::text,''::text,'estaba'::text,'había'::text,'Solo después de una larga espera al cachorro se le acabó por fin la paciencia.'::text),
(373199,41467,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ce n''est qu''après une longue attente que ... la patience du chiot a fini par s''épuiser.'::text,''::text,'était'::text,'avait'::text,'Ce n''est qu''après une longue attente que la patience du chiot a fini par s''épuiser.'::text),
(373202,41467,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ancak uzun bir beklemenin ardından köpek yavrusunun sabrı nihayet ... tükendi.'::text,''::text,NULL::text,NULL::text,'Ancak uzun bir beklemenin ardından köpek yavrusunun sabrı nihayet tükendi.'::text),
(373203,41467,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csak hosszú várakozás után ... fogyott el végre a kiskutya türelme.'::text,''::text,'volt'::text,'volt'::text,'Csak hosszú várakozás után fogyott el végre a kiskutya türelme.'::text),
(373206,41468,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wir ließen die Geduld des Welpen über 60 Sekunden für den Quartalsbericht ...'::text,'messen'::text,'messen'::text,'zu messen'::text,'Wir ließen die Geduld des Welpen über 60 Sekunden für den Quartalsbericht messen.'::text),
(373210,41468,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ми доручили ... терпіння цуценяти протягом понад 60 секунд для квартального звіту.'::text,'виміряти'::text,'виміряти'::text,'виміряти'::text,'Ми доручили виміряти терпіння цуценяти протягом понад 60 секунд для квартального звіту.'::text),
(373209,41468,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hicimos ... la paciencia del cachorro durante más de 60 segundos para el informe trimestral.'::text,'medir'::text,'medir'::text,'medir'::text,'Hicimos medir la paciencia del cachorro durante más de 60 segundos para el informe trimestral.'::text),
(373208,41468,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nous avons fait ... la patience du chiot sur plus de 60 secondes pour le rapport trimestriel.'::text,'mesurer'::text,'mesurer'::text,'mesurer'::text,'Nous avons fait mesurer la patience du chiot sur plus de 60 secondes pour le rapport trimestriel.'::text),
(373211,41468,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Üç aylık rapor için köpek yavrusunun sabrını 60 saniyeden uzun süre ...'::text,'ölçtürdük'::text,'ölç'::text,'ölçmek'::text,'Üç aylık rapor için köpek yavrusunun sabrını 60 saniyeden uzun süre ölçtürdük.'::text),
(373212,41468,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A negyedéves jelentéshez 60 másodpercen át ... a kiskutya türelmét.'::text,'megmérettük'::text,'mérni'::text,'mérni'::text,'A negyedéves jelentéshez 60 másodpercen át megmérettük a kiskutya türelmét.'::text),
(373215,41469,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Welpe wünschte, er ... mehr Geduld gehabt. Jetzt ist die Wurst für immer weg!'::text,'hätte'::text,'hätte'::text,'hat'::text,'Der Welpe wünschte, er hätte mehr Geduld gehabt. Jetzt ist die Wurst für immer weg!'::text),
(373219,41469,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Цуценя хотіло б, щоб у нього ... більше терпіння. Тепер ковбаска зникла назавжди!'::text,'було'::text,'було б'::text,'є'::text,'Цуценя хотіло б, щоб у нього було більше терпіння. Тепер ковбаска зникла назавжди!'::text),
(373218,41469,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El cachorro desearía ... tenido más paciencia. ¡Ahora la salchicha ha desaparecido para siempre!'::text,'haber'::text,'tener'::text,'tiene'::text,'El cachorro desearía haber tenido más paciencia. ¡Ahora la salchicha ha desaparecido para siempre!'::text),
(373217,41469,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le chiot aimerait ... eu plus de patience. Maintenant, la saucisse a disparu pour toujours !'::text,'avoir'::text,'avoir'::text,'a'::text,'Le chiot aimerait avoir eu plus de patience. Maintenant, la saucisse a disparu pour toujours !'::text),
(373220,41469,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Köpek yavrusu keşke daha çok sabrım ... diyor. Şimdi sosis sonsuza dek gitti!'::text,'olsaydı'::text,'olsa'::text,'var'::text,'Köpek yavrusu keşke daha çok sabrım olsaydı diyor. Şimdi sosis sonsuza dek gitti!'::text),
(373221,41469,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kiskutya azt kívánja, bárcsak ... több türelme; most a kolbász örökre eltűnt!'::text,'lett volna'::text,'lenne'::text,'van'::text,'A kiskutya azt kívánja, bárcsak lett volna több türelme; most a kolbász örökre eltűnt!'::text),
(364575,40509,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Hunde ... ruhig auf dem Rasen, als der Brunnen plötzlich in die Luft schoss!'::text,'standen'::text,'standen'::text,'haben gestanden'::text,'Die Hunde standen ruhig auf dem Rasen, als der Brunnen plötzlich in die Luft schoss!'::text),
(364579,40509,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Собаки спокійно ... на газоні, коли фонтан раптом вибухнув угору!'::text,'стояли'::text,'постояли'::text,'постояли'::text,'Собаки спокійно стояли на газоні, коли фонтан раптом вибухнув угору!'::text),
(364578,40509,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Los perros ... tranquilamente en el césped cuando la fuente de repente estalló en el aire!'::text,'estaban'::text,'estuvieron'::text,'han estado'::text,'¡Los perros estaban tranquilamente en el césped cuando la fuente de repente estalló en el aire!'::text),
(364577,40509,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les chiens ... tranquillement sur la pelouse quand la fontaine a soudain explosé dans les airs !'::text,'étaient'::text,'ont été'::text,'ont été'::text,'Les chiens étaient tranquillement sur la pelouse quand la fontaine a soudain explosé dans les airs !'::text),
(364580,40509,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Köpekler çimenlikte sakince ..., fıskiye aniden havaya patladığında!'::text,'duruyordu'::text,'durdu'::text,'durmuş'::text,'Köpekler çimenlikte sakince duruyordu, fıskiye aniden havaya patladığında!'::text),
(364581,40509,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kutyák nyugodtan ... a gyepen, amikor a szökőkút hirtelen a levegőbe robbant!'::text,'álltak'::text,'álltak'::text,'álltak'::text,'A kutyák nyugodtan álltak a gyepen, amikor a szökőkút hirtelen a levegőbe robbant!'::text),
(364584,40510,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die beiden Exemplare ... seit etwa zehn Minuten auf diesem Rasen.'::text,'spielen'::text,'spielen'::text,'spielen'::text,'Die beiden Exemplare spielen seit etwa zehn Minuten auf diesem Rasen.'::text),
(364588,40510,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дві особини ... на цьому газоні приблизно десять хвилин.'::text,'граються'::text,'граються'::text,'граються'::text,'Дві особини граються на цьому газоні приблизно десять хвилин.'::text),
(364587,40510,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los dos ejemplares ... en este césped aproximadamente diez minutos.'::text,'llevan jugando'::text,'están jugando'::text,'juegan'::text,'Los dos ejemplares llevan jugando en este césped aproximadamente diez minutos.'::text),
(364586,40510,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les deux spécimens ... sur cette pelouse depuis environ dix minutes.'::text,'jouent'::text,'jouent'::text,'jouent'::text,'Les deux spécimens jouent sur cette pelouse depuis environ dix minutes.'::text),
(364589,40510,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İki örnek yaklaşık on dakikadır bu çimenlikte ...'::text,'oynuyor'::text,'oynuyor'::text,'oynar'::text,'İki örnek yaklaşık on dakikadır bu çimenlikte oynuyor.'::text),
(364590,40510,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A két egyed körülbelül tíz perce ... ezen a gyepen.'::text,'játszik'::text,'játszik'::text,'játszik'::text,'A két egyed körülbelül tíz perce játszik ezen a gyepen.'::text),
(364593,40511,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der größere Hund ... über den Rasen und trank aus dem Brunnen.'::text,'lief'::text,'lief gerade'::text,'ist gelaufen'::text,'Der größere Hund lief über den Rasen und trank aus dem Brunnen.'::text),
(364597,40511,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Більший пес ... через газон і попив із фонтана.'::text,'пройшов'::text,'ішов'::text,'пройшов'::text,'Більший пес пройшов через газон і попив із фонтана.'::text),
(364596,40511,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El perro más grande ... por el césped y bebió de la fuente.'::text,'caminó'::text,'estaba caminando'::text,'ha caminado'::text,'El perro más grande caminó por el césped y bebió de la fuente.'::text),
(364595,40511,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le plus grand chien ... la pelouse et a bu à la fontaine.'::text,'a traversé'::text,'traversait'::text,'a traversé'::text,'Le plus grand chien a traversé la pelouse et a bu à la fontaine.'::text),
(364598,40511,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Büyük köpek çimenliği ... ve fıskiyeden su içti.'::text,'geçti'::text,'geçiyordu'::text,'geçmiş'::text,'Büyük köpek çimenliği geçti ve fıskiyeden su içti.'::text),
(364599,40511,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A nagyobb kutya ... a gyepen, és ivott a szökőkútból.'::text,'átsétált'::text,'sétált'::text,'átsétált'::text,'A nagyobb kutya átsétált a gyepen, és ivott a szökőkútból.'::text),
(364611,40513,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Rasen, ... Gras frisch gemäht war, hatte in der Mitte einen blauen Brunnen.'::text,'dessen'::text,'der'::text,'wo'::text,'Der Rasen, dessen Gras frisch gemäht war, hatte in der Mitte einen blauen Brunnen.'::text),
(364615,40513,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Газон, ... трава була щойно скошена, мав посередині синій фонтан.'::text,'чия'::text,'який'::text,'де'::text,'Газон, чия трава була щойно скошена, мав посередині синій фонтан.'::text),
(364614,40513,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El césped, ... hierba estaba recién cortada, tenía una fuente azul en el centro.'::text,'cuya'::text,'que'::text,'donde'::text,'El césped, cuya hierba estaba recién cortada, tenía una fuente azul en el centro.'::text),
(364613,40513,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La pelouse, ... l''herbe était fraîchement tondue, avait une fontaine bleue au milieu.'::text,'dont'::text,'qui'::text,'où'::text,'La pelouse, dont l''herbe était fraîchement tondue, avait une fontaine bleue au milieu.'::text),
(364616,40513,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Otları yeni ... çimenliğin ortasında mavi bir fıskiye vardı.'::text,'biçilmiş'::text,'hangi'::text,'nerede'::text,'Otları yeni biçilmiş çimenliğin ortasında mavi bir fıskiye vardı.'::text),
(364617,40513,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A gyepen, ... füvét frissen nyírták, a közepén egy kék szökőkút volt.'::text,'amelynek a'::text,'amely'::text,'ahol'::text,'A gyepen, amelynek a füvét frissen nyírták, a közepén egy kék szökőkút volt.'::text),
(364620,40514,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Hunde trinken ... aus einem Brunnen auf dem Rasen.'::text,'frisches Wasser'::text,'ein frisches Wasser'::text,'die frischen Wasser'::text,'Die Hunde trinken frisches Wasser aus einem Brunnen auf dem Rasen.'::text),
(364624,40514,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Собаки п''ють ... з фонтана на газоні.'::text,'свіжу воду'::text,'свіжу воду'::text,'свіжі води'::text,'Собаки п''ють свіжу воду з фонтана на газоні.'::text),
(364623,40514,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los perros beben ... de una fuente en el césped.'::text,'agua fresca'::text,'un agua fresca'::text,'las aguas frescas'::text,'Los perros beben agua fresca de una fuente en el césped.'::text),
(364622,40514,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les chiens boivent ... à une fontaine sur la pelouse.'::text,'de l''eau fraîche'::text,'une eau fraîche'::text,'les eaux fraîches'::text,'Les chiens boivent de l''eau fraîche à une fontaine sur la pelouse.'::text),
(364625,40514,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Köpekler çimenlikteki bir fıskiyeden ... içiyor.'::text,'temiz su'::text,'bir temiz su'::text,'temiz suları'::text,'Köpekler çimenlikteki bir fıskiyeden temiz su içiyor.'::text),
(364626,40514,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kutyák ... isznak egy szökőkútból a gyepen.'::text,'friss vizet'::text,'egy friss vizet'::text,'a friss vizeket'::text,'A kutyák friss vizet isznak egy szökőkútból a gyepen.'::text),
(364629,40515,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Hunde blieben auf dem Rasen, ... der Wasserstrahl sie ständig nass spritzte.'::text,'obwohl'::text,'trotz'::text,'falls'::text,'Die Hunde blieben auf dem Rasen, obwohl der Wasserstrahl sie ständig nass spritzte.'::text),
(364633,40515,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Собаки залишалися на газоні, ... струмінь води постійно їх обприскував.'::text,'хоча'::text,'попри'::text,'на випадок, якщо'::text,'Собаки залишалися на газоні, хоча струмінь води постійно їх обприскував.'::text),
(364632,40515,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los perros se quedaron en el césped ... el chorro de agua no paraba de mojarlos.'::text,'aunque'::text,'a pesar de'::text,'por si'::text,'Los perros se quedaron en el césped aunque el chorro de agua no paraba de mojarlos.'::text),
(364631,40515,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les chiens sont restés sur la pelouse ... le jet d''eau n''arrêtait pas de les arroser.'::text,'même si'::text,'malgré'::text,'au cas où'::text,'Les chiens sont restés sur la pelouse même si le jet d''eau n''arrêtait pas de les arroser.'::text),
(364634,40515,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su fışkırması onları durmadan ıslatmasına ... köpekler çimenlikte kaldı.'::text,'rağmen'::text,'rağmen'::text,'ihtimaline karşı'::text,'Su fışkırması onları durmadan ıslatmasına rağmen köpekler çimenlikte kaldı.'::text),
(364635,40515,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kutyák a gyepen maradtak, ... a vízsugár folyamatosan lefröcskölte őket.'::text,'pedig'::text,'annak ellenére'::text,'arra az esetre, ha'::text,'A kutyák a gyepen maradtak, pedig a vízsugár folyamatosan lefröcskölte őket.'::text),
(364638,40516,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Besitzer wusste, dass die Hunde den Brunnen ..., sobald er auf dem Rasen auftauchte.'::text,'lieben würden'::text,'lieben werden'::text,'lieben'::text,'Der Besitzer wusste, dass die Hunde den Brunnen lieben würden, sobald er auf dem Rasen auftauchte.'::text),
(364642,40516,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Власник знав, що собаки ... фонтан, щойно він з''явиться на газоні.'::text,'полюблять'::text,'полюблять'::text,'люблять'::text,'Власник знав, що собаки полюблять фонтан, щойно він з''явиться на газоні.'::text),
(364641,40516,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El dueño sabía que a los perros les ... la fuente en cuanto apareciera en el césped.'::text,'encantaría'::text,'encantará'::text,'encanta'::text,'El dueño sabía que a los perros les encantaría la fuente en cuanto apareciera en el césped.'::text),
(364640,40516,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le propriétaire savait que les chiens ... la fontaine dès qu''elle apparaîtrait sur la pelouse.'::text,'adoreraient'::text,'adoreront'::text,'adorent'::text,'Le propriétaire savait que les chiens adoreraient la fontaine dès qu''elle apparaîtrait sur la pelouse.'::text),
(364643,40516,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sahibi, fıskiye çimenlikte belirir belirmez köpeklerin ona ... biliyordu.'::text,'bayılacağını'::text,'bayılacağını'::text,'bayıldığını'::text,'Sahibi, fıskiye çimenlikte belirir belirmez köpeklerin ona bayılacağını biliyordu.'::text),
(364644,40516,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A gazdi tudta, hogy a kutyák ... a szökőkutat, amint megjelenik a gyepen.'::text,'imádni fogják'::text,'imádni fogják'::text,'imádják'::text,'A gazdi tudta, hogy a kutyák imádni fogják a szökőkutat, amint megjelenik a gyepen.'::text),
(364647,40517,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Derzeit ... der Rasenbrunnen 2 Hunde, im Rahmen des Budgets.'::text,'versorgt'::text,'versorgt'::text,'hat versorgt'::text,'Derzeit versorgt der Rasenbrunnen 2 Hunde, im Rahmen des Budgets.'::text),
(364651,40517,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Наразі фонтан на газоні ... 2 собак, відповідно до бюджету.'::text,'обслуговує'::text,'обслуговує'::text,'обслужив'::text,'Наразі фонтан на газоні обслуговує 2 собак, відповідно до бюджету.'::text),
(364650,40517,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Actualmente, la fuente del césped ... a 2 perros, dentro del presupuesto.'::text,'está dando servicio'::text,'da servicio'::text,'ha dado servicio'::text,'Actualmente, la fuente del césped está dando servicio a 2 perros, dentro del presupuesto.'::text),
(364649,40517,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Actuellement, la fontaine de la pelouse ... 2 chiens, conformément au budget.'::text,'dessert'::text,'dessert'::text,'a desservi'::text,'Actuellement, la fontaine de la pelouse dessert 2 chiens, conformément au budget.'::text),
(364652,40517,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şu anda çimenlikteki fıskiye bütçeye uygun olarak 2 köpeğe ...'::text,'hizmet ediyor'::text,'hizmet eder'::text,'hizmet etti'::text,'Şu anda çimenlikteki fıskiye bütçeye uygun olarak 2 köpeğe hizmet ediyor.'::text),
(364653,40517,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jelenleg a gyepen álló szökőkút 2 kutyát ..., a költségvetéssel összhangban.'::text,'szolgál ki'::text,'kiszolgál'::text,'kiszolgált'::text,'Jelenleg a gyepen álló szökőkút 2 kutyát szolgál ki, a költségvetéssel összhangban.'::text),
(364665,40519,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen um diese Zeit ... die Hunde auf einem komplett überfluteten Rasen!'::text,'planschen'::text,'werden planschen'::text,'planschen'::text,'Morgen um diese Zeit planschen die Hunde auf einem komplett überfluteten Rasen!'::text),
(364669,40519,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра в цей час собаки ... на повністю затопленому газоні!'::text,'хлюпатимуться'::text,'хлюпнуться'::text,'хлюпаються'::text,'Завтра в цей час собаки хлюпатимуться на повністю затопленому газоні!'::text),
(364668,40519,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Mañana a esta hora, los perros ... en un césped completamente inundado!'::text,'estarán chapoteando'::text,'chapotearán'::text,'chapotean'::text,'¡Mañana a esta hora, los perros estarán chapoteando en un césped completamente inundado!'::text),
(364667,40519,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain à cette heure-ci, les chiens ... sur une pelouse complètement inondée !'::text,'barboteront'::text,'barboteront'::text,'barbotent'::text,'Demain à cette heure-ci, les chiens barboteront sur une pelouse complètement inondée !'::text),
(364670,40519,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın bu saatlerde köpekler tamamen su basmış bir çimenlikte ...!'::text,'su sıçratıyor olacak'::text,'su sıçratacak'::text,'su sıçratıyor'::text,'Yarın bu saatlerde köpekler tamamen su basmış bir çimenlikte su sıçratıyor olacak!'::text),
(364671,40519,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap ilyenkor a kutyák egy teljesen elárasztott gyepen ...!'::text,'fognak pancsolni'::text,'pancsolnak majd'::text,'pancsolnak'::text,'Holnap ilyenkor a kutyák egy teljesen elárasztott gyepen fognak pancsolni!'::text),
(367455,40829,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als sie das Einkaufszentrum verließen, ... sie schon fünf Tüten Klamotten gekauft.'::text,'hatte'::text,'hat'::text,'kauft'::text,'Als sie das Einkaufszentrum verließen, hatte sie schon fünf Tüten Klamotten gekauft.'::text),
(367459,40829,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки вони вийшли з торгового центру, вона вже ... п''ять пакетів одягу.'::text,'купила'::text,'купила'::text,'купує'::text,'Поки вони вийшли з торгового центру, вона вже купила п''ять пакетів одягу.'::text),
(367458,40829,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando salieron del centro comercial, ella ya ... cinco bolsas de ropa.'::text,'había comprado'::text,'ha comprado'::text,'compra'::text,'Para cuando salieron del centro comercial, ella ya había comprado cinco bolsas de ropa.'::text),
(367457,40829,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le temps qu''ils quittent le centre commercial, elle ... cinq sacs de vêtements.'::text,'avait acheté'::text,'a acheté'::text,'achète'::text,'Le temps qu''ils quittent le centre commercial, elle avait acheté cinq sacs de vêtements.'::text),
(367460,40829,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alışveriş merkezinden çıktıklarında o çoktan beş poşet kıyafet ...'::text,'almıştı'::text,'aldı'::text,'alıyor'::text,'Alışveriş merkezinden çıktıklarında o çoktan beş poşet kıyafet almıştı.'::text),
(367461,40829,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire kijöttek a plázából, ő már öt szatyornyi ruhát ...'::text,'vett'::text,'vett'::text,'vesz'::text,'Mire kijöttek a plázából, ő már öt szatyornyi ruhát vett.'::text),
(367464,40830,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sie im Einkaufszentrum noch ein Kleid sieht, ... er noch mehr Tüten.'::text,'trägt'::text,'würde tragen'::text,'trug'::text,'Wenn sie im Einkaufszentrum noch ein Kleid sieht, trägt er noch mehr Tüten.'::text),
(367468,40830,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо вона побачить у торговому центрі ще одну сукню, він ... ще більше пакетів.'::text,'нестиме'::text,'ніс би'::text,'ніс'::text,'Якщо вона побачить у торговому центрі ще одну сукню, він нестиме ще більше пакетів.'::text),
(367467,40830,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si ella ve otro vestido en el centro comercial, él ... todavía más bolsas.'::text,'llevará'::text,'llevaría'::text,'llevó'::text,'Si ella ve otro vestido en el centro comercial, él llevará todavía más bolsas.'::text),
(367466,40830,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si elle voit une autre robe dans le centre commercial, il ... encore plus de sacs.'::text,'portera'::text,'porterait'::text,'a porté'::text,'Si elle voit une autre robe dans le centre commercial, il portera encore plus de sacs.'::text),
(367469,40830,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alışveriş merkezinde bir elbise daha görürse o daha da fazla poşet ...'::text,'taşıyacak'::text,'taşırdı'::text,'taşıdı'::text,'Alışveriş merkezinde bir elbise daha görürse o daha da fazla poşet taşıyacak.'::text),
(367470,40830,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha még egy ruhát meglát a plázában, ő még több szatyrot ...'::text,'fog cipelni'::text,'cipelne'::text,'cipelt'::text,'Ha még egy ruhát meglát a plázában, ő még több szatyrot fog cipelni.'::text),
(367473,40831,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn es im Einkaufszentrum keine Kleiderläden gäbe, ... er die Hände frei.'::text,'hätte'::text,'wird haben'::text,'hat'::text,'Wenn es im Einkaufszentrum keine Kleiderläden gäbe, hätte er die Hände frei.'::text),
(367477,40831,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби в торговому центрі не було магазинів суконь, у нього ... вільні руки.'::text,'були б'::text,'будуть'::text,'є'::text,'Якби в торговому центрі не було магазинів суконь, у нього були б вільні руки.'::text),
(367476,40831,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el centro comercial no tuviera tiendas de vestidos, él ... las manos libres.'::text,'tendría'::text,'tendrá'::text,'tiene'::text,'Si el centro comercial no tuviera tiendas de vestidos, él tendría las manos libres.'::text),
(367475,40831,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le centre commercial n''avait pas de boutiques de robes, il ... les mains libres.'::text,'aurait'::text,'aura'::text,'a'::text,'Si le centre commercial n''avait pas de boutiques de robes, il aurait les mains libres.'::text),
(367478,40831,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alışveriş merkezinde elbise dükkânı olmasaydı onun elleri boş ...'::text,'olurdu'::text,'olacak'::text,NULL::text,'Alışveriş merkezinde elbise dükkânı olmasaydı onun elleri boş olurdu.'::text),
(367479,40831,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a plázában nem lennének ruhaboltok, szabad ... a keze.'::text,'lenne'::text,'lesz'::text,NULL::text,'Ha a plázában nem lennének ruhaboltok, szabad lenne a keze.'::text),
(367482,40832,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Warte, angeblich ... jede Tüte auf dem Weg aus dem Einkaufszentrum von ihm getragen.'::text,'wurde'::text,'trug'::text,'wird'::text,'Warte, angeblich wurde jede Tüte auf dem Weg aus dem Einkaufszentrum von ihm getragen.'::text),
(367486,40832,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чекай, кажуть, кожен пакет на виході з торгового центру ... він.'::text,'ніс'::text,'ніс'::text,'несе'::text,'Чекай, кажуть, кожен пакет на виході з торгового центру ніс він.'::text),
(367485,40832,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Espera, al parecer cada bolsa ... por él al salir del centro comercial.'::text,'fue llevada'::text,'llevó'::text,'es llevada'::text,'Espera, al parecer cada bolsa fue llevada por él al salir del centro comercial.'::text),
(367484,40832,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Attends, apparemment chaque sac ... par lui à la sortie du centre commercial.'::text,'a été porté'::text,'a porté'::text,'est porté'::text,'Attends, apparemment chaque sac a été porté par lui à la sortie du centre commercial.'::text),
(367487,40832,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dur, güya alışveriş merkezinden çıkarken her poşet onun tarafından ...'::text,'taşınmış'::text,'taşımış'::text,'taşınıyor'::text,'Dur, güya alışveriş merkezinden çıkarken her poşet onun tarafından taşınmış.'::text),
(367488,40832,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Várj, állítólag minden szatyrot ő ... ki a plázából.'::text,'vitt'::text,'vitte'::text,'viszi'::text,'Várj, állítólag minden szatyrot ő vitt ki a plázából.'::text),
(367491,40833,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör mal, ich hab gehört, sie ... ihn direkt zum Kleiderladen im Einkaufszentrum.'::text,'zog'::text,'wurde gezogen'::text,'ziehend'::text,'Hör mal, ich hab gehört, sie zog ihn direkt zum Kleiderladen im Einkaufszentrum.'::text),
(367495,40833,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, я чула, що вона ... його просто до магазину суконь у торговому центрі.'::text,'потягла'::text,'була потягнута'::text,'тягнучи'::text,'Слухай, я чула, що вона потягла його просто до магазину суконь у торговому центрі.'::text),
(367494,40833,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, me han dicho que ella lo ... directo a la tienda de vestidos del centro comercial.'::text,'arrastró'::text,'fue arrastrada'::text,'arrastrando'::text,'Oye, me han dicho que ella lo arrastró directo a la tienda de vestidos del centro comercial.'::text),
(367493,40833,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, j''ai entendu dire qu''elle ... tout droit vers la boutique de robes du centre commercial.'::text,'l''a tiré'::text,'a été tirée'::text,'le tirant'::text,'Écoute, j''ai entendu dire qu''elle l''a tiré tout droit vers la boutique de robes du centre commercial.'::text),
(367496,40833,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, duydum ki onu doğruca alışveriş merkezindeki elbise dükkânına ...'::text,'sürüklemiş'::text,'sürüklenmiş'::text,'sürükleyerek'::text,'Dinle, duydum ki onu doğruca alışveriş merkezindeki elbise dükkânına sürüklemiş.'::text),
(367497,40833,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt hallottam, hogy egyenesen a pláza ruhaboltjába ... őt.'::text,'húzta'::text,'húzták'::text,'húzva'::text,'Figyelj, azt hallottam, hogy egyenesen a pláza ruhaboltjába húzta őt.'::text),
(367509,40835,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich gesagt, das Kleid, ... du in dem Einkaufszentrum gefunden hast, ist ikonisch.'::text,'das'::text,'wer'::text,'wo'::text,'Ehrlich gesagt, das Kleid, das du in dem Einkaufszentrum gefunden hast, ist ikonisch.'::text),
(367513,40835,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не брешу, сукня, ... ти знайшла в тому торговому центрі, — культова.'::text,'яку'::text,'хто'::text,'де'::text,'Не брешу, сукня, яку ти знайшла в тому торговому центрі, — культова.'::text),
(367512,40835,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No te voy a mentir, el vestido ... encontraste en ese centro comercial es icónico.'::text,'que'::text,'quien'::text,'donde'::text,'No te voy a mentir, el vestido que encontraste en ese centro comercial es icónico.'::text),
(367511,40835,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je vais pas mentir, la robe ... tu as trouvée dans ce centre commercial est iconique.'::text,'que'::text,'qui'::text,'où'::text,'Je vais pas mentir, la robe que tu as trouvée dans ce centre commercial est iconique.'::text),
(367514,40835,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalan yok, o alışveriş merkezinde ... elbise efsane.'::text,'bulduğun'::text,'kim'::text,'nerede'::text,'Yalan yok, o alışveriş merkezinde bulduğun elbise efsane.'::text),
(367515,40835,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem hazudok, a ruha, ... abban a plázában találtál, ikonikus.'::text,'amit'::text,'aki'::text,'ahol'::text,'Nem hazudok, a ruha, amit abban a plázában találtál, ikonikus.'::text),
(367518,40836,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er sagte, der Ausflug ins Einkaufszentrum ... nur zehn Minuten dauern. Eine makellose Prognose.'::text,'würde'::text,'wird'::text,'dauert'::text,'Er sagte, der Ausflug ins Einkaufszentrum würde nur zehn Minuten dauern. Eine makellose Prognose.'::text),
(367522,40836,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він сказав, що похід у торговий центр ... лише десять хвилин. Бездоганний прогноз.'::text,'триватиме'::text,'триватиме'::text,'триває'::text,'Він сказав, що похід у торговий центр триватиме лише десять хвилин. Бездоганний прогноз.'::text),
(367521,40836,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dijo que la visita al centro comercial ... solo diez minutos. Una predicción impecable.'::text,'duraría'::text,'durará'::text,'dura'::text,'Dijo que la visita al centro comercial duraría solo diez minutos. Una predicción impecable.'::text),
(367520,40836,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a dit que la virée au centre commercial ... seulement dix minutes. Une prédiction impeccable.'::text,'prendrait'::text,'prendra'::text,'prend'::text,'Il a dit que la virée au centre commercial prendrait seulement dix minutes. Une prédiction impeccable.'::text),
(367523,40836,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alışveriş merkezi gezisinin sadece on dakika ... söyledi. Kusursuz bir tahmin.'::text,'süreceğini'::text,'süreceğini'::text,'sürdüğünü'::text,'Alışveriş merkezi gezisinin sadece on dakika süreceğini söyledi. Kusursuz bir tahmin.'::text),
(367524,40836,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt mondta, a plázás kör ... csak tíz percig. Hibátlan jóslat.'::text,'tart majd'::text,'fog tartani'::text,'tart'::text,'Azt mondta, a plázás kör tart majd csak tíz percig. Hibátlan jóslat.'::text),
(367527,40837,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... früher gern ins Einkaufszentrum. Eindeutig tut er das immer noch.'::text,'ging'::text,'ging'::text,'war es gewohnt zu gehen'::text,'Er ging früher gern ins Einkaufszentrum. Eindeutig tut er das immer noch.'::text),
(367531,40837,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... походи в торговий центр. Явно й досі любить.'::text,'колись любив'::text,'любив'::text,'звик любити'::text,'Він колись любив походи в торговий центр. Явно й досі любить.'::text),
(367530,40837,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... disfrutar de las visitas al centro comercial. Claramente, todavía lo hace.'::text,'solía'::text,'solía'::text,'estaba acostumbrado a'::text,'Él solía disfrutar de las visitas al centro comercial. Claramente, todavía lo hace.'::text),
(367529,40837,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avant, il ... les virées au centre commercial. Clairement, c''est toujours le cas.'::text,'adorait'::text,'adorait'::text,'était habitué à adorer'::text,'Avant, il adorait les virées au centre commercial. Clairement, c''est toujours le cas.'::text),
(367532,40837,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eskiden alışveriş merkezi gezilerinden ..., belli ki hâlâ da hoşlanıyor.'::text,'hoşlanırdı'::text,'hoşlanırdı'::text,'hoşlanmaya alışkındı'::text,'Eskiden alışveriş merkezi gezilerinden hoşlanırdı, belli ki hâlâ da hoşlanıyor.'::text),
(367533,40837,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Régen ... a plázás körutakat. Nyilván most is.'::text,'élvezte'::text,'élvezte'::text,'hozzá volt szokva, hogy élvezze'::text,'Régen élvezte a plázás körutakat. Nyilván most is.'::text),
(367536,40838,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, sie kann nicht aufhören, ihn in jeden Laden dieser Mall ..., echt jetzt.'::text,'zu schleppen'::text,'zu schleppen'::text,'schleppen'::text,'Digga, sie kann nicht aufhören, ihn in jeden Laden dieser Mall zu schleppen, echt jetzt.'::text),
(367540,40838,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, вона не може перестати ... в кожен магазин цього торгового центру, реально.'::text,'тягати його'::text,'тягати його'::text,'тягати його'::text,'Бро, вона не може перестати тягати його в кожен магазин цього торгового центру, реально.'::text),
(367539,40838,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, no puede parar de ... a cada tienda de este centro comercial, en serio.'::text,'arrastrarlo'::text,'arrastrarlo'::text,'lo arrastra'::text,'Bro, no puede parar de arrastrarlo a cada tienda de este centro comercial, en serio.'::text),
(367538,40838,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, elle arrête pas de ... dans chaque boutique de ce centre commercial, sérieux.'::text,'le traîner'::text,'le traîner'::text,'le traîne'::text,'Frérot, elle arrête pas de le traîner dans chaque boutique de ce centre commercial, sérieux.'::text),
(367541,40838,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, onu bu AVM''deki her dükkâna ... duramıyor, cidden.'::text,'sürüklemeden'::text,'sürüklemek'::text,'sürükle'::text,'Kanka, onu bu AVM''deki her dükkâna sürüklemeden duramıyor, cidden.'::text),
(367542,40838,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, nem tudja abbahagyni, hogy ... minden boltba ebben a plázában, komolyan.'::text,'behúzza őt'::text,'behúzni őt'::text,'behúzza'::text,'Tesó, nem tudja abbahagyni, hogy behúzza őt minden boltba ebben a plázában, komolyan.'::text),
(343578,38176,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, stell dir das ... auf einem Court so weit oben vor, lowkey unreal.'::text,'Spielen'::text,'zu spielen'::text,'spielen'::text,'Digga, stell dir das Spielen auf einem Court so weit oben vor, lowkey unreal.'::text),
(343582,38176,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, уяви собі ... на корті так високо, це якось нереально.'::text,'гру'::text,'грати'::text,'грай'::text,'Бро, уяви собі гру на корті так високо, це якось нереально.'::text),
(343581,38176,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, imagínate ... en una pista tan alta, un poco irreal.'::text,'jugar'::text,'jugando'::text,'juega'::text,'Bro, imagínate jugar en una pista tan alta, un poco irreal.'::text),
(343580,38176,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, imagine ... sur un court aussi haut, un peu irréel quand même.'::text,'jouer'::text,'jouant'::text,'joue'::text,'Frérot, imagine jouer sur un court aussi haut, un peu irréel quand même.'::text),
(343583,38176,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bu kadar yüksekteki bir kortta ... hayal et, resmen gerçek dışı.'::text,'oynamayı'::text,'oynamak'::text,'oyna'::text,'Kanka, bu kadar yüksekteki bir kortta oynamayı hayal et, resmen gerçek dışı.'::text),
(343584,38176,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, képzeld el, hogy egy ilyen magasan lévő pályán ..., kicsit irreális.'::text,'játszol'::text,'játszani'::text,'játssz'::text,'Tesó, képzeld el, hogy egy ilyen magasan lévő pályán játszol, kicsit irreális.'::text),
(343587,38177,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, der Platz ist mit dem Berg dahinter schon krass, ...?'::text,'oder?'::text,'echt?'::text,'oder?'::text,'Yo, der Platz ist mit dem Berg dahinter schon krass, oder?'::text),
(343591,38177,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, цей корт із тією горою позаду якийсь божевільний, ...?'::text,'так?'::text,'справді?'::text,'так?'::text,'Йо, цей корт із тією горою позаду якийсь божевільний, так?'::text),
(343590,38177,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, esta pista es una locura con esa montaña detrás, ...?'::text,'¿no?'::text,'¿sí?'::text,'¿no?'::text,'Oye, esta pista es una locura con esa montaña detrás, ¿no?'::text),
(343589,38177,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wesh, ce court est un peu ouf avec cette montagne derrière, ... ?'::text,'non ?'::text,'ah bon ?'::text,'non ?'::text,'Wesh, ce court est un peu ouf avec cette montagne derrière, non ?'::text),
(343592,38177,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bu kort arkasındaki o dağla biraz çılgın, ...?'::text,'değil mi?'::text,'öyle mi?'::text,'değil mi?'::text,'Kanka, bu kort arkasındaki o dağla biraz çılgın, değil mi?'::text),
(343593,38177,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyu, ez a pálya elég őrült azzal a heggyel mögötte, ...?'::text,'nem?'::text,'tényleg?'::text,'nem?'::text,'Figyu, ez a pálya elég őrült azzal a heggyel mögötte, nem?'::text),
(343596,38178,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Spieler in Rot hat den Platz nie verlassen, und ... der Spieler auf der Kameraseite.'::text,'ebenso wenig'::text,'ebenso'::text,'ebenso wenig'::text,'Der Spieler in Rot hat den Platz nie verlassen, und ebenso wenig der Spieler auf der Kameraseite.'::text),
(343600,38178,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Гравець у червоному жодного разу не покинув корт, і ... гравець біля камери.'::text,'так само не покинув'::text,'так само покинув'::text,'так само не був'::text,'Гравець у червоному жодного разу не покинув корт, і так само не покинув гравець біля камери.'::text),
(343599,38178,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El jugador de rojo nunca salió de la pista, y ... el jugador del lado de la cámara.'::text,'tampoco salió'::text,'también salió'::text,'tampoco estaba'::text,'El jugador de rojo nunca salió de la pista, y tampoco salió el jugador del lado de la cámara.'::text),
(343598,38178,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le joueur en rouge n''a jamais quitté le court, et le joueur côté caméra ...'::text,'non plus'::text,'aussi'::text,'n''était pas non plus'::text,'Le joueur en rouge n''a jamais quitté le court, et le joueur côté caméra non plus.'::text),
(343601,38178,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kırmızılı oyuncu kortu hiç terk etmedi, kameranın olduğu taraftaki oyuncu ...'::text,'da etmedi'::text,'da etti'::text,'da değildi'::text,'Kırmızılı oyuncu kortu hiç terk etmedi, kameranın olduğu taraftaki oyuncu da etmedi.'::text),
(343602,38178,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A piros ruhás játékos sosem hagyta el a pályát, és a kamera felőli játékos ...'::text,'sem'::text,'is'::text,'sem volt'::text,'A piros ruhás játékos sosem hagyta el a pályát, és a kamera felőli játékos sem.'::text),
(343605,38179,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Spieler ... schon eine Stunde auf dem Platz gespielt, bevor jemand anderes kam.'::text,'hatten'::text,'haben'::text,'spielten'::text,'Die Spieler hatten schon eine Stunde auf dem Platz gespielt, bevor jemand anderes kam.'::text),
(343609,38179,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Гравці ... на корті годину, перш ніж хтось іще прийшов.'::text,'грали'::text,'грають'::text,'грали'::text,'Гравці грали на корті годину, перш ніж хтось іще прийшов.'::text),
(343608,38179,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los jugadores ... una hora en la pista antes de que llegara nadie más.'::text,'llevaban jugando'::text,'llevan jugando'::text,'estaban jugando'::text,'Los jugadores llevaban jugando una hora en la pista antes de que llegara nadie más.'::text),
(343607,38179,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les joueurs ... sur le court depuis une heure avant que quelqu''un d''autre arrive.'::text,'jouaient'::text,'jouent'::text,'jouaient'::text,'Les joueurs jouaient sur le court depuis une heure avant que quelqu''un d''autre arrive.'::text),
(343610,38179,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Başka biri gelmeden önce oyuncular bir saattir kortta ...'::text,'oynuyordu'::text,'oynuyor'::text,'oynuyordu'::text,'Başka biri gelmeden önce oyuncular bir saattir kortta oynuyordu.'::text),
(343611,38179,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A játékosok már egy órája ... a pályán, mielőtt bárki más megérkezett.'::text,'játszottak'::text,'játszanak'::text,'játszottak'::text,'A játékosok már egy órája játszottak a pályán, mielőtt bárki más megérkezett.'::text),
(343614,38180,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis Sonnenuntergang ... die Spieler etwa zweihundert Schläge über den Platz gespielt.'::text,'haben'::text,'werden'::text,'werden gerade'::text,'Bis Sonnenuntergang haben die Spieler etwa zweihundert Schläge über den Platz gespielt.'::text),
(343618,38180,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До заходу сонця гравці ... через корт приблизно двісті ударів.'::text,'зроблять'::text,'зроблять'::text,'робитимуть'::text,'До заходу сонця гравці зроблять через корт приблизно двісті ударів.'::text),
(343617,38180,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para la puesta de sol, los jugadores ... aproximadamente doscientos golpes de un lado a otro de la pista.'::text,'habrán dado'::text,'darán'::text,'estarán dando'::text,'Para la puesta de sol, los jugadores habrán dado aproximadamente doscientos golpes de un lado a otro de la pista.'::text),
(343616,38180,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici le coucher du soleil, les joueurs ... environ deux cents coups à travers le court.'::text,'auront frappé'::text,'frapperont'::text,'seront en train de frapper'::text,'D''ici le coucher du soleil, les joueurs auront frappé environ deux cents coups à travers le court.'::text),
(343619,38180,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gün batımına kadar oyuncular kort boyunca yaklaşık iki yüz vuruş ...'::text,'yapmış olacak'::text,'yapacak'::text,'yapıyor olacak'::text,'Gün batımına kadar oyuncular kort boyunca yaklaşık iki yüz vuruş yapmış olacak.'::text),
(343620,38180,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Napnyugtáig a játékosok körülbelül kétszáz ütést ... a pályán át.'::text,'fognak leadni'::text,'adnak le'::text,'fognak leadni'::text,'Napnyugtáig a játékosok körülbelül kétszáz ütést fognak leadni a pályán át.'::text),
(343623,38181,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis Mittag ... sie schon fünf Stunden auf diesem Platz. Dieser Ballwechsel hört nie auf!'::text,'spielen'::text,'spielen'::text,'spielen'::text,'Bis Mittag spielen sie schon fünf Stunden auf diesem Platz. Dieser Ballwechsel hört nie auf!'::text),
(343627,38181,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До полудня вони ... на цьому корті п''ять годин. Цей розіграш ніколи не закінчиться!'::text,'гратимуть'::text,'гратимуть'::text,'гратимуть'::text,'До полудня вони гратимуть на цьому корті п''ять годин. Цей розіграш ніколи не закінчиться!'::text),
(343626,38181,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para el mediodía, ... cinco horas en esta pista. ¡Este peloteo no va a terminar nunca!'::text,'llevarán jugando'::text,'estarán jugando'::text,'jugarán'::text,'Para el mediodía, llevarán jugando cinco horas en esta pista. ¡Este peloteo no va a terminar nunca!'::text),
(343625,38181,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici midi, ils ... sur ce court depuis cinq heures. Cet échange ne finira jamais !'::text,'joueront'::text,'joueront'::text,'joueront'::text,'D''ici midi, ils joueront sur ce court depuis cinq heures. Cet échange ne finira jamais !'::text),
(343628,38181,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Öğlene kadar bu kortta beş saattir ...; bu ralli asla bitmeyecek!'::text,'oynuyor olacaklar'::text,'oynuyor olacaklar'::text,'oynayacaklar'::text,'Öğlene kadar bu kortta beş saattir oynuyor olacaklar; bu ralli asla bitmeyecek!'::text),
(343629,38181,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Délre már öt órája ... ezen a pályán. Ez a labdamenet sosem ér véget!'::text,'játszanak majd'::text,'fognak játszani'::text,'játszanak'::text,'Délre már öt órája játszanak majd ezen a pályán. Ez a labdamenet sosem ér véget!'::text),
(343632,38182,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn es geregnet hätte, ... der Sandplatz zu nass für ein Spiel gewesen.'::text,'wäre'::text,'wäre'::text,'war'::text,'Wenn es geregnet hätte, wäre der Sandplatz zu nass für ein Spiel gewesen.'::text),
(343636,38182,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби пішов дощ, ґрунтовий корт ... надто мокрим для гри.'::text,'був би'::text,'був би'::text,'був'::text,'Якби пішов дощ, ґрунтовий корт був би надто мокрим для гри.'::text),
(343635,38182,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si hubiera llovido, la pista de tierra batida ... demasiado mojada para jugar.'::text,'habría estado'::text,'estaría'::text,'estaba'::text,'Si hubiera llovido, la pista de tierra batida habría estado demasiado mojada para jugar.'::text),
(343634,38182,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il avait plu, le court en terre battue ... trop mouillé pour jouer.'::text,'aurait été'::text,'serait'::text,'était'::text,'S''il avait plu, le court en terre battue aurait été trop mouillé pour jouer.'::text),
(343637,38182,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yağmur yağsaydı toprak kort maç için fazla ıslak ...'::text,'olurdu'::text,'olurdu'::text,'idi'::text,'Yağmur yağsaydı toprak kort maç için fazla ıslak olurdu.'::text),
(343638,38182,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha esett volna, a salakpálya túl nedves ... a játékhoz.'::text,'lett volna'::text,'lenne'::text,'volt'::text,'Ha esett volna, a salakpálya túl nedves lett volna a játékhoz.'::text),
(343641,38183,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sie hier oben keinen Platz gebaut hätten, ... dieser Berg jetzt leer.'::text,'wäre'::text,'wäre gewesen'::text,'wird sein'::text,'Wenn sie hier oben keinen Platz gebaut hätten, wäre dieser Berg jetzt leer.'::text),
(343645,38183,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби тут нагорі не побудували корт, ця гора ... зараз порожньою.'::text,'була б'::text,'була б'::text,'буде'::text,'Якби тут нагорі не побудували корт, ця гора була б зараз порожньою.'::text),
(343644,38183,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si no hubieran construido una pista aquí arriba, esta montaña ... vacía ahora.'::text,'estaría'::text,'habría estado'::text,'estará'::text,'Si no hubieran construido una pista aquí arriba, esta montaña estaría vacía ahora.'::text),
(343643,38183,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''ils n''avaient pas construit de court ici, cette montagne ... vide maintenant.'::text,'serait'::text,'aurait été'::text,'sera'::text,'S''ils n''avaient pas construit de court ici, cette montagne serait vide maintenant.'::text),
(343646,38183,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Buraya bir kort yapmasalardı bu dağ şimdi boş ...'::text,'olurdu'::text,'olmuş olurdu'::text,'olacak'::text,'Buraya bir kort yapmasalardı bu dağ şimdi boş olurdu.'::text),
