(340749,37861,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az építő feltehetően kézzel ... a köveket, mielőtt a szerkezet összeomlott.'::text,'rakatta ki'::text,'kirakni'::text,'kirakni'::text,'Az építő feltehetően kézzel rakatta ki a köveket, mielőtt a szerkezet összeomlott.'::text),
