(340756,37862,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Будівельник, імовірно, хотів би, щоб споруда ... після фото, а не до нього.'::text,'обвалилася'::text,'обвалилася'::text,'обвалилася'::text,'Будівельник, імовірно, хотів би, щоб споруда обвалилася після фото, а не до нього.'::text),
