(340773,37864,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La figura de piedra se derrumbó ... no había viento en la playa.'::text,'aunque'::text,'a pesar de'::text,'para que'::text,'La figura de piedra se derrumbó aunque no había viento en la playa.'::text),
