(340781,37865,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le constructeur savait que la figure ... tôt ou tard, alors il l''a filmée.'::text,'s''effondrerait'::text,'s''effondrera'::text,'s''effondre'::text,'Le constructeur savait que la figure s''effondrerait tôt ou tard, alors il l''a filmée.'::text),
