(340799,37867,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La figure ... seulement quelques secondes avant de s''effondrer. Un vrai chef-d''œuvre.'::text,'avait tenu'::text,'a tenu'::text,'tient'::text,'La figure avait tenu seulement quelques secondes avant de s''effondrer. Un vrai chef-d''œuvre.'::text),
(340802,37867,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figür çökmeden önce yalnızca birkaç saniye ayakta ..., gerçek bir başyapıt.'::text,'durmuştu'::text,'durdu'::text,'duruyor'::text,'Figür çökmeden önce yalnızca birkaç saniye ayakta durmuştu, gerçek bir başyapıt.'::text),
(340803,37867,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A figura csak néhány másodpercig ..., mielőtt összeomlott. Igazi mestermű.'::text,'állt'::text,'állt'::text,'áll'::text,'A figura csak néhány másodpercig állt, mielőtt összeomlott. Igazi mestermű.'::text),
(340806,37868,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, bis morgen ... die Flut den ganzen eingestürzten Haufen weggespült, kein Witz.'::text,'hat'::text,'spült'::text,'spült'::text,'Digga, bis morgen hat die Flut den ganzen eingestürzten Haufen weggespült, kein Witz.'::text),
(340810,37868,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, до завтра приплив ... всю цю обвалену купу, без брехні.'::text,'змиє'::text,'змиє'::text,'змиває'::text,'Бро, до завтра приплив змиє всю цю обвалену купу, без брехні.'::text),
